                                "StemSizeFrom", "StemSizeTo", "StemType", "StemColor", "CapType", "CapColor",
                                "CapUndersideType", "Description", "HeaderPhotoLink", "ExtraPhotoLinks")
VALUES
('712a071a-da74-5608-a523-a7acd8feacad', 'Свинушка тонкая', 'Коровник, Матрёшка , Кобылка, Свинух, Свинарь, Свинорой, Свиное ухо', NULL, 'Свинушковые', false, 'Неизвестно', true, 10, 15, 'Утолщенная вверху', 'Бело-жёлтая', 'Вогнутая', 'Оливково-бурая, охристо-бурая, рыжеватая, ржавая', 'Пластинчатая', 'Растёт в лиственных и хвойных лесах, чаще всего в молодых березняках, дубняках и кустарниках, по окраинам оврагов и сфагновых болот, на опушках около полян, а также около замшелых оснований елей и сосен, на корнях вывороченных деревьев. Встречается на влажной почве часто и обильно группами, реже одиночно. Плодоносит с июня по октябрь.', '/media/mushrooms/placeholder.webp', NULL),
('31cfb54c-382c-5ef8-b7cb-9c33494abcad', 'Жёлчный гриб', 'Горчак, Ложный белый гриб, Ложный подберёзовик, Гриб заячья губа, Тилопилус горький', NULL, 'Болетовые', true, 'Неизвестно', true, 10, 40, 'Утолщенная внизу', 'Кремово-охристая, желтоватая, желтовато-бурая', 'Выпуклая', 'Бежевый, светло-каштановый, буровато-коричневый', 'Трубчатая', 'Вид широко распространен по всему миру. Отмечен в Северной Америке, Европе, Азии, Центральной Америке, Австралии, на острове Гренландия. Период плодоношения с июня по октябрь. Растёт в хвойных и смешанных сырых лесах, на почве, часто у оснований стволов деревьев, на покрытых мхом корнях, около гнилых пней или на них, на гниющем валеже хвойных деревьев, на старых муравейниках. Жёлчный гриб несъедобен из-за горького вкуса.', '/media/mushrooms/placeholder.webp', NULL),
('d992653a-c29a-5d85-9ca6-87ba76850eb7', 'Рядовка лиловоногая', 'Рядовка лиловоножковая, Рядовка двухцветная, Синеножка, Подотавник', NULL, 'Рядовковые', false, 'Неизвестно', true, 20, 30, 'Ровная', 'Серовато-фиолетовый, голубоватый', 'Выпуклая', 'Серо-фиолетовый, серый, серо-коричневый, белый', 'Пластинчатая', 'Рядовка лиловоногая принадлежит к категории южных грибов. Иногда его находят и в Подмосковье, Рязанской области. В целом распространён по всей территории России. Активное плодоношение приходится на период с середины весны и до середины осени. Эти грибы растут колониями, образуя большие круги или ряды. Синеножки также любят гумусные почвы, поэтому их часто можно встретить около ферм, в старых ямах с компостом и вблизи жилых домов. Этот вид грибов предпочитает расти на открытой местности, но иногда лиловоногие рядовки встречают и в лесу. Часто такие грибы находят около лиственных пород деревьев. Синеножка пригодна для употребления в пищу.', '/media/mushrooms/placeholder.webp', NULL),
('9d691de5-c802-5e71-8962-d5129e90d932', 'Рядовка тополёвая', 'Тополёвка, Песочник тополевый, Песчаник, Рядовка тополиная, Подтополевик, Подтопольник', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Розовато-белый, розовато-коричневый', 'Выпуклая', 'Розовато-коричневатый', 'Пластинчатая', 'Рядовка тополёвая растёт с августа по октябрь большими группами (целые гряды) под тополями, лиственных лесах с преобладанием осины, можно встретить в посадках вдоль дорог, в парках. Распространены в Европейской части России, Сибири. Гриб имеет приятный аромат свежей муки. По своим вкусовым и потребительским качествам, рядовка тополёвая соотносится к съедобным грибам.', '/media/mushrooms/placeholder.webp', NULL),
('3f934c41-6ba9-5671-8488-94ad1ea06faa', 'Рамария жёлтая', 'Рогатик жёлтый, Медвежья лапка, Оленьи рожки, Коралл жёлтый', NULL, 'Гомфовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Жёлтый, белый', 'Гладкая', 'Рамария жёлтая растет на земле в лиственных, хвойных и смешанных лесах в августе — сентябре, группами и одиночно. Особенно обилен в лесах Карелии. Встречается в горах Кавказа, а так же в странах Центральной Европы. Эта рамария считается съедобным грибом, но при употреблении ее в пищу необходимо принимать определенные меры предосторожности. Прежде всего, собирать следует только молодые экземпляры и использовать основание, так как веточки горчат. Зрелые грибы и вовсе не съедобны из-за горечи.', '/media/mushrooms/placeholder.webp', NULL),
('01beed2f-e2b2-50a0-8104-a2dde8b36b3f', 'Опёнок осенний', 'Опёнок настоящий', NULL, 'Физалакриевые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Желтовато-коричневатый, желтый, оранжевый, оливковый, серый', 'Выпуклая', 'Желтовато-коричневатый, желтый, оранжевый, оливковый, серый', 'Пластинчатая', 'Плодоносит со второй половины июля, и до конца осени на древесине любых видов, в том числе, и находящейся под землей, сростками и семьями, вплоть до очень значительных. Основной слой, как правило, проходит с конца августа и до третьей декады сентября, длится недолго, 5-7 дней. В остальное время плодоношение локально, однако, можно найти в таких локальных точках довольно значительное количество плодовых тел.', '/media/mushrooms/placeholder.webp', NULL),
('6f6f869a-0675-5449-8765-a22568de2f87', 'Колпак кольчатый', 'Курочка, Приболотник белый, Приболотух, Турок, турка), Розитес тусклый, Опёнок морщинистый, Паутинник сморщенный', NULL, 'Паутинниковые', true, 'Неизвестно', true, 10, 30, 'С юбкой', 'Беловатый, желтоватый, светло-охристый', 'Выпуклая', 'Беловатый, желтоватый, светло-охристый, розоватый', 'Пластинчатая', 'Довольно распространённый вид, встречается в Северной Америке, Европе и Азии. Отмечен в США, Японии, Гренландии, европейских странах, Беларуси, в западных и центральных районах европейской части России, центральном и южном Урале, Сибири, на Дальнем Востоке. Довольно распространённый вид, встречается в Северной Америке, Европе и Азии. Отмечен в США, Японии, Гренландии, европейских странах, Беларуси, в западных и центральных районах европейской части России, центральном и южном Урале, Сибири, на Дальнем Востоке. Съедобный вкусный гриб 4-й категории.', '/media/mushrooms/placeholder.webp', NULL),
('5dcf966f-1ef4-5929-a4e0-1d247b5a721d', 'Козляк', 'Решетняк, Маслёнок сухой, Козлёнок, Иванчик, Коровик, Коровий гриб, Коровий хлеб, Коровяк, Моховик', NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Желтоватый, буроватый, телесный, желтовато-охристый, бежевый', 'Выпуклая', 'Телесный, желтовато-охристый, бежевый, оранжево-коричневый, желто-бурый, светло-бурый, розоватый', 'Трубчатая', 'Отмечен в Северной и Южной Америке, Африке, Азии. Широко распространён в умеренной климатической зоне Евразии, тяготеет к северным регионам. Встречается в Европе, Беларуси, Украине, европейской части России, Сибири, на Урале, Дальнем Востоке, Северном Кавказе. На территории СНГ плодоносит с июля по октябрь. Образует микоризу с двухвойными соснами: сосна обыкновенная, сосна густоцветковая, сосна приморская. Предпочитает кислые питательные увлажнённые почвы. Тяготеет к местам с нарушенным местообитаниям: растёт на песчаных обочинах лесных дорог и тропинок, зарастающих сосной пустырях с песчаной почвой, засаженных сосной вырубках, на сфагновых болотах и, конечно же, в лесах с преобладанием сосны. Встречается часто, как правило, большими группами, часто может расти кучей плотно друг к другу. Съедобный вкусный гриб 4-й категории.', '/media/mushrooms/placeholder.webp', NULL),
('a9274666-fa81-571e-a779-208d0da1f5cf', 'Дождевик съедобный', 'Дождевик, Дождевик настоящий, Дождевик шиповатый, Дождевик жемчужный', NULL, 'Шампиньоновые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Белый', 'Гладкая', 'У молодого гриба плодовое тело шиповато-бородавчатое, белое. У зрелых грибов, становится бурым, охристым и голым. Дождевик съедобный встречается в хвойных и лиственных лесах с июня по ноябрь. Малоизвестный съедобный вкусный гриб. Дождевики и пылевики съедобны, пока не потеряют белизну. В пищу употребляют молодые плодовые тела', '/media/mushrooms/placeholder.webp', NULL),
('1bbd76b4-86ea-5263-91e9-97b1c71adb39', 'Подберёзовик', 'Подберёзовик обыкновенный, Берёзовик, Обабок, Обабок берёзовый', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 30, 'Утолщенная внизу', 'Бело-серый, оливково-бурый', 'Выпуклая', 'Светло-серый, темно-коричневый', 'Гладкая', 'Подберёзовик произрастает с начала лета до поздней осени в лиственных (предпочтительно березовых) и смешанных лесах, в некоторые годы весьма обильно. В удивительных количествах встречается порой в еловых посадках с вкраплением березы. Дает хорошие урожаи и в совсем молодых березняках, появляясь там едва ли не первым среди промысловых грибов. Относится к съедобным грибам. У пожилых грибов трубчатый слой надо удалять.', '/media/mushrooms/placeholder.webp', NULL),
('2228bcfe-2586-5298-a121-fb0ca318bf25', 'Рядовка серая', 'Рядовка штриховатая, Рядовка странная, Подсосновик, Подзелёнка, Песочник серый, Серушка', NULL, 'Рядовковые', false, 'Неизвестно', true, 15, 25, 'Утолщенная в центре', 'Белая, сероватая, серовато-желтоватая, светло-лимонно-жетловатая', 'Выпуклая', 'Светло-серый, желтоватый, зеленоватый', 'Пластинчатая', 'Плодоносит с осени и вплоть до зимних морозов. При небольшом промерзании полностью восстанавливает вкусовые качества. Ранее указывалось, что Рядовка серая растёт преимущественно в южных регионах (Крым, Новороссийск, Мариуполь), однако её регион значительно шире, она встречается во всей умеренной зоне. Отмечена в Западной Сибири. Плодоносит неравномерно, часто большими группами. Хороший съедобный гриб, употребляется после термической обработки.', '/media/mushrooms/placeholder.webp', NULL),
('df6b9930-1ef5-50ad-b1fe-d62cc7f63768', 'Рядовка землисто-серая', 'Мышата, Рядовка землистая, Рядовка напочвенная', NULL, 'Рядовковые', false, 'Неизвестно', true, 15, 20, 'Ровная', 'Белый', 'Выпуклая', 'Пепельно-серый, сероватый, мышино-серый, тёмно-серый, коричневато-серый', 'Пластинчатая', 'Поздний гриб. Распространён во всей умеренной зоне. Плодоносит с октября и вплоть до сильных морозов. В южных регионах, в частности, в Крыму, в тёплые зимы — до января, и даже в феврале-марте. В восточном Крыму в отдельные годы — в мае. До недавнего времени Рядовка землистая считалась хорошим съедобным грибом. «Мышата» в Крыму — один из самых распространённых и самых популярных, собираемых грибов, можно сказать, «кормилец». Их сушат, маринуют, солят, приготавливают в свежем виде. Однако в последние годы был проведен ряд исследований, показавших, что употребление землисто-серой рядовки может вызвать рабдомиолиз (миоглобинурия) — довольно сложный в диагностике и лечении синдром, представляющий собой крайнюю степень миопатии и характеризующийся разрушением клеток мышечной ткани, резким повышением уровня креатинкиназы и миоглобина, миоглобинурией, развитием острой почечной недостаточности.', '/media/mushrooms/placeholder.webp', NULL),
('15ae5b88-491c-5309-870a-332c7acfcf59', 'Горькушка', 'Горькушка рыжая, Груздь горький, Горчак, Горянка', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белесоватый, розоватый, ржаво-красный', 'Вогнутая', 'Белесоватый, розоватый, ржаво-красный', 'Пластинчатая', 'Растет Горькушка в хвойных и смешанных лесах Европейской части России, предпочитая болотистую местность, мох и сосновые леса. Период плодоношения приходится на летние и осенние месяцы вплоть до ноября. Выдерживает заморозки до -5°C. Горькушка - условно-съедобный гриб, часто относят к четвертой категории. Этот гриб содержит антибиотическое вещество, отрицательно воздействующее на ряд бактерий, а также тормозящее рост культур золотистого стафилококка.', '/media/mushrooms/placeholder.webp', NULL),
('afd94fe5-8f56-5ced-a14a-b63afaac723e', 'Рядовка зелёная', 'Зеленушка, Зелёнка, Песочник зелёный', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Жёлтый, зеленоватый', 'Выпуклая', 'Зеленовато-желтый, желто-оливковый, буроватый', 'Пластинчатая', 'Рядовка зелёная растет в основном в сухих сосновых лесах, иногда попадается и в смешанных на песчаной и супесчаной почве, встречается по одному и в группе по 5-8 штук. Может расти по соседству с похожей на него рядовкой серой. Наиболее часто попадается на открытой почве в сосновых борах, когда другие грибы уже закончили плодоношение, в период с сентября по ноябрь до самых заморозков. Гриб обычен в умеренной зоне Северного полушария. Рядовка зелёная относится к условно-съедобным грибам, заготавливается и употребляется в пищу в любом виде.', '/media/mushrooms/placeholder.webp', NULL),
('bc711d42-455a-508b-8dca-0340ed1463ac', 'Белый гриб', 'Боровик, Белый гриб еловый, Жатник, Струень, Панг, Печура', NULL, 'Болетовые', false, 'Неизвестно', true, 15, 50, 'Утолщенная внизу', 'Белый, кремовый, светло-коричневый', 'Выпуклая', 'Лимонно-жёлтый, белый, охристый, грязно-жёлтый, жёлто-коричневый', 'Трубчатая', 'Белый гриб распространен по всей планете Земля. Единственное место, где он не отмечен – это Антарктида. Период плодоношения на территории стран СНГ с июня по ноябрь. Отмечаются случаи нахождения грибов в мае и декабре в регионах с боле тёплым климатом. Плодоносит так называемыми «волнами» (в начале июня, в середине июля, в августе и пр.). Первая волна, как правило, не слишком обильная, в то время как одна из последующих волн зачастую бывает несравнимо более урожайная, чем остальные. Это зависит от климатических и природных условий каждого конкретного региона. Растёт в хвойных, лиственных и смешанных лесах, образует микоризу с более чем 50 древесными породами, наиболее часто встречается в симбиозе с берёзой, елью, дубом, сосной, грабом, буком. Предпочитает не переувлажнённые суглинистые, супесчаные и песчаные почвы, поэтому в болотистых местах и на торфяниках расти не любит. Встречается одиночно, группами, большими группами.', '/media/mushrooms/placeholder.webp', NULL),
('d6b8183b-d7c8-5105-b18e-15ce51dbca6e', 'Шампиньон обыкновенный', 'Шампиньон настоящий, Шампиньон луговой, Печерица', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 20, 'С юбкой', 'Буроватый, ржавый', 'Выпуклая', 'Коричневатый, белый, буроватый, розоватый', 'Пластинчатая', 'Шампиньон обыкновенный растет с самого конца мая до конца сентября на открытых пространствах с богатыми перегнойными почвами, особенно после дождей, на лугах, пастбищах, в садах, огородах, парках, около ферм, на окультуренных землях, около жилья, на улицах, в траве, реже на опушках леса, группами, кольцами, часто, ежегодно. Широко распространен. Вкусный, полезный, съедобный гриб 2 категории.', '/media/mushrooms/placeholder.webp', NULL),
('867fa6ae-ac45-505c-94dd-62b67c07f40d', 'Ложноопёнок серно-жёлтый', 'Опёнок серно-жёлтый', NULL, 'Строфариевые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Светло-желтый', 'Выпуклая', 'Желтоватый, желто-бурый, серно-желтый', 'Пластинчатая', 'Ложноопёнок серно-жёлтый повсеместно встречается с конца мая до поздней осени на гниющей древесине, на пнях и на земле около пней, иногда на стволах живых деревьев. Предпочитает лиственные породы, но изредка может встречаться и на хвойных. Как правило, растет большими группами. Ложноопёнок серно-жёлтый ядовит. При употреблении в пищу через 1-6 ч появляются тошнота, рвота, потливость, человек теряет сознание.', '/media/mushrooms/placeholder.webp', NULL),
('5c9be0af-0554-5eb4-9928-2f1747739065', 'Дубовик обыкновенный', 'Дубовик, Дубовик оливково-бурый, Поддубник, Синяк, Болет грязно-бурый', NULL, 'Болетовые', false, 'Неизвестно', true, 30, 60, 'Утолщенная внизу', 'Желтоватый, красноватый', 'Выпуклая', 'Желтовато-коричневый, серо-бурый', 'Трубчатая', 'Дубовик встречается повсеместно, но не особо часто, в лиственных и смешанных лесах, образуя микоризу с дубами и липами. По литературным данным, начинает расти уже в конце мая-начале июня, затем на время пропадает, чтобы появиться вновь в начале августа и стабильно плодоносить до конца сентября. Хороший съедобный гриб, быть может, похуже белого, но лучше большинства других.', '/media/mushrooms/placeholder.webp', NULL),
('74be7827-2928-5f11-86c6-19b65222cd51', 'Гиропорус каштановый', 'Каштановый гриб, Каштановик, Заячий гриб', NULL, 'Гиропоровые', false, 'Неизвестно', true, 8, 30, 'Ровная', 'Красно-бурый', 'Ровная', 'Ржаво-бурый, красно-бурый, каштаново-бурый', 'Гладкая', 'Растет каштановый гриб с июля по ноябрь в лиственных и хвойных лесах. Чаще всего растет на песчаной почве в теплых сухих областях. Плодовые тела растут одиночно, разбросано. Малоизвестный съедобный гриб, но по вкусовым качествам его нельзя сравнить с Гиропорусом синеющим. При варке приобретает горьковатый вкус. При сушке горечь исчезает. Поэтому каштановик годится главным образом для сушки.', '/media/mushrooms/placeholder.webp', NULL),
('379c2c3b-13be-592a-a140-fbed08d99687', 'Энтолома садовая', 'Розовопластинник щитовидный, Энтолома съедобная, Энтолома щитовидная, Энтолома щитковая, Энтолома терновниковая, Энтолома лесная, Подсливник, Подабрикосовик, Поджердельник', NULL, 'Энтоломовые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Беловатый, розоватый, сероватый', 'Выпуклая', 'Беловато-серый, бежеватый и серо-буроватый, серо-коричневый', 'Пластинчатая', 'Энтолома садовая растет в лиственных и смешанных лесах под рябиной, березами и дубами – на богатой питательными веществами почве, вдоль дорог, на лугах, в садах и на городских газонах. В саду часто растет под плодовыми деревьями (яблоня и груша) и кустами розы, шиповника, боярышника и терновника. Распространена и обычна на территории Ленинградской области и в Санкт- Петербурге, хотя и растет точечно – с последней пятидневки мая до конца июля с наиболее массовым плодоношением в июне и во влажное, прохладное лето – и в июле. Зачастую дает не один, а несколько коротких слоев. Энтолома садовая редко появляется в одиночку, обычно растет группами, нередко — большими. Это условно-съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('fadbaaa2-d8ea-573c-a2b9-6e6c4268034a', 'Подосиновик красный', 'Красноголовик, обабок, осиновик, лекцинум', NULL, 'Болетовые', false, 'Неизвестно', true, 15, 50, 'Утолщенная внизу', 'Серовато-белый', 'Выпуклая', 'Красный, оранжевый, буровато-красный', 'Трубчатая', 'Красноватая шляпка, коренастая ножка с серо-бурыми чешуйками и плотная мякоть - отличительные особенности подосиновика. Твердая губчатая мякоть становится темно синей при надавливании или срезе, а через некоторое время и вовсе чернеет. Все виды подосиновиков съедобны, практически не имеют запаха, по вкусовым качествам сравнимы с белыми грибами. Обнаружить плодовые тела, которые растут небольшими группками по 2-5 штук или поодиночке, можно как в смешанных, так и сосновых лесах в тени деревьев.', '/media/mushrooms/placeholder.webp', NULL),
('4b20d518-b534-5515-91c8-f690a8cb9e9b', 'Гиропорус синеющий', 'Болетус синеющий, синяк', NULL, 'Гиропоровые', true, 'Неизвестно', true, 10, 30, 'Утолщенная в центре', 'Синий', 'Выпуклая', 'Синий', 'Трубчатая', 'Народное название «Синяк» точно передаёт поведение гриба при малейшем повреждении тканей, будь то разрез, разлом или просто прикосновение: он синеет. Изменение цвета происходит быстро и очень явно, что позволяет почти безошибочно отличить Гиропорус синеющий от других болетовых.', '/media/mushrooms/placeholder.webp', NULL),
('fe500794-d0f3-5d19-9b92-0e9e077b25a6', 'Навозник белый', 'Чернильный гриб', NULL, 'Коприновые', false, 'Неизвестно', true, 10, 20, 'С юбкой', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Шляпка высотой до 5—15, иногда до 20 см, 5—10 см в диаметре, у молодого гриба удлинённо-яйцевидная, потом узкоколокольчатая. Цвет белый, сероватый или коричневатый, на верхушке широкий коричневый бугорок. Поверхность густо покрыта волокнистыми чешуйками. Мякоть белая, мягкая, тонкомясистая, без особого вкуса и запаха. Пластинки свободные, широкие, очень частые. Цвет их у молодых грибов белый, затем снизу начинают розоветь, позже расплываются вместе со шляпкой в чёрную жидкость (автолиз), в которой присутствуют многочисленные споры. Ножка 10—35 см высотой, 1—2 см в диаметре, центральная, цилиндрическая, белая, с шелковистым отливом, полая. В основании заметно луковицевидное утолщение. Остатки покрывал: кольцо плёнчатое, очень нежное, подвижное, у молодых грибов белое, после начала автолиза окрашивается в чёрный цвет. Споровый порошок чёрный, споры 12×8 мкм, эллипсоидальные, с порой.', '/media/mushrooms/placeholder.webp', NULL),
('c857dd3c-bfe1-5671-a158-3431374beb60', 'Маслёнок желто-бурый', 'Маслёнок пёстрый, моховик болотный, моховик песчаный, моховик желто-бурый, болотовик, пестрец', NULL, 'Масленковые', false, 'Неизвестно', true, 20, 35, 'Ровная', 'Лимонно-желтая, желто-бурая, оранжево-бурая, красноватая', 'Выпуклая', 'Серо-желтая, серо-оранжевая, буро-красноватая, светло-охряная', 'Трубчатая', 'Диаметр шляпки составляет 6—10 см, шляпка имеет полукруглую, выпуклую, в молодости с завёрнутым краем, позже подушковидную или плоскую форму, с волокнистыми чешуйками, цвет шляпки — оливковый, тёмно-жёлтый или серо-жёлтый, серо-оранжевый, позже охряно-бурый, буро-красноватый, светло-охряный. Во влажную погоду шляпка становится слегка клейкой. Кожица плохо отделяется от шляпки. Мякоть желтоватая, жёлтая или светло-оранжевая, в основании ножки буроватая, на разрезе синеет, имеет приятный запах сосновой хвои и приятный вкус либо без вкуса. Иногда запах мякоти сравнивают с металлическим. Трубчатый слой приросший у ножки, трубочки имеют жёлтый, светло-оранжевый, бурый или желтовато-оливковый цвет, поры коричневого цвета, мелкие, округлые, на срезе или при надавливании слегка синеют. Ножка 3—9 см высотой и 1,5—3,5 см толщиной, гладкая, цилиндрическая, цвет лимонно-жёлтый, серовато-жёлтый, иногда с красноватым оттенком или оранжево-бурая снизу.', '/media/mushrooms/placeholder.webp', NULL),
('966f285a-ed80-5a8a-8d32-9a92cb7b9a9f', 'Груздь Настоящий', 'Груздь белый, Груздь сырой, Груздь мокрый, Груздь правский', NULL, 'Сыроежковые', false, 'Неизвестно', true, 20, 50, 'Ровная', 'Белый, желтоватый', 'Вогнутая', 'Молочно-белый, желтоватый', 'Пластинчатая', 'Груздь встречается в лиственных и смешанных лесах (берёзовых, сосново-берёзовых, с липовым подлеском). Распространён в северных областях России, в Белоруссии, в Верхнем и Среднем Поволжье, на Урале, в Западной Сибири. Встречается нечасто, но обильно, растёт обычно большими группами. Относится к условно-съедобным грибам.', '/media/mushrooms/placeholder.webp', NULL),
('b64db0ef-4901-5e86-8bfd-375c6cb9ccba', 'Мокруха пурпуровая', 'Мокруха слизистая, Мокруха блестящая, Мокруха желтоногая, Мокруха пурпурная, Мокруха сосновая, Желтоног медно-красный', NULL, 'Мокруховые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Желтоватый, бледно-оранжевый', 'Выпуклая', 'Желтоватый, оранжевый, медный, красноватый, пурпурно-красный, красновато-коричневый', 'Пластинчатая', 'Мокруха пурпуровая растет с начала августа до конца сентября в сосновых лесах и в лесах с примесью сосны. Может расти как в старых лесах, так и молодых посадках, на обочинах лесных дорог и опушках. Часто соседствует с маслёнком обыкновенным. Встречается одиночно или небольшими группами. Нормальный съедобный гриб. Необходимо предварительное отваривание, после чего пурпуровую мокруху можно жарить или мариновать. Рекомендуется снимать кожицу со шляпки.', '/media/mushrooms/placeholder.webp', NULL),
('0d56eb84-bdce-551d-81ba-446e22599f04', 'Трутовик серно-жёлтый', 'Куриный гриб, Гриб курица, Ведьмина сера, Кулына', NULL, 'Фомитопсисовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Бледно-желтый, оранжевый, розовато-оранжевый', 'Гладкая', 'Трутовик серно-желтый растет с середины мая до осени на остатках деревьев или на живых ослабленных деревьях лиственных пород. Первый слой (майско-июньский) наиболее обилен. В молодом возрасте съедобен, хотя вкус, надо отметить, «на любителя».', '/media/mushrooms/placeholder.webp', NULL),
('7e73ab39-ab0c-5cb1-af8d-66ab627808f8', 'Опёнок зимний', 'Фламмулина, Фламмулина бархатистоножковая, Коллибия бархатистоножковая, Зимний гриб', NULL, 'Физалакриевые', false, 'Неизвестно', true, 5, 8, 'Ровная', 'Желто-коричневый, медовый', 'Ровная', 'Желто-коричневый, медовый', 'Пластинчатая', 'Опёнок зимний встречается поздней осенью и в начале зимы. Произрастает на валежнике и пнях, предпочитает лиственные деревья. При благоприятных условиях, может плодоносить весь зимний период. Хороший съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('32fdd297-6cf8-59be-9ba5-631980b0112b', 'Лисичка ложная', 'Говорушка оранжевая, Гигрофоропсис оранжевый, Кокошка', NULL, 'Гигрофоропсисовые', false, 'Неизвестно', true, 5, 10, 'Утолщенная вверху', 'Жёлто-оранжевый', 'Ровная', 'Оранжевый, жёлто-оранжевый, оранжево-коричневый', 'Пластинчатая', 'Ложная лисичка обитает с начала августа до конца октября (массово с середины августа до последней декады сентября) в хвойных и смешанных лесах, на почве, подстилке, во мху, на гниющей древесине сосны и около нее, иногда возле муравейников, одиночно и большими группами, довольно часто, ежегодно. Распространена по всей умеренной лесной зоне Европы, Азии. Лисичка ложная долгое время считалась ядовитым грибом. Потом была перенесена в разряд «условно-съедобных». Сейчас многие микологи склонны считать её скорее слабоядовитой, чем съедобной, даже после предварительного отваривания не менее 15 минут. Пока медики и микологи не пришли к единому мнению на этот счёт, мы рекомендуем воздержаться от употребления этого гриба в пищу людям с повышенной чувствительностью к грибам: есть информация, что употребление ложной лисички может вызвать обострение гастроэнтерита.', '/media/mushrooms/placeholder.webp', NULL),
('782c53f0-82de-538c-b0ef-5766ef04ce92', 'Ежовик пёстрый', 'Ежовик черепитчатый, Ежовик чешуйчатый, Саркодон черепитчатый, Саркодон пёстрый', NULL, 'Банкеровые', false, 'Неизвестно', true, 20, 25, 'Ровная', 'Бурый, фиолетовый', 'Ровная', 'Бурый', 'Трубчатая', 'Ежовик пёстрый встречается в хвойных лесах время произрастания август — ноябрь. Достаточно редкий гриб, растет большими группами. Предпочитает сухие песчаные почвы. Распространен во всех лесных зонах, но не одинаково, местами вообще отсутствует, а местами образует круги. Гриб годится для употребления в пищу. Молодые грибы можно употреблять в любом виде, но вкуснее всего в жареном виде. Горьковатый вкус исчезает после отваривания. Ежовик пёстрый отличается необычным пряным запахом, поэтому не каждому он придется по вкусу. Чаще всего, его используют в качестве приправы в небольшом количестве.', '/media/mushrooms/placeholder.webp', NULL),
('8d3933a9-7671-5a38-8bc5-d8ef1957965d', 'Паутинник жёлтый', 'Паутинник триумфальный, Приболотник жёлтый, Приболотник триумфальный', NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 30, 'Ровная', 'Беловато-жёлтый', 'Выпуклая', 'Оранжево-желтый', 'Пластинчатая', 'Паутинник жёлтый растет с середины августа до конца сентября в лиственных лесах, образуя микоризу преимущественно с березой. Предпочитает сухие места; может считаться спутником черного груздя. Место и время наиболее интенсивного плодоношения этих двух видов нередко совпадает. Паутинник жёлтый в зарубежных источниках проходит по категории несъедобных грибов; отечественные авторы придерживаются другого мнения. Ю.Г. Семенов в своей книге называет паутинник желтый наиболее вкусным паутинником.', '/media/mushrooms/placeholder.webp', NULL),
('11fe59aa-02f7-5cca-a516-7615eec3c782', 'Дубовик крапчатый', 'Поддубник, Боровик зернистоногий, Болет красноножковый', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 30, 'Утолщенная внизу', 'Желто-красный, тёмно-красный', 'Выпуклая', 'Каштаново-коричневый, красно-бурый, черно-коричневый', 'Трубчатая', 'Дубовик крапчатый растет в августе-сентябре (на юге — с конца мая) в лиственных и хвойных (с елью) лесах, в средней полосе редко Дубовик крапчатый — съедобный (2 категории) или условно съедобный гриб (отваривание около 15 минут).', '/media/mushrooms/placeholder.webp', NULL),
('71b7f444-9cd6-5115-aeec-ce03d4a362f5', 'Бледная поганка', 'Мухомор зелёный, Мухомор белый', NULL, 'Аманитовые', false, 'Неизвестно', true, 10, 25, 'С юбкой', 'Белый, тускло-зеленый, оливковый, желтоватый, коричневатый', 'Выпуклая', 'Тускло-зеленый, оливковый, желтоватый, коричневатый', 'Пластинчатая', 'Распространена в средней полосе России и других странах с континентальным климатом: Беларусь, Украина, встречается в странах Европы. Гриб смертельно ядовит. Даже минимальная доза может привести к летальному исходу. Определяющие признаки для этого вида включают: мешковидную белую вольву вокруг основания ножки кольцо белые пластины белый отпечаток спорового порошка отсутствие бороздок на шляпке', '/media/mushrooms/placeholder.webp', NULL),
('401451c6-9d9c-5d42-8c01-c03e8978b501', 'Чешуйчатка обыкновенная', 'Чешуйчатка ворсистая, Чешуйчатка сухая, Чешуйчатка шероховатая', NULL, 'Строфариевые', false, 'Неизвестно', true, 10, 30, 'Утолщенная вверху', 'Ржаво-бурый, коричневатый', 'Выпуклая', 'Охряно-коричневый, охряно-бурый, бледно-желтый, бледно-охряный', 'Пластинчатая', 'Чешуйчатка обыкновенная растет с середины июля до начала октября (массово с конца августа до конца сентября) в разных лесах на мертвой и живой древесине, на стволах, у основания вокруг стволов, на корнях лиственных (дуб, клён, липа, береза, осина, бук, плодовые — яблоня, груша) и реже хвойных (ель, сосна) деревьев, на пнях и около них, группами-пучками, колониями, не редко, ежегодно. Несмотря на привлекательный внешний вид, чешуйчатка обыкновенная не относится к съедобным грибам достаточно давно. Ранее, примерно до середины восьмидесятых годов прошлого века, Чешуйчатка обыкновенная считалась вполне съедобным грибом третьей категории. Но после нескольких зафиксированных случаев отравлений в европейский странах, ряд справочников относят её к несъедобным, а в более современных источниках всё чаще — к ядовитым.', '/media/mushrooms/placeholder.webp', NULL),
('62df595d-6674-5f0d-8cb0-25709f7728ea', 'Мухомор красный', NULL, NULL, 'Аманитовые', false, 'Неизвестно', true, 25, 35, 'С юбкой', 'Белый', 'Выпуклая', 'Ярко-красный, оранжево-красный', 'Пластинчатая', 'Мухомор красный растёт в хвойных, лиственных и смешанных лесах, особенно в березняках. Встречается часто и обильно одиночно и большими группами с июня до осенних заморозков. Гриб ядовит. Симптомы отравления проявляются через 20 мин и до 2 ч после приема. Содержит значительное количество мускарина и других алкалоидов.', '/media/mushrooms/placeholder.webp', NULL),
('ab8b42e9-ce1e-5fc7-a5dd-e5e209506c09', 'Вёшенка устричная', 'Вёшенка обыкновенная, Устричный гриб, Глыва', NULL, 'Вёшенковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная вверху', 'Светло-серый', 'Вогнутая', 'Светло-пепельный, темно-серый, светлый, желтоватый, металлический', 'Пластинчатая', 'Вешёнка устричная растет на мертвой древесине и на ослабленных деревьях, предпочитая лиственные породы. Массовое плодоношение, как правило, отмечается в сентябре-октябре, хотя при благоприятных условиях может появиться и в мае. Гриб съедобный и в молодом виде даже вкусный. Искусственно культивируется. Пожилые вешенки становятся жесткими и безвкусными.', '/media/mushrooms/placeholder.webp', NULL),
('f57133a2-0943-566b-af8b-6e27919da2ba', 'Маслёнок жёлто-бурый', 'Маслёнок пёстрый, Моховик болотный, Моховик песчаный, Моховик желто-бурый, Болотовик, Пестрец', NULL, 'Маслёнковые', false, 'Неизвестно', true, 20, 35, 'Ровная', 'Лимонно-желтый, светло-желтый, оранжево-бурый, красноватый', 'Выпуклая', 'Серо-желтый, серо-оранжевый, буро-красноватый, светло-охряный', 'Трубчатая', 'Масленок желто-бурый растет прежде всего на песчаной почве с июня по ноябрь в хвойных и смешанных лесах, часто в очень больших количествах. Плодовые тела появляются одиночно или небольшими группами. Масленок желто-бурый известен в Европе; в России— в европейской части, в Сибири и на Кавказе, доходя к северу до предела сосновых лесов, а также в горных лесах Сибири и Кавказа. Съедобен (3-я категория). Малоизвестный съедобный гриб, но не очень вкусный. Молодые плодовые тела-лучше всего мариновать.', '/media/mushrooms/placeholder.webp', NULL),
('81dec418-a516-53f1-be5c-34c564b1c227', 'Говорушка перевёрнутая', 'Говорушка рыже-бурая', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Светло-коричневый', 'Вогнутая', 'Оранжево-коричневый, кирпичный', 'Пластинчатая', 'растёт разбросанно или тесными группами на хвойной подстилке, часто у подножия муравейников, иногда на влажных опилках и щепе. Чаще встречается в хвойных и смешанных лесах, иногда растёт и на богатых гумусом почвах. Распространённый вид Северного полушария, обычен в Северной Америке, материковой Европе и Великобритании. Период активного роста — осень, вплоть до наступления холодов, однако, в ряде мест он может смещаться на зиму или продолжаться — в мягком климате — до января. Согласно одним источникам, говорушка перевёрнутая не ядовита, но его пищевые качества оставляют желать лучшего, и собирать её большого смысла нет. Согласно другим — ядовита (содержит мускариноподобные токсины).', '/media/mushrooms/placeholder.webp', NULL),
('ef8242dd-c2e7-57f2-8f1e-d42a6b892b46', 'Польский гриб', 'Моховик каштановый, Коричневый гриб, Панский гриб', NULL, 'Болетовые', false, 'Неизвестно', true, 8, 40, 'Ровная', 'Светло-бурый, желтовато-буроватый, желто-коричневый, светло-коричневый, желтоватый, белый, палевый', 'Выпуклая', 'Светло-красноватый, светло-коричневый, каштановый, шоколадно-коричневый, оливково-коричневый, буроватый, темно-коричневый, черно-коричневый', 'Трубчатая', 'Польский гриб растет на кислых почвах в смешанных (часто под дубами, каштанами и буками) и в хвойных лесах — под немолодыми деревьями, на подстилке, на песчаных почвах и во мху, у основания деревьев, на кислых почвах в низинах и горах, единично или небольшими группами, не редко или довольно часто, ежегодно. Распространен в северной умеренной зоне, включая Северную Америку, но более массово — в Европе, в т.ч. в Польше, Беларуси, Западной Украине, Прибалтике, Европейской части России, на Кавказе, включая Северный, в Западной Сибири, Восточной Сибири, на Дальнем Востоке, в Азербайджане, Монголии и даже в Австралии (южная умеренная зона). Популярный и вкусный съедобный гриб (2-й категории) — особенно поздней осенью, когда сходят другие болетовые. Сине-голубая окраска белой мякоти исчезает при приготовлении.', '/media/mushrooms/placeholder.webp', NULL),
('9b98dafe-52ac-5fdb-a83d-8c454ca107fc', 'Зонтик чешуйчатый', 'Лепиота чешуйчатая, Лепиота коричнево-красная', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 20, 'С юбкой', 'Бело-кремовый, тёмно-вишнёвый', 'Выпуклая', 'Кремовато-коричневый, серовато-коричневый, вишнёвый', 'Пластинчатая', 'Зонтик чешуйчатый распространен по территории Западной Европы и Средней Азии, на Украине и юге России и предпочитает расти на лугах и в парках на газонах. Активное созревание происходит уже в середине июня и продолжается до конца августа. Зонтик чешуйчатый относится к смертельно ядовитым грибам. Он содержит в своём составе такие опасные яды, как цианиды, вызывающие смертельные отравления!', '/media/mushrooms/placeholder.webp', NULL),
('3f98eecb-265d-5381-b181-bac93b15be9d', 'Рядовка фиолетовая', 'Рядовка лиловая, Леписта голая, Леписта фиолетовая, Синюха, Синичка', NULL, 'Рядовковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Бледно-лиловый', 'Выпуклая', 'фиолетовый, бледно-лиловый, коричневатый', 'Пластинчатая', 'Рядовка фиолетовая встречается часто, в основном группами. В основном растет на севере лесной зоны в смешанных и хвойных лесах. Реже встречается на полянах и опушках, среди зарослей крапивы и около навалов хвороста. Съедобный вкусный гриб. Перед приготовлением, грибы нужно проварить в течение 10-15 минут.', '/media/mushrooms/placeholder.webp', NULL),
('e555054a-cd3a-5bd9-b45b-f3ec8725c638', 'Мухомор серо-розовый', 'Мухомор розовый, Мухомор краснеющий, Мухомор жемчужный', NULL, 'Аманитовые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Белый, розоватый', 'Выпуклая', 'Серовато-розовый, красно-коричневый, мясо-красный', 'Пластинчатая', 'Мухомор серо-розовый образует микоризу с лиственными и хвойными деревьями, особенно с берёзой и сосной. Растёт на почвах любого типа, повсеместно в зоне умеренного климата Северного полушария. Мухомор серо-розовый плодоносит одиночно или небольшими группами, встречается часто. Сезон с весны до поздней осени, наиболее часто с июля по октябрь. Мухомор серо-розовый — Условно-съедобный гриб, знающие грибники считают его очень хорошим на вкус, и любят за то, что он появляется уже в начале лета. В свежем виде в пищу непригоден, обычно употребляется жареным после предварительного отваривания. Сырой гриб содержит не термостойкие ядовитые вещества, перед приготовлением его рекомендуется хорошо отваривать и сливать воду.', '/media/mushrooms/placeholder.webp', NULL),
('30a46148-6faf-5849-b126-d541656aab2b', 'Зонтик пёстрый', 'Зонтик, Зонтик большой, Зонтик высокий, Макролепиота процера', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 15, 30, 'С юбкой', 'Светло-коричневатый', 'Выпуклая', 'Беловатый, бело-серый, бурый', 'Пластинчатая', 'Зонтик пёстрый произрастает с июля по октябрь в лесах, на полянах, вдоль дорог, на лугах, полях, пастбищах, в садах и пр. В благоприятных условиях образует внушительные «ведьмины кольца». Считается хорошим съедобным грибом', '/media/mushrooms/placeholder.webp', NULL),
('42d464c4-5ecb-56bb-8b70-aa7a10b565d6', 'Рядовка майская', 'Калоцибе майская, Калоцибе майский, Майский гриб, Георгиев гриб', NULL, 'Лиофилловые', false, 'Неизвестно', true, 10, 30, 'Ровная', 'Желтоватый, белый', 'Выпуклая', 'Желтоватый, белый', 'Пластинчатая', 'Рядовка майская начинает плодоносить в середине или конце мая на лужайках, лесных опушках и полянах, в парках и скверах, на газонах; растет кругами или рядами, образуя хорошо заметные «тропинки» в травяном покрове. Полностью исчезает к середине июня. Рядовка майская считается очень хорошим съедобным грибом.', '/media/mushrooms/placeholder.webp', NULL),
('d8c2410f-9744-5454-8b63-0e5a3078afae', 'Груздь дубовый', 'Рыжик дубовый, Млечник зональный, Млечник дубовый', NULL, 'Сыроежковые', true, 'Неизвестно', true, 15, 30, 'Утолщенная вверху', 'Желтоватый, светло-оранжевый, кремовый', 'Выпуклая', 'Желтоватый, желтовато-оранжевый, рыжеватый, кремово-охристый', 'Пластинчатая', 'Вид широко распространен в центральных и южных регионах Европы, Украины и европейской части России. Любит теплое время, встречается в Крыму, Краснодарском крае, на Кавказе. В последнее время заметны тенденции к распространению в более северные регионы. Так вид отмечен в Ленинградской области.Период плодоношения с июля по октябрь. Образует микоризу с дубом, лещиной, буком, грабом. Встречается в широколиственных и смешанных лесах, на глинистых почвах, одиночно, группами, большими группами. Не часто. Условно-съедобный гриб 2-й категории. Традиционно используется солёным, с предварительным вымачиванием или отвариванием, для избавления от лишней горечи.', '/media/mushrooms/placeholder.webp', NULL),
('e96109be-6062-5ce4-8971-fc604989f944', 'Свинуха гигантская', 'Белосвинуха гигантская, Говорушка гигантская, Рядовка гигантская', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 30, 'Утолщенная вверху', 'Бело-палевый', 'Вогнутая', 'Бело-палевый', 'Пластинчатая', 'Свинуха гигантская встречается на лесных полянах в европейской части России и на Кавказе. Иногда образует «ведьмины кольца». Съедобен, но может вызывать расстройство желудка. Посредственный, условно-съедобный гриб 4-й категории, используется свежим (после 15-20 минутного отваривания) или соленым. Использовать рекомендуется лишь молодые грибы.', '/media/mushrooms/placeholder.webp', NULL),
('c7dace1f-6274-5910-bdc0-4fa78e8a1660', 'Лисичка обыкновенная', 'Лисичка настоящая, Лисичка жёлтая, Лисичка, Петушок', NULL, 'Лисичковые', false, 'Неизвестно', true, 10, 30, 'Утолщенная вверху', 'Яично-желтый, оранжево-желтый, беловатый', 'Вогнутая', 'Яично-желтый, оранжево-желтый, беловатый', 'Пластинчатая', 'Этот весьма распространенный гриб растет с начала лета до поздней осени в смешанных, лиственных и хвойных лесах, временами (особенно в июле) в огромных количествах. Особенно часто встречается во мхах, в хвойных лесах. Съедобный вкусный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('ab9924fe-bd59-5001-bf5c-b5c58f6c043b', 'Ежовик желтый', 'Ежовик выемчатый, Гиднум выемчатый, Дентинум выемчатый', NULL, 'Ежовиковые', false, 'Неизвестно', true, 15, 25, 'Утолщенная внизу', 'Бледно-желтый', 'Ровная', 'Желтоватый, беловатый, оранжевый', 'Трубчатая', 'Растет с июля по октябрь (в основном — в августе) большими группами в лиственных, хвойных и смешанных лесах, предпочитая моховой покров. Нормальный съедобный гриб. Все источники указывают, что в пожилом возрасте Ежовик желтый горчит.', '/media/mushrooms/placeholder.webp', NULL),
('6056c6d7-bbad-5aa2-84cf-ebb202d33db1', 'Болет красивоножковый', 'Боровик красивый, Боровик несъедобный', NULL, 'Болетовые', false, 'Неизвестно', true, 10, 40, 'Утолщенная внизу', 'Лимонно-желтый, карминно-красный, буро-красный, белый', 'Выпуклая', 'Светло-коричневый, оливково-светло-бурый, бурый, буро-серый', 'Трубчатая', 'Болет красивоножковый растет на почве с июля по октябрь в хвойных лесах в горных районах под елями, изредка в лиственных лесах. Не съедобен из-за неприятного горького вкуса.', '/media/mushrooms/placeholder.webp', NULL),
('67a9aa08-9631-5b5a-bd94-8a6f9398c8df', 'Сатанинский гриб', 'Болет сатанинский, Боровик сатанинский', NULL, 'Болетовые', false, 'Неизвестно', true, 30, 60, 'Утолщенная внизу', 'Тёмно-красный, белый, оливковый', 'Выпуклая', 'Бледно-охристо-белый, беловато-серый, свинцово-серый, желтоватый, оливковый, розоватый', 'Трубчатая', 'Растет в светлых дубняках и широколиственных лесах на известковой почве. Встречается в светлых лиственных лесах с дубом, буком, грабом, лещиной, съедобным каштаном, липой с которыми образует микоризу, преимущественно на известковых почвах. Распространён в Южной Европе, на юге европейской части России, на Кавказе, Ближнем Востоке. Встречается также в лесах на юге Приморского края. Сезон июнь — сентябрь. Ядовит. Согласно некоторым источникам сатанинский гриб в европейских странах (Чехия, Франция) считают условно-съедобным и употребляют в пищу. Согласно итальянскому справочнику токсичность сохраняется и после тепловой обработки.', '/media/mushrooms/placeholder.webp', NULL),
('dc159480-032e-5d84-9356-85a0ec23ad7d', 'Паутинник плюшевый', 'Паутинник горный, Паутинник оранжево-красный', NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Оранжевый, коричнево-красный, золотой', 'Выпуклая', 'Оранжевый, коричнево-красный, золотой', 'Пластинчатая', 'Паутинник плюшевый — сравнительно редкий вид. В некоторых странах он до сих пор обнаружен не был. В Европе растет главным образом осенью (иногда в конце лета) в лиственных, а изредка и в хвойных лесах. Он образует микоризу в основном с дубом и березой. Чаще всего появляется на кислых почвах. Паутинник плюшевый — смертельно ядовит. Содержит ядовитое вещество орелланин, вызывающее патологические изменения в почках. Признаки отравления появляются через 3— 14 дней после приема гриба в пищу. Ядовитые свойства гриб сохраняет после кипячения в воде или сушки.', '/media/mushrooms/placeholder.webp', NULL),
('48cdaad2-d33d-5750-a5df-63fd2c655b3f', 'Мухомор вонючий', 'Мухомор зловонный, Белоснежная поганка, Белая поганка', NULL, 'Аманитовые', false, 'Неизвестно', true, 10, 15, 'Утолщенная внизу', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Растёт в хвойных и смешанных сыроватых лесах на песчаных почвах с июля по сентябрь. Гриб смертельно ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('315f9f78-9d6c-5a68-8ea1-f1b1e53060fd', 'Трутовик скошенный', 'Берёзовый гриб, Чага, Древесный гриб, Чёрный гриб, Трутовик косотрубчатый, Чёрный берёзовый гриб', NULL, 'Гименохетовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Чёрно-бурый, чёрный, буро-коричневый, древесный', 'Трубчатая', 'На протяжении всего сезона плодоношения трутовик скошенный паразитирует на древесине берёз, ольхе, иве, рябине, осине. Развивается в углублениях и трещинах деревьев, паразитируя на них много лет, пока древесина не станет трухлявой, и не рассыплется. Встретить этот гриб можно не часто, а определить его наличие на первых стадиях развития можно по стерильным наростам. Вторая стадия развития трутовика скошенного характеризуется образованием плодовых тел уже на отмершей древесине. Этот гриб провоцирует поражение древесины белой, сердцевинной гнилью. Трутовик скошенный, произрастающий на всех деревьях, кроме берёзы, употреблять в пищу нельзя. Плодовые тела скошенного трутовика, паразитирующего на древесине берёзы, обладают лечебным действием. Народная медицина предлагает экстракт чаги как прекрасное средство для лечения заболеваний органов желудочно-кишечного тракта, селезёнки, печени.', '/media/mushrooms/placeholder.webp', NULL),
('5822fe1a-7df8-5275-ac63-b91d97d7ce99', 'Рядовка белая', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 15, 20, 'Утолщенная внизу', 'Желтовато-бурый, серовато-белый', 'Выпуклая', 'Серовато-белый', 'Пластинчатая', 'Белая рядовка растет в густых лесах, большими группами. Так же встречается в парках и рощах. Белая окраска рядовки делает гриб похожим на шампиньоны, но не темнеющие светлые пластины, сильный резкий запах и жгучий едкий вкус отличают белую рядовку от шампиньонов. Гриб несъедобен из-за сильного неприятного запаха. Вкус едкий, жгучий. По некоторым источникам, гриб относится к ядовитым видам.', '/media/mushrooms/placeholder.webp', NULL),
('77fc1497-60f2-5ea8-96a2-37c68d664dbe', 'Боровик придаточковый', 'Боровик девичий, Боровик укороченный, Боровик красноватый, Боровик буро-желтый', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 30, 'Ровная', 'Лимонно-желтый, красно-буроватый', 'Выпуклая', 'Желто-бурый, красно-бурый, коричнево-бурый', 'Трубчатая', 'Гриб редкий. Растет, как правило группами, с июня по сентябрь прежде всего в регионах с умеренно теплым климатом в лиственных и смешанных лесах, главным образом под дубами, грабами и буками, так же отмечен в горах среди пихт. В литературе отмечают привязанность к известковой почве. Вкусный съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('03109fa2-1d9c-55cb-9370-162492156b53', 'Шампиньон желтокожий', 'Шампиньон рыжеющий, Печерица желтокожая', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 20, 'С юбкой', 'Белый', 'Выпуклая', 'Белый, буроватый, желтоватый', 'Пластинчатая', 'Шампиньон желтокожий активно плодоносит летом и осенью. Особенно в обильном количестве она появляется после дождей. Встречается не только в лесах смешанного типа, но также и в парках, в садах, во всех заросших травой местах. Данный вид гриба широко распространен по всему миру. Гриб ядовит, вызывает желудочные расстройства. Отличительными признаками шампиньона желтокожего от съедобного гриба является его желтеющие места при прикосновении и выделяемый неприятный фенольный запах.', '/media/mushrooms/placeholder.webp', NULL),
('0707e509-3839-5238-a87b-9ff1c26bab0b', 'Гигрофор оливково-белый', 'Сластена, Черноголовик, Мокрица оливково-белая', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 15, 30, 'Ровная', 'Желтоватый, бело-рыжеватый', 'Выпуклая', 'Коричневый, оливково-зеленый', 'Пластинчатая', 'Гигрофор оливково-белый встречается в хвойных и смешанных лесах, чаще всего с елью и сосной. Сезон - лето-осень. Съедобный гриб среднего качества.', '/media/mushrooms/placeholder.webp', NULL),
('3d66ef90-28ca-532d-9610-721540861524', 'Паутинник фиолетовый', NULL, NULL, 'Паутинниковые', true, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Буровато-фиолетовый, темно-фиолетовый', 'Выпуклая', 'Темно-фиолетовый', 'Пластинчатая', 'Встречается в лиственных и хвойных лесах, особенно в сосняках, в августе-сентябре. Малоизвестный съедобный гриб. Занесен в Красную книгу.', '/media/mushrooms/placeholder.webp', NULL),
('bcda9d1e-ae03-5567-a67d-005e85016474', 'Рядовка дымчатая', 'Говорушка серая, Говорушка дымчато-серая', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 30, 'Утолщенная внизу', 'Серо-белый, светло-серый, желтоватый', 'Выпуклая', 'Пепельный, желтоватый', 'Пластинчатая', 'Дымчатая говорушка растет с конца лета до поздней осени (особенно обильно с середины сентября до первой декады октября, а то и позже) в еловых и смешанных лесах (предпочитая, видимо, образовывать микоризу с елью), а также на опушках, в садах и пр. Часто появляется очень большими группами, образуя кольца и ряды. Рядовка дымчатая — съедобный гриб, по некоторым данным — условно съедобный (во избежание недоразумений гриб лучше отваривать, отвар в пищу не использовать).', '/media/mushrooms/placeholder.webp', NULL),
('e3f5a50b-8de4-5ea5-938c-8b3c810044c9', 'Опёнок луговой', 'Негниючник луговой, Марасмиус луговой, Луговик, Гвоздичный гриб', NULL, 'Негниючниковы', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Желтовато-белый', 'Выпуклая', 'Рыжевато-желтый, грязно-белый', 'Пластинчатая', 'Луговой опенок встречается с начала лета до середины или конца октября на лугах, в садах, на полянах и лесных опушках, а также вдоль дорог; плодоносит обильно, часто образуя характерные кольца. Универсальный съедобный гриб, подходит в том числе для сушки и супов.', '/media/mushrooms/placeholder.webp', NULL),
('89703b14-7c4e-5785-b90b-ca25597c1589', 'Моховик зеленый', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 10, 20, 'Утолщенная вверху', 'Желтовато-бурый, красно-буроватый', 'Выпуклая', 'Оливково-бурый, желтовато-оливковый, ярко-желтый, пеленовато-желтый', 'Трубчатая', 'Моховик зелёный встречается в лиственных, хвойных лесах и кустарниках, обычно на хорошо освещенных местах (по обочинам троп, канав, на опушках), иногда растет на гнилой древесине, муравейниках. Селится чаще одиночно, иногда группами. Моховик зеленый считается съедобным грибом 2-й категории. Для приготовления используется все тело гриба, состоящее из шляпки и ножки. Горячие блюда из него приготавливаются без предварительного отваривания, но с обязательным очищением от кожицы.', '/media/mushrooms/placeholder.webp', NULL),
('f18de96c-e208-5881-a121-d6cda1010153', 'Панеолус мотыльковый', NULL, NULL, 'Псатирелловые', false, 'Неизвестно', true, 20, 40, 'Ровная', 'Серо-коричневый', 'Выпуклая', 'Серо-коричневый, оливково-коричневый, желтовато-коричневый, красновато-коричневый', 'Пластинчатая', 'Панеолус мотыльковый встречается на пастбищах или на перегнившей траве. Произрастает небольшими группами в лошадином или коровьем навозе. Иногда встречается одиночно, но редко. Период плодоношения с весны по осень. Насчет съедобности гриба информация отсутствует, но употреблять его в пищу не рекомендуется, поскольку возможно, гриб содержит токсическое вещество – слабо концентрированный псилоцибин, имеющее умерено галлюциногенные свойства. Некоторые источники указывают данный гриб, как ядовитый.', '/media/mushrooms/placeholder.webp', NULL),
('6cc43df1-0606-542a-a138-cea34d8644e5', 'Маслёнок настоящий', 'Маслёнок обыкновенный, Маслёнок жёлтый, Маслёнок поздний, Маслёнок осенний', NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 25, 'С юбкой', 'Лимонно-желтый, буроватый', 'Выпуклая', 'Шоколадно-буроватый, фиолетовый', 'Трубчатая', 'Маслёнок настоящий растёт на песчаной почве с конца мая по ноябрь в хвойных лесах. Плодовые тела появляются одиночно или чаще всего большими группами. Маслёнок настоящий — Съедобный, вкусный гриб второй категории, по вкусовым качествам очень близок к белым грибам. Перед употреблением кожицу со шляпки лучше снимать.', '/media/mushrooms/placeholder.webp', NULL),
('b686a580-17e2-52d9-8816-a2263a3741b7', 'Груздь осиновый', 'Груздь Тополевый, Белянка', NULL, 'Сыроежковые', true, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, розоватый', 'Вогнутая', 'Белый, розоватый', 'Пластинчатая', 'Груздь осиновый образует микоризу с ивой, осиной и тополем. Растёт в сырых осинниках, тополёвых лесах, встречается довольно редко, плодоносит обычно небольшими группами. Груздь осиновый распространён в более тёплых частях умеренного климатического пояса, в России встречается главным образом в районе Нижнего Поволжья. Сезон июль—октябрь. Условно-съедобный гриб, используется в основном в солёном виде, реже — жареным или варёным во вторых блюдах.', '/media/mushrooms/placeholder.webp', NULL),
('de435ad0-1b6f-519c-a7d9-36decb21e6d8', 'Опёнок серопластинчатый', 'Ложноопёнок серопластинчатый, Опёнок маковый, Ложноопёнок маковый, Гифолома маковая, Гифолома охряно-оранжевая', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Желтый, ржаво-коричневый', 'Ровная', 'Тускло-желтый, светло-коричневый', 'Пластинчатая', 'Опёнок серопластинчатый — типичный древесный гриб. Его плодовые тела вырастают пучками на пнях и на скрытых в земле корнях. Он растет лишь в хвойных лесах, чаше всего на сосне и ели, как в низинах, так и высоко в горах. Особенно обильна в горных еловых лесах. Опёнок серопластинчатый распространен во всем умеренном поясе северного полушария. Опёнок серопластинчатый имеет репутацию хорошего съедобного гриба.', '/media/mushrooms/placeholder.webp', NULL),
('4d592942-e150-5286-a0be-ee4c75855c42', 'Говорушка буро-желтая', 'Рядовка водопятнистая, Рядовка золотистая, Рядовка буро-жёлтая', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Желто-охряный, бледно-охряный', 'Вогнутая', 'Желтовато-охряный, желто-оранжевый, рыжеватый, желтоватый, коричневато-желтоватый, кремовый, желтовато-молочный', 'Пластинчатая', 'Говорушка буро-жёлтая растет с начала июля до конца октября (массово с середины августа до середины октября) в хвойных и смешанных лесах, группами, не редко. По некоторым зарубежным источникам Говорушка буро-жёлтая — ядовитый гриб с ядами, аналогичными мускарину. По другим микологическим источникам — условно-съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('7c7f4a19-75a2-5457-a7ae-d832a93352db', 'Опёнок летний', 'Опеногаллеринный опенок, Кюнеромицес изменчивый', NULL, 'Строфариевые', false, 'Неизвестно', true, 3, 5, 'С юбкой', 'Коричневый, бурый, темно-бурый', 'Выпуклая', 'Желто-бурый', 'Пластинчатая', 'Опёнок летний растет с июня по октябрь (обильно плодоносит, как правило, в июле-августе, не позже) на гниющей древесине, на пнях и валежнике лиственных деревьев, преимущественно березы. При подходящих условиях попадается в огромном количестве. На хвойных деревьях встречается редко. Считается очень хорошим съедобным грибом, особенно в западной литературе.', '/media/mushrooms/placeholder.webp', NULL),
('e04afd4c-1f06-51e5-9a24-d8c16e6177c9', 'Рядовка желто-красная', 'Рядовка краснеющая, Песочник красный, Ложнорядовка жёлто-красная, Опёнок жёлто-красный, Опёнок красный, Опёнок сосновый', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 15, 'Утолщенная внизу', 'Желто-красный', 'Выпуклая', 'Желто-оранжевый, желто-красный, бордово-коричневый, бордово-фиолетовый', 'Пластинчатая', 'Рядовка жёлто-красная встречается нечасто в хвойных лесах. Произрастает на пнях лиственницы и на валеже, на завалах, в поймах. Предпочитает древесину именно хвойных пород деревьев. Плодоносит с июля по сентябрь. Как правило, растет пучком по три-четыре гриба. Рядовка жёлто-красная съедобна, употребляется в жареном, соленом, маринованном или вареном виде. Относится к условно-съедобным, четвертой категории вкусовых качеств.', '/media/mushrooms/placeholder.webp', NULL),
('20fa0682-1c6f-53a1-841b-866e0479d3a0', 'Чёрный груздь', 'Оливково-чёрный груздь, Чернушка, Черныш, Чёрная дуплянка, Цыган, Чёрный еловый груздь, Оливково-коричневый груздь', NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Тёмно-оливковый', 'Ровная', 'Тёмно-оливковый', 'Пластинчатая', 'Чёрный груздь образует микоризу с берёзой. Произрастает в смешанных лесах, березняках, обычно большими группами во мху, на подстилке, в траве, в светлых местах и у лесных дорог. Сезон с середины июля до середины октября (массово с середины августа до конца сентября). Условно-съедобный гриб, используется, как правило, солёным или свежим во вторых блюдах.', '/media/mushrooms/placeholder.webp', NULL),
('cd4424c6-12a7-512a-84f7-ff27f66aae97', 'Рыжик настоящий', 'Рыжик обыкновенный, Рыжик осенний, Рыжик сосновый, Рыжик боровой, Рыжик деликатесный, Рыжик благородный', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Рыжий, беловато-оранжевый', 'Ровная', 'Рыжий, беловато-оранжевый', 'Пластинчатая', 'Основными местами произрастания являются горные хвойные леса Сибири, Урала и европейской части России. Рыжик — съедобный гриб первой категории. Используется преимущественно для засола и маринования, но можно употреблять его и в жареном виде.', '/media/mushrooms/placeholder.webp', NULL),
('c8afacff-104f-5f7f-8f08-3901153cda6e', 'Мокруха еловая', 'Мокруха клейкая, Гриб слизняк', NULL, 'Мокруховые', false, 'Неизвестно', true, 6, 20, 'С юбкой', 'Белый, черноватый, коричневатый', 'Выпуклая', 'Серый, серовато-коричневый, фиолетовый, серо-синий, шоколадно-коричневый, пурпурный', 'Пластинчатая', 'С середины июля до заморозков. Массово плодоносит с августа по сентябрь. Распространен повсеместно в северном и умеренном поясе республик бывшего СССР, в Алтайском крае, Западной Европе, Северной Америке. Съедобный гриб 4 категории, напоминающий по вкусу маслят, перед употреблением рекомендуется очистить от кожицы и отварить.', '/media/mushrooms/placeholder.webp', NULL),
('7a664dd0-cb02-5591-85a1-7b92859ff1ea', 'Рядовка украшенная', 'Рядовка красивая, Рядовка оливково-жёлтая', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Пурпурный, желтоватый', 'Выпуклая', 'Жёлто-охряный, желтоватый', 'Пластинчатая', 'Украшенные рядовки чаще всего встречаются в смешанных или хвойных лесах, где растут сосны. Предпочитают расти на подгнивающей древесине хвойных пород деревьев (чаще это – сосны, иногда – ели). Увидеть рядовку украшенную также можно на пнях. Этот гриб растёт в составе небольших групп, встречается нечасто. Наиболее активное его плодоношение приходится на период с августа по вторую декаду октября. Рядовка украшенная – условно-съедобный гриб, обладающий низким качеством. Его мякоть очень горькая, что обуславливает неприязнь многих гурманов к этому виду рядовок.', '/media/mushrooms/placeholder.webp', NULL),
('598ff3eb-513b-59a9-96aa-e76d3ab7045c', 'Полубелый гриб', 'Желтожебрик, Болет полубелый, Боровик жёлтый', NULL, 'Болетовые', true, 'Неизвестно', true, 20, 60, 'Утолщенная внизу', 'Кремовый или от светло-жёлтого до жёлтого, снизуКрасноватый, ржавый, желто-оранжевый, красный', 'Выпуклая', 'Сероватый, серовато-охристый, светло-серый, оливковый, светло-коричневый, глинистый, рыжеватый', 'Трубчатая', 'Период плодоношения на территории стран СНГ с конца мая по октябрь, более массово в августе-сентябре. Растёт как на кислых, так и известковых почвах. Образует микоризу с дубом, буком, каштаном, грабом, липой, сосной. Предпочитает влажные пойменные широколиственные леса, влажные глинистые с примесью извести почвы. Встречается редко, может быть не ежегодно, иногда обильно. Съедобный гриб 2-й категории. По некоторым оценкам, очень вкусный гриб, не уступающий Белым грибам.', '/media/mushrooms/placeholder.webp', NULL),
('f2ddbb6a-31ee-5042-b174-a9b0a9dabf1e', 'Скрипица', 'Груздь войлочный, Скрипун, Скрипуха, Молочай, Подскрёбыш молочный, Подсухарь', NULL, 'Сыроежковые', false, 'Неизвестно', true, 20, 50, 'Ровная', 'Белый', 'Вогнутая', 'Белый, желтоватый, красновато-бурый, охристый', 'Пластинчатая', 'Скрипица образует микоризу с лиственными и хвойными деревьями, часто с березой. В хвойных и лиственных лесах, обычно группами. Сезон — Лето-осень. Условно-съедобный гриб. Съедобна в соленом виде после вымачивания.', '/media/mushrooms/placeholder.webp', NULL),
('ed90f51e-e06a-5bd5-9d5f-ffbb600440bf', 'Цезарский гриб', 'Цезарев гриб, Кесарев гриб, Мухомор цезаря', NULL, 'Аманитовые', false, 'Неизвестно', true, 15, 25, 'Утолщенная внизу', 'Светло-жёлтый, золотистый', 'Выпуклая', 'Оранжевый, огненно-красный, желтоватый', 'Пластинчатая', 'Встречается с июня по октябрь в старых светлых лесах, перелесках, лесных порослях, на границе лиственных лесов и лугов. Традиционно произрастает под каштанами и дубами, реже — по соседству с буками, берёзами, орешником или хвойными породами деревьев на кислых или декальцинированных почвах, спорадически, одиночно. Исключительно вкусный съедобный гриб (1-ая категория), чрезвычайно ценимый ещё с античных времён. Используется варёным, жареным, сушёным, маринованным.', '/media/mushrooms/placeholder.webp', NULL),
('71c8f8a0-8221-516f-b5f4-dd57df8d4edd', 'Аурикулярия извилистая', 'Аурикулярия плёнчатая', NULL, 'Аурикуляриевые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Коричневый, светло-серый', 'Гладкая', 'Аурикулярия извилистая обитает в лиственных, главным образом низинных лесах на упавших стволах деревьев: вязы, тополя, ясени. Обычный гриб для района Нижнего Дона. Гриб Аурикулярия извилистая Съедобен, но пищевое качество низкое.', '/media/mushrooms/placeholder.webp', NULL),
('845b0b36-70d8-5bad-9ae8-241406f0e71a', 'Волнушка белая', 'Белянка, Волжанка', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Беловатый, розоватый', 'Вогнутая', 'Белый, розовый, желтый', 'Пластинчатая', 'Волнушка белая встречается с начала августа по конец сентября в смешанных и лиственных лесах, образовывая микоризу главным образом с березой; предпочитает молодые березняки и приболоченные места. В удачный сезон может появляться в зарослях молодых березок в огромных количествах. Хороший гриб, пригодный для засола и маринования.', '/media/mushrooms/placeholder.webp', NULL),
('a7a41992-7b94-53be-99ab-d551b8693c2e', 'Подмолочник', 'Подоречник, Молочай', NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Рыже-бурый, коричнево-бурый, ржавый, светло-охристый', 'Выпуклая', 'Рыже-бурый, коричнево-бурый, ржавый, светло-охристый', 'Пластинчатая', 'Встречается с июля по октябрь. Один из самых ранних млечников. Растет в лиственных, смешанных и еловых лесах. Съедобный гриб, который можно есть даже сырым. Хорош в сыро засоленном или квашенном виде, без какой-либо термообработки.', '/media/mushrooms/placeholder.webp', NULL),
('3532d71d-6515-5cad-a580-11bdaedb86a3', 'Волнушка розовая', 'Волнянка, Волжанка, Волвенка, Волвяница, Волминка, Волнуха, Краснуха, Красуля, Отваруха', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Бледно-розовый', 'Ровная', 'Розовато-красный', 'Пластинчатая', 'Волнушка растет с сердины лета по октябрь в лиственных и смешанных лесах, предпочитая образовывать микоризу с немолодоыми березами. Иногда появляется большими группами в густой траве на опушках. В России Условно-съедобный гриб хорошего качества, употребляется в солёном и маринованном виде, иногда свежим во вторых блюдах.', '/media/mushrooms/placeholder.webp', NULL),
('15f798e8-53dd-5448-9e1f-72e017415907', 'Рядовка чешуйчатая', 'Рядовка коричневатая, Рядовка волокнисто-чешуйчатая, Сластушка', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Белый, желтоватый, светло-ржавый', 'Выпуклая', 'Рыжевато-коричневый, красновато-коричневый', 'Пластинчатая', 'Рядовка чешуйчатая встречается в смешанных или хвойных лесах, где много сосен. Увидеть этот вид грибов можно в лесистых местностях, где произрастает сосновый молодняк. Период массового плодоношения приходится на осень (сентябрь), а первый урожай этих грибов можно собрать уже в середине августа. Завершается же плодоносный период у сластушек примерно в середине октября. Гриб Рядовка чешуйчатая является съедобным, правда, некоторые грибники относят этот вид к условно-съедобным или несъедобным. Такая путаница возникает по причине того, что описываемый вид грибов изучен не до конца.', '/media/mushrooms/placeholder.webp', NULL),
('c1b2662a-27f3-5943-90c8-3aa700ad0c24', 'Боровик прекрасный', 'Боровик красивейший', NULL, 'Болетовые', false, 'Неизвестно', true, 40, 100, 'Утолщенная внизу', 'Красновато-коричневый, темно-красный', 'Выпуклая', 'Красноватый, коричневатый, желтоватый, оливково-коричневый', 'Трубчатая', 'Боровик прекрасный образует микоризу с такими хвойными деревьями: камнеплодник, лжетсуга тиссолистная и пихта великая. Сезон роста этого гриба припадает у грибников на конец лета и длится до конца осени. Боровик прекрасный относится к ядовитым грибам.', '/media/mushrooms/placeholder.webp', NULL),
('2bf61764-e243-5984-89d3-1e643b785869', 'Мухомор жемчужный', NULL, NULL, 'Аманитовые', false, 'Неизвестно', true, 10, 30, 'С юбкой', 'Белый', 'Выпуклая', 'Желто-коричневый, грязно-коричневый, красноватый', 'Пластинчатая', 'Встречается мухомор жемчужный достаточно часто. Это один из самых неприхотливых видов грибов. Произрастает на любых почвах, в любом лесу. Встречается летом и растет до поздней осени. Мухомор жемчужный - условно-съедобный гриб. В сыром виде не употребляется, его необходимо тщательно прожаривать. Для сушки не подходит, но его можно солить, замораживать или мариновать.', '/media/mushrooms/placeholder.webp', NULL),
('e9cbf0c7-d4ec-5701-b7d9-53f135e38290', 'Строфария сине-зеленая', NULL, NULL, 'Строфариевые', false, 'Неизвестно', true, 8, 20, 'С юбкой', 'Бледно-синеватый, бледно-зеленоватый', 'Выпуклая', 'Сине-зеленый', 'Пластинчатая', 'Строфария сине-зеленая растет группами или пучками на мертвых стволах и пнях хвойных деревьев, главным образом елей, сосен, пихт. Реже она встречается на мертвых лиственных деревьях. Плодовые тела обильно появляются летом и осенью, как в низинах, так и в горах. Строфарию сине-зеленую в Европе считают съедобным, но низкокачественным грибом. Перед приготовлением необходимо снимать со шляпки скользкую кожицу. В США этот гриб относят к числу ядовитых, так как там были отмечены случаи отравления строфарией сине-зеленой.', '/media/mushrooms/placeholder.webp', NULL),
('35260204-35a8-5796-b305-817b386ebf66', 'Галерина окаймленная', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 2, 5, 'Утолщенная внизу', 'Светло-желтый, рыжеватый', 'Выпуклая', 'Желто-бурый, охряный', 'Пластинчатая', 'Галерина окаймлённая произрастает с середины июня по октябрь в лесах различного типа, предпочитая сильно перегнившую древесину хвойных пород; часто растет на субстрате, погруженном в землю и от того невидимом. Плодоносит небольшими группами. Гриб крайне ядовит. Содержит токсины, аналогичные токсинам бледной поганки.', '/media/mushrooms/placeholder.webp', NULL),
('a0724fd3-4ada-590c-b9ad-0e66377fc90b', 'Головач гигантский', 'Дождевик гигантский, Лангермания гигантская', NULL, 'Шампиньоновые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Шелый, желто-зеленый', 'Гладкая', 'Гриб можно встретить практически везде, но наиболее часто в умеренном поясе. Встречается в одиночку, но появившись в одном месте он может исчезнуть совсем или не появляться очень долго. Такой вид получил название «метеорный». На территории России встречался в европейской части, в Карелии, на Дальнем Востоке, в Сибири в Красноярском крае. Также на Северном Кавказе. Растет в смешанных и лиственных лесах, на лугах, полях, на выгонах, в степях по одному. Съедобен в молодом возрасте, пока мякоть упругая, плотная и белого цвета.', '/media/mushrooms/placeholder.webp', NULL),
('0e34363c-611c-5513-a608-c6f51ac192c6', 'Подгруздок белый', 'Сухарь, Сухой груздь, Сыроежка превосходная, Сыроежка приятная', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'Беловатый', 'Вогнутая', 'Беловатый', 'Пластинчатая', 'Гриб растет с середины лета и до начала октября. Его ареал – березовые, осиновые, дубовые леса, смешанные леса. Гораздо реже встречается в хвойных лесах. В целом это довольно распространенный вид гриба на территории всей Евразии. Гриб относится к съедобным. Но вкусовые качества довольно-таки посредственные.', '/media/mushrooms/placeholder.webp', NULL),
('f6164463-21a7-54c8-9e20-c8b2fc12d1e2', 'Перечный гриб', 'Маслёнок перечный, Моховик перечный', NULL, 'Болетовые', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Медно-красный, темно-ржавый', 'Выпуклая', 'Медно-красный, темно-ржавый', 'Трубчатая', 'Перечный гриб обычен в сухих хвойных лесах, встречается довольно часто, но как правило, не слишком обильно, с июля и до конца осени. Также может образовывать микоризу с лиственными породами, например, с молодыми березами. Гриб, безусловно, не ядовит. Многие источники сообщают, что он «несъедобен по причине острого перечного вкуса».', '/media/mushrooms/placeholder.webp', NULL),
('7978307c-c9bb-579f-bacc-ab8e27b17c1e', 'Панеолус колокольчатый', 'Панеолус мотыльковый, Навозник колокольчатый, Навозник мотыльковый', NULL, 'Псатирелловые', false, 'Неизвестно', true, 2, 3, 'Ровная', 'Красноватый, черновато-коричневый, черный', 'Выпуклая', 'Беловатый, серый, красновато-коричневый, коричневатый', 'Пластинчатая', 'Растет в основном группами, иногда по одиночке, на почве, хорошо унавоженной коровьим или лошадиным навозом, часто прямо на навозе. Распространен на плодородных лугах и речных долинах, часто на или рядом с местами, где растет особенно высокая трава (навоз, плодородные почвы). Панеолус колокольчатый – гриб несъедобный, а некоторые источники утверждают, что даже ядовитый', '/media/mushrooms/placeholder.webp', NULL),
('4143113c-5be2-517b-aad1-a6c5514b2491', 'Говорушка дымчатая', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 30, 'Утолщенная внизу', 'Сероватый, беловатый', 'Ровная', 'Желтовато-беловатый, грязно-белый, сероватый', 'Пластинчатая', 'Говорушка дымчатая растет с начала сентября до ноября (массовое плодоношение в сентябре) в хвойных и смешанных (с дубом, елью) лесах, в светлых местах, на подстилке, группами, рядами, встречается нечасто, не ежегодно. Ядовитый гриб для многократного употребления: токсины постепенно накапливаются в организме, пока не вызывают желудочно-кишечные и неврологические отравления.', '/media/mushrooms/placeholder.webp', NULL),
('3356fc99-fd76-5f84-8746-d3661b8ef192', 'Рядовка грязная', 'Рядовка сорная, Синичка, Леписта грязная, Леписта сорная', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Сиреневый, буро-лиловый, коричневатый, красно-коричневый', 'Выпуклая', 'Сиреневый, буро-лиловый, коричневатый, красно-коричневый', 'Пластинчатая', 'Произрастает в садах, огородах, парках, скверах, на опушках лесов или не глубоко в светлых лесах. Может быть встречена на лугах. Растет группой/пучком из нескольких плодовых тел, реже встречается одиночно. Наиболее активное плодоношение этого вида рядовок начинается в июле и продолжается до конца сентября. Несмотря на малую известность среди любителей грибного собирательства, гриб рядовка грязная принадлежит к числу съедобных. Его желательно перед употреблением в пищу отварить, но отвар с него не годится для употребления и потому его лучше вылить.', '/media/mushrooms/placeholder.webp', NULL),
('3a532cf3-cb82-595b-8bea-1edd699f0c1b', 'Боровик королевский', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 40, 60, 'Утолщенная внизу', 'Желтовато-бурый', 'Выпуклая', 'Розовый, фиолетовато-красный, ровозовато-красный', 'Трубчатая', 'Встречается боровик королевский преимущественно в буковых и других лиственных лесах. В России распространен на Кавказе, а также редко встречается на Дальнем Востоке. Это гриб предпочитает песчаные и известковые почвы. Собирать это гриб можно с июня по сентябрь. Хороший съедобный гриб. Боровик королевский имеет душистую и плотную мякоть, которая очень высоко ценится. Употреблять этот гриб можно как в свежеприготовленном, так и в консервированном виде.', '/media/mushrooms/placeholder.webp', NULL),
('383a59c9-94d4-552b-bd22-e4fc3e1ebfc8', 'Валуй', 'Сыроежка вонючая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 20, 50, 'Ровная', 'Белый, сероватый, грязно-коричневый, красновато-коричневый', 'Выпуклая', 'Светло-охристый, красновато-коричневый, красновато-чёрный', 'Пластинчатая', 'Обычен в слегка влажных лесах, на тяжелых почвах, под лиственными и хвойными деревьями, как на равнинах, так и в горах. Обильно растёт по всей Европе, Азии и Северной Америке. Часто плодоносит большими группами. Начинает плодоносить с июля, при тёплой весне — даже с июня, до осени. Ряд зарубежных источников безоговорочно относит Валуй к несъедобным и даже ядовитым видам. Так, например, итальянский источник: «Во всех смыслах его следует рассматривать как ядовитую сыроежку, хотя неприятный запах почти автоматически отпугивает.» На территории бывшего СССР валуй считается вполне съедобным грибом, если уметь его приготовить. За Уралом Валуёв заготавливают огромными бочками, в основном их солят.', '/media/mushrooms/placeholder.webp', NULL),
('cbd6be4b-4fe9-5de4-b9e1-fa7babcaa202', 'Шампиньон лесной', 'Благушка', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 15, 'С юбкой', 'Грязно-белый, беловато-коричневатый', 'Выпуклая', 'Светло-рыжевато-коричневый, охристый, красновато-коричневый', 'Пластинчатая', 'Со второй половины лета, активно — с августа и до середины осени, при теплой погоде вплоть до конца ноября. Одиночно или группами, иногда образует «ведьмины круги». Гриб широко распространён по всей территории Европы, включая Англию и Ирландию, в Азии. Хороший съедобный гриб, особенно в молодом возрасте', '/media/mushrooms/placeholder.webp', NULL),
('09175a07-cfa9-5d15-8259-bd40a226512c', 'Зонтик белый', 'Зонтик полевой, Зонтик луговой', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 6, 12, 'С юбкой', 'Белый, желтоватый, буроватый', 'Выпуклая', 'Беловатый, кремовый, бурый', 'Пластинчатая', 'Съедобный гриб с приятным вкусом и запахом. Растет он в лесах, на лугах и в степях с мая по ноябрь, достигая особенно крупных размеров на гумусных степных почвах. За обильное плодоношение на лугах и в степях его называют иногда гриб-зонтик луговой.', '/media/mushrooms/placeholder.webp', NULL),
('43dc76c0-dad6-5c18-9a05-311f79e2d4d8', 'Рядовка голубиная', 'Рядовка сизоватая', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Белый, желтоватый', 'Ровная', 'Белый, желтоватый', 'Пластинчатая', 'Рядовка голубиная произрастает поодиночке или не небольшими группами с середины августа до конца сентября в лесах смешанного типа. Любит селиться по соседству с дубом и березой. Грибниками замечены случаи ее роста не только в лесу, но и на лугах и пастбищах. Рядовка голубиная является съедобной, применяется в большом разнообразии приготавливаемых блюд.', '/media/mushrooms/placeholder.webp', NULL),
('7b1b1ffa-2bb0-5efb-a183-e815f334012e', 'Паутинник съедобный', 'Толстушка', NULL, 'Паутинниковые', false, 'Неизвестно', true, 15, 20, 'Ровная', 'Беловато-буроватый', 'Выпуклая', 'Беловато-сероватый, глинистый', 'Пластинчатая', 'Распространен в европейской части России, в лесах Белорусии. Поселяется в хвойных лесах. Паутинник съедобный употребляется в пищу в жареном виде или в соленом.', '/media/mushrooms/placeholder.webp', NULL),
('5f89b274-c577-54ed-a58c-54e343f57ce2', 'Белый гриб сетчатый', 'Белый гриб дубовый, Боровик сетчатый, Белый летний гриб', NULL, 'Болетовые', true, 'Неизвестно', true, 20, 100, 'Утолщенная внизу', 'Беловатый, бежевый, светло-коричневый', 'Выпуклая', 'Светло-коричневый, коричневый, охристый', 'Трубчатая', 'Один из самых ранних видов белых грибов. Период плодоношения на территории стран СНГ с мая по октябрь, слоями. Растёт в лиственных и смешанных лесах. Образует микоризу с дубом, липой, буком, каштаном, орешником, грабом. Предпочитает теплый климат, чаще встречается в гористой и холмистой местностях, в средней полосе – светлые опушки и разреженные места, растёт на суховатых щелочных почвах. Превосходный съедобный гриб 1-й категории, ценится наравне с настоящим Белым грибом. Может подвергаться любым видам переработки.', '/media/mushrooms/placeholder.webp', NULL),
('d0a6031b-7d0e-5add-9d0a-8e9faa41c997', 'Сыроежка Мэйра', 'Сыроежка заметная', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, буроватый, желтоватый', 'Ровная', 'Насыщенно-красный, красновато-розовый', 'Пластинчатая', 'Сыроежки Мэйра широко распространены по всей территории Южной Европы. Встретить этот вид можно исключительно в лиственных буковых лесах. Сыроежка Мэйра считается слабо ядовитым, несъедобным грибом. Имеет горьковатый привкус мякоти. При употреблении в сыром виде может спровоцировать не сильное отравление желудочно-кишечного тракта.', '/media/mushrooms/placeholder.webp', NULL),
('4943bc3c-da0e-5fcb-88df-fdf4756fc401', 'Ежовик коралловидный', 'Коралловый гриб, Ежевик решетчатовидный, Гериций ветвистый, Гериций коралловидный, Гериций коралловый, Гериций решетчатовидный', NULL, 'Герициевые', true, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Белый, кремовый', 'Шипастая', 'Растет ежовик коралловидный с начала июля до середины сентября на пнях и валеже лиственных пород (осины, дуба, чаще березы), единично, очень редко. Ежовик коралловидный — гриб редкий или даже очень редкий. Считается съедобным грибом.', '/media/mushrooms/placeholder.webp', NULL),
('ecbeac4c-bab1-5aaa-8a0c-727fd0f01387', 'Рядовка скученная', 'Лиофиллум скученный, Рядовка групповая', NULL, 'Лиофилловые', false, 'Неизвестно', true, 5, 15, 'Утолщенная внизу', 'Белый, коричневатый', 'Выпуклая', 'Серо-коричневый', 'Пластинчатая', 'Поздний гриб; встречается с конца августа до конца октября в лесах различного типа, предпочитая специфические участки вроде лесных дорог, прореженных опушек; иногда попадается в парках, на лугах, в разнотравье. В большинстве случаев плодоносит крупными сростками. Рядовка скученная считается низкокачественным съедобным грибом..', '/media/mushrooms/placeholder.webp', NULL),
('bfbf5673-2dcb-5048-8197-47f56c65aa24', 'Млечник дубовый', 'Млечник нейтральный, Груздь дубовый, Млечник спокойный, Поддубник, Подорешник', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Коричнево-кремовый, коричневый', 'Ровная', 'Коричнево-кремовый', 'Пластинчатая', 'Млечник дубовый встречается часто и обильно с июня по октябрь, предпочитая леса с примесью дуба. Дубовый млечник, в принципе, съедобен, хотя не всем понравится специфический запах.', '/media/mushrooms/placeholder.webp', NULL),
('c63badde-bc21-5583-9aba-be37a5c6c748', 'Опёнок кирпично-красный', 'Гифолома кирпично-красная, Ложноопёнок кирпично-красный', NULL, 'Строфариевые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Беловатый, светло-охристый, коричневатый, светло-коричневый, ржаво-коричневый, красноватый, желтоватый', 'Выпуклая', 'Кирпично-красный, розовато-охристый, розоватый, ярко-красный', 'Пластинчатая', 'Ложноопёнок кирпично-красный широко распространён в Европе, Азии, Америке. Плодоносит с лета (конец июня-июль) и до осени, ноябрь-декабрь, вплоть до заморозков. Растёт группами и сростками на отмершей, гнилой, редко — живой древесине (на пнях и около пней, на крупном валеже, погружённых в землю отмерших корнях) лиственных пород, предпочитает дуб, встречается на берёзе, клёне, тополе, плодовых деревьях. Разные источники указывают очень разные данные о вкусе, от «мягкий», «немного горьковатый» до «горький». Часть русскоязычных источников относят кирпично-красного опёнка к несъедобным грибам или к условно-съедобным 4 категории.', '/media/mushrooms/placeholder.webp', NULL),
('a676a488-de00-58e6-8db8-9ebf9d40347b', 'Грабовик', 'Подберёзовик серый, Подберёзовик вязовый, Обабок серый', NULL, 'Болетовые', false, 'Неизвестно', true, 15, 40, 'Утолщенная внизу', 'Оливково-серый, буроватый, бурый', 'Выпуклая', 'Оливково-бурый, коричнево-серый', 'Трубчатая', 'В основном Грабовик встречается в районах Кавказа. Плодоносит гриб с июня по октябрь. Как правило, произрастает под грабом, отсюда и название – Грабовик. Съедобность: Грабовик хороший гриб, годный для употребления в сушеном, отварном, маринованном, соленом и жареном виде. Правда, его часто могут повреждать личинки.', '/media/mushrooms/placeholder.webp', NULL),
('f1d5f705-7edd-5d44-9a2e-6b1f7e67acc6', 'Весёлка обыкновенная', 'Фаллюс нескромный, Сморчок вонючий, Сморчок подагрический, Выскочка, Яйцо ведьм, Срамотник', NULL, 'Весёлковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Грязно-белый, желтоватый', 'Выпуклая', 'Буро-оливковый', 'Лабиринтовидная', 'Веселка имеет две стадии развития. Первая — гриб имеет яйцевидную форму, цвет грязно-белый, желтоватый. Под плотной кожурой веселки находится что-то слизистое, а под слизью прощупывается более жесткая структура. В стадии яйца веселка пребывает очень долго, возможно, несколько недель. Затем яйцо трескается, и веселка начинает с большой скоростью расти вверх. Вскоре формируется плодовое тело с высокой полой ножкой и маленькой прилегающей шляпкой «Яйца» веселки появляются в середине июля; шляпочнообразные плодовые тела развиваются несколько позже. Растет в траве, в кустарниках, в лиственном редколесье. Предпочитает богатые почвы. Считается, что в стадии яйца гриб съедобен; любителей, надо полагать, находится немного. Вместе с тем надо отметить, что веселка активно применяется в народной медицине.', '/media/mushrooms/placeholder.webp', NULL),
('5895e7a0-365e-5e93-b1f1-6d0607c5808a', 'Рядовка пятнистая', 'Рядовка крапчатая, Рядовка погубленная, Рядовка волнисто-ножковая', NULL, 'Рядовковые', false, 'Неизвестно', true, 20, 30, 'Ровная', 'Белый, грязно-белый, желтоватый', 'Выпуклая', 'Красно-коричневый', 'Пластинчатая', 'Пятнистые рядовки (Tricholoma pessundatum) грибники встречают на своём пути не часто. Период их активного плодоношения начинается в сентябре, а завершается – во второй половине октября. Этот вид рядовок предпочитает произрастать на кислых почвах, в ельниках, посреди сосновых песчаных боров. Чаще всего пятнистые рядовки встречаются в смешанных или хвойных лесах. Гриб рядовка пятнистая ядовит и не пригоден для употребления в пищу. И хотя уровень токсических веществ в плодовых телах этой рядовки невелик, при попадании в человеческий организм гриб часто вызывает расстройства желудочно-кишечного тракта и отравления.', '/media/mushrooms/placeholder.webp', NULL),
('f14ec603-19ed-5464-9210-f559f570b362', 'Серушка', 'Млечник извилистый, Серая дуплянка, Груздь серо-лиловатый, Серый млечник, Серянка, Подорешница, Подорожница, Путик', NULL, 'Сыроежковые', false, 'Неизвестно', true, 8, 30, 'Утолщенная вверху', 'Беловато-кремовый, светло-розовый, серый', 'Ровная', 'Серый, лилово-серый, коричневато-серый, серо-фиолетовый, серо-розовый, свинцовый, розовато-коричневый, серо-коричневый', 'Пластинчатая', 'Плодоносит с июля по октябрь, пик урожайности обычно приходится на сентябрь, хотя это сильно зависит от каждого региона и погодных условий, перед заморозками пропадает. Образует микоризу с берёзой и осиной. Растёт в берёзовых, осиновых и смешанных с ними лесах и парках, под орешником, по опушкам, на открытых поросших травой участках леса, вдоль лесных дорог и тропинок, на песчаных и суглинистых почвах, во влажных и заболоченных местах, в низинах. Предпочитает богатые, хорошо увлажнённые почвы. Встречается одиночно и группами, часто, иногда, особенно после дождей, очень обильно. Условно-съедобный гриб 3-й категории. Как и для большинства Млечников из-за горького жгуче-едкого вкуса необходимо предварительное отмачивание или отваривание.', '/media/mushrooms/placeholder.webp', NULL),
('f0a697fc-a00c-5367-919e-48f14f0ad5c6', 'Мухомор пантерный', 'Мухомор серый', NULL, 'Аманитовые', false, 'Неизвестно', true, 5, 15, 'С юбкой', 'Белый, желтоватый', 'Выпуклая', 'Серо-коричневый, оливково-серый, буроватый, белый, светло-бурый, коричневатый, оливково-грязный, сероватый', 'Пластинчатая', 'Гриб смертельно ядовит. Некоторые источники даже утверждают, что Мухомор пантерный опаснее, чем Бледная Поганка.', '/media/mushrooms/placeholder.webp', NULL),
('8914d03c-fe26-57de-a697-2af5f70ab667', 'Боровик коренящийся', 'Боровик коренастый, Болет глубокоукореняющийся, Боровик беловатый', NULL, 'Болетовые', false, 'Неизвестно', true, 30, 50, 'Утолщенная внизу', 'Лимонно-желтый, коричнево-оливковый, голубовато-зеленый', 'Выпуклая', 'Беловатый, серый, светло-палевый, зеленоватый', 'Трубчатая', 'Боровик коренящийся распространен в Европе, Северной Америке, Северной Африке, хотя везде встречается не часто. Теплолюбивый вид, предпочитает лиственные леса, хотя встречается в смешанных, чаще образует микоризу с дубом и березой. Встречается редко, с лета до осени. Боровик коренящийся несъедобен из-за горького вкуса, но не считается ядовитым.', '/media/mushrooms/placeholder.webp', NULL),
('3e1bb874-e5a2-591e-85f5-50d07d9db33c', 'Груздь перечный', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 12, 30, 'Утолщенная вверху', 'Белый', 'Выпуклая', 'Кремово-белый', 'Пластинчатая', 'Груздь перечный — микоризообразователь со многими деревьями. Часто встречающийся гриб. Произрастает рядами или кругами в сырых и затенённых лиственных и смешанных лесах, гораздо реже в хвойных. Предпочитает хорошо дренированные глинистые почвы. Встречается в средней полосе, к северу реже. Сезон лето—осень. Часто считается несъедобным из-за очень острого вкуса, хотя его можно употреблять как условно-съедобный после тщательной обработки для удаления горечи, идёт только в засол.', '/media/mushrooms/placeholder.webp', NULL),
('bcf29a0f-bb8e-5beb-9c34-594557631a2a', 'Моховик пёстрый', 'Моховик жёлтомясый, Моховик трещиноватый, Боровик пастбищный', NULL, 'Болетовые', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Желто-бурый, светло-желтый, красноватый', 'Выпуклая', 'Светло-бурый, темно-коричневый, краснгватый', 'Трубчатая', 'Съедобный гриб, четвертой категории, собирают в июле — октябре. Молодые грибы годятся для жаренья и маринования. Пригоден для сушки.', '/media/mushrooms/placeholder.webp', NULL),
('72d98b85-ed23-594c-9a20-07ab35121354', 'Саркосцифа алая', 'Саркосцифа ярко-красная, Саркосцифа киноварно-красная, Пецица красная, Алая эльфова чаша', NULL, 'Саркосцифовые', false, 'Неизвестно', true, 2, 5, 'Утолщенная вверху', 'Ярко-красный', 'Вогнутая', 'Ярко-красный', 'Гладкая', 'Встречается группами ранней весной (иногда в феврале), после таянья снега, на сухих веточках, погребенной древесине и других растительных остатках. В большинстве справочников по грибоводству написано, что саркосцифа алая принадлежит к категории съедобных грибов. Гриб не ядовит, и это означает, что получить серьёзное отравление при употреблении описываемого вида в пищу вряд ли получится. Однако грибная мякоть очень жёсткая, да и внешний вид саркосцифы алой не слишком аппетитен.', '/media/mushrooms/placeholder.webp', NULL),
('fa9850a8-26c7-574a-abbf-de8a252fd325', 'Лисичка трубковидная', 'Лисичка трубчатая, Лисичка ворончатая, Лисичка воронковидная', NULL, 'Лисичковые', false, 'Неизвестно', true, 3, 8, 'Ровная', 'Желтоватый, светло-коричневый', 'Ровная', 'Тускло-желтовато-бурый', 'Пластинчатая', 'Период обильного плодоношения начинается в конце августа, и продолжается до конца октября. Этот гриб предпочитает обитать в смешанных и хвойных лесах, большими группами (колониями). Хорошо себя чувствует на кислых почвах в лесу. Приравнивается к Лисичке настоящей, хотя гастроному едва ли принесет столько радости, а эстету не скоро еще наскучит до такой же степени. Как и все лисички, употребляется преимущественно в свежем виде, не требует подготовительных процедур вроде отваривания, а также, по сообщениям литераторов, не полнится червями.', '/media/mushrooms/placeholder.webp', NULL),
('83b1fd78-5d64-5988-bab7-23aeb5d4e2e9', 'Рядовка жёлто-бурая', 'Рядовка бурая, Рядовка буро-жёлтая, Рядовка жёлто-коричневая, Рядовка красно-бурая', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Буро-желтый, коричневатый', 'Выпуклая', 'Буро-желтый, красноватый', 'Пластинчатая', 'Встречается в основном в лиственных и смешанных лесах, но есть случаи произрастания и в хвойниках. Предпочитает исключительно березу, является микоризообразователем. Рядовка бурая является съедобным грибом, но по отзывам грибников – невкусная.', '/media/mushrooms/placeholder.webp', NULL),
('4ed30aa8-415d-5ac2-9d58-326b52ff7cb5', 'Зонтик краснеющий', 'Зонтик лохматый, Курятник', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 20, 'С юбкой', 'Серо-коричневый', 'Выпуклая', 'Коричневатый, буроватый, бурый', 'Пластинчатая', 'Зонтик краснеющий растет с июля до конца октября в хвойных и смешанных лесах, часто соседствует с муравейниками, растёт на полянах и лужайках. В период обильного плодоношения (обычно конец августа) может расти очень большими группами. Может обильно плодоносить и в октябре-ноябре. Хлорофиллум краснеющий — съедобный гриб. Обычно собирают только полностью раскрытые шляпки.', '/media/mushrooms/placeholder.webp', NULL),
('176a48c6-ae14-5d53-8ef2-ce72e8ed3fbb', 'Лисичка черная', 'Ворончик воронковидный, Вороночник рожковидный', NULL, 'Лисичковые', false, 'Неизвестно', true, 5, 10, 'Утолщенная вверху', 'Серый, коричневатый, черно-бурый', 'Вогнутая', 'Коричнево-черный, черный, коричневатый, серо-бурый', 'Гладкая', 'Лисичка черная растет с июля до последней декады сентября (массово с середины августа до середины сентября) в лиственных и смешанных лесах, во влажных местах, у дорог, группой-сростком и колонией, не часто. Съедобный гриб (4 категории), используются только шляпки (ножки жестко-резинистые).', '/media/mushrooms/placeholder.webp', NULL),
('e796bde2-c5b6-5262-87e9-35d563e3f167', 'Трутовик окаймлённый', 'Древесная губка, Сосновый трутовик', NULL, 'Фомитопсисовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Красный, темно-коричневато-красный, коричневый, черный, белый, желтый', 'Трубчатая', 'Окаймлённые трутовики относят к сапрофитам, провоцирует развитие бурой гнили. Встречается во многих регионах, но наиболее часто – на территории Европы и России.Трутовик окаймлённый успешно растёт на валежнике и сухостое не только хвойных, но и лиственных деревьев, на пнях. Съедобен. Используется для создания ароматизированных приправ со вкусом грибов. Является сырьём для гомеопатических лекарств. Успешно применяется в китайской народной медицине.', '/media/mushrooms/placeholder.webp', NULL),
('86d62a5e-e536-50fc-ade0-fdaa30ae6557', 'Говорушка ворончатая', 'Говорушка душистая, Говорушка пахучая, Воронка', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 10, 'Утолщенная вверху', 'Палевый, серовато-желтый', 'Вогнутая', 'Палевый, серовато-желтый', 'Пластинчатая', 'Говорушка ворончатая встречается с середины июля до конца сентября в лесах различного типа, вдоль дорог, нередко большими группами. Характерный признак: растет в подстилке, очень неглубоко. В молодом возрасте гриб съедобен.', '/media/mushrooms/placeholder.webp', NULL),
('8e2e98bf-8a03-59b0-a6c3-3314a29204c1', 'Рядовка тигровая', 'Рядовка ядовитая, Рядовка леопардовая', NULL, 'Рядовковые', false, 'Неизвестно', true, 8, 12, 'Ровная', 'Беловатый, зеленоватый, желтоватый', 'Выпуклая', 'Грязно-белый, серовато-белый, светло-серебристо-серый, черновато-серый, синеватый', 'Пластинчатая', 'Растёт на почве с августа по октябрь в хвойных и смешанных с хвойными, реже лиственных (с присутствием бука и дуба) лесах, на опушках. Предпочитает известковые почвы. Плодовые тела появляются как одиночно, так и небольшими группами, может образовывать «ведьмины круги», может расти небольшими «сростками». Гриб распространён во всей умеренной зоне Северного полушария, но довольно редок. Гриб ядовит, часто указывается как смертельно ядовитый. По данным токсикологических исследований, токсическое вещество точно не установлено.', '/media/mushrooms/placeholder.webp', NULL),
('f33a2c97-ed57-5a79-8ec4-20815dc72fb5', 'Гимнопил Юноны', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 15, 30, 'С юбкой', 'Оранжево-желтый, жёлтый, грязно-оранжевый, оранжево-коричневый', 'Выпуклая', 'Оранжево-желтый, жёлтый, грязно-оранжевый, оранжево-коричневый', 'Пластинчатая', 'Гимнопил Юноны плодоносит с середины лета и до середины-конца осени. Широко распространен на всех континентах: в Северной и Южной Америке, Европе, Азии. Сапрофит на гниющей древесине лиственных и (реже) хвойных пород. Может расти и на живой, ослабленной древесине. Обычно плодовые тела растут большими сростками, «гроздьями», часто в таком сростке может быть более двух десятков плодовых тел. Относится к несъедобным неядовитым грибам.', '/media/mushrooms/placeholder.webp', NULL),
('7a9b2870-d68b-593b-af68-8de0b77cdde8', 'Строчок обыкновенный', NULL, NULL, 'Дисциновые', false, 'Неизвестно', true, 20, 40, 'Ровная', 'Беловатый, сероватый, желтоватый, красноватый', 'Выпуклая', 'Каштаново-коричневый, темно-коричневый, красноватый', 'Гладкая', 'Встречается довольно редко, на песчаной незадерненной почве, на опушках леса, на вырубках, на обочинах дорог, тропинок, краях канав. Плодоносит с марта по май. Строчок обыкновенный — смертельно ядовитый гриб.', '/media/mushrooms/placeholder.webp', NULL),
('20161a8f-d3cc-5f17-a0d0-2f82f8e68811', 'Говорушка налиственная', 'Говорушка восковатая, Говорушка листолюбивая, Говорушка восковидная, Говорушка сероватая', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, грязновато-охряный', 'Ровная', 'Белый, телесный, коричневатый, охряный', 'Пластинчатая', 'Говорушка налиственная растёт в лесах, чаще на лиственном опаде, иногда на хвойном (ель, сосна), группами. Сезон активного плодоношения с сентября до поздней осени. Это распространённый в северной умеренной зоне вид, он встречается в материковой Европе, Великобритании и Северной Америке. Говорушка налиственная ядовита (содержит мускарин).', '/media/mushrooms/placeholder.webp', NULL),
('ab571984-c20a-50e2-a988-89dbb8556f3a', 'Рядовка бело-коричневая', 'Рядовка бело-бурая', NULL, 'Рядовковые', false, 'Неизвестно', true, 7, 20, 'Ровная', 'Белый, коричневый, бурый, красновато-бурый', 'Ровная', 'Светло-коричневый, коричневый, каштаново-бурый, красноватый', 'Пластинчатая', 'Рядовка бело-коричневая растет с августа и по октябрь, бывает замечена и в ноябре, преимущественно в хвойных (особенно, сухих сосновых), реже в смешанных (с преобладанием сосны) лесах. Образует микоризу с сосной. Растет группами, нередко большими (одиночно – редко), часто правильными рядами. Имеет очень широкий ареал распространения, встречается практически на всей территории Евразии, где имеются хвойные леса. Рядовка бело-коричневая относится к условно-съедобным грибам, используется после отваривания в течение 15 минут, универсального применения. Однако, в некоторых источниках, особенно зарубежных, она причислена к несъедобным грибам, а в некоторых – к съедобным, без приставки «условно-».', '/media/mushrooms/placeholder.webp', NULL),
('3eb484a3-732d-5b82-85d2-68a1c08b7315', 'Свинушка толстая', NULL, NULL, 'Тапинелловые', false, 'Неизвестно', true, 10, 40, 'Ровная', 'Бурый, темно-коричневый', 'Вогнутая', 'Коричневый, оливково-бурый', 'Пластинчатая', 'Свинушка толстая (Tapinella atrotomentosa) встречается не часто. Гриб начинает плодоношение с июля и растет до глубокой осени небольшими группами или в одиночку. Произрастает на корнях, пнях или на земле. Предпочитает хвойные деревья, а иногда и лиственные. О съедобности свинушки информация отсутствует, так, как до конца неизвестно, является ли он ядовитым, как и свинушка тонкая. К тому же мякоть толстой свинушки жесткая и горькая, что делает этот гриб несъедобным.', '/media/mushrooms/placeholder.webp', NULL),
('d984a25c-c58a-5f9e-a171-48116ba971a7', 'Маслёнок зернистый', 'Маслёнок летний, Маслёнок ранний', NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Светло-серо-желтый, желтый', 'Выпуклая', 'Красноватый, коричневато-бурый, желтоватый, желто-охряный', 'Трубчатая', 'Растет группами в сосновых лесах, где невысокая трава. Особенно много в сосновых лесах Кавказа. Съедобный гриб, второй категории. Собирают с июня по сентябрь, а в Южных районах и Краснодарском крае — с мая по ноябрь. Употребляют свежим, маринованным и соленым.', '/media/mushrooms/placeholder.webp', NULL),
('bd021eb4-ca3b-5a28-b565-7b60c8d047a0', 'Плютей олений', 'Олений гриб, Плютей бурый, Плютей тёмно—волокнистый', NULL, 'Плютеевые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Беловатый, грязно-белый, розоватый', 'Выпуклая', 'Бледно-коричневый, коричневый, серовато-коричневый, каштаново-коричневый, оливковый, серый, беловатый, коричневатый', 'Пластинчатая', 'Плютей олений растёт с весны и до поздней осени на древесине разных типов, одиночно, группами или небольшими сростками. Предпочитает лиственные, но может расти и в хвойных лесах. Растёт на валежной и погружённой в землю древесине, на пнях и возле них, может расти и у основания живых деревьев. Разные источники указывают разную информациюя: от несъедобного до съедобного, с рекомендацией отваривать непременно, не менее 20 минут.', '/media/mushrooms/placeholder.webp', NULL),
('01b5aeed-c2b7-54f6-86f2-2cb83f77af9d', 'Трутовик чешуйчатый', 'Пестрец', NULL, 'Полипоровые', false, 'Неизвестно', true, 10, 40, 'Утолщенная вверху', 'Буроватый, светло-желтый', 'Ровная', 'Темно-бурый, желтоватый', 'Гладкая', 'Встречается Трутовик чешуйчатый на живых и ослабленных деревьях в парках и широколиственных лесах. Произрастает группами или одиночно. Плодоносит с мая и до конца лета. Предпочитает леса южных районов. В средней полосе практически не встречается. Молодой Трутовик употребляется в пищу свежим, после предварительного отваривания. Так же можно есть маринованным и соленым. Съедобный гриб четвертой категории. Старые грибы в пищу не употребляются, так как становятся очень жесткими', '/media/mushrooms/placeholder.webp', NULL),
('b4da2e0d-9d48-5db9-bf31-628a7768b563', 'Печёночница обыкновенная', 'Печёночный гриб, Трутовик печёночный', NULL, 'Печёночницевые', false, 'Неизвестно', true, 10, 40, 'Утолщенная вверху', 'Беловатый, печеночно-красный, красновато-оранжевый, коричневато-красный', 'Ровная', 'Печеночно-красный, красновато-оранжевый, коричневато-красный', 'Трубчатая', 'Плодовые тела однолетние. Печёночница растет в одиночку или небольшими группами у основания деревьев и на пеньках, с начала лета и до середины осени. Иногда можно встретить печёночницу, растущую как будто из земли, но если раскопать основание стебля, там непременно найдётся толстый корень. Широко распространена на всех континентах, где есть дубовые леса. Печёночница съедобна. Слишком взрослые, переросшие грибы могут иметь чуть больше кисловатого привкуса.', '/media/mushrooms/placeholder.webp', NULL),
('5a72e480-2032-5962-a9bd-cd621f0dda69', 'Опенок толстоногий', 'Опенок луковицеобразный', NULL, 'Физалакриевые', false, 'Неизвестно', true, 5, 20, 'Утолщенная внизу', 'Серовато-желтый, беловатый', 'Выпуклая', 'Серовато-желтый', 'Пластинчатая', 'Опенок толстоногий растет с августа по октябрь (иногда попадается и в июле) на гниющих остатков деревьев, а также на почве (особенно на еловой подстилке). Эта разновидность, как правило, не поражает живые деревья, да и плодоносит не слоями, а постоянно (правда, не настолько обильно). На почве растет большими группами, но в крупные пучки, как правило, не срастается. Один из самых популярных грибов, заготавливаемый в промышленных масштабах.', '/media/mushrooms/placeholder.webp', NULL),
('37d81cb8-60d7-5892-8232-4651a1ed486c', 'Млечник камфорный', 'Груздь камфорный', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Темно-красный, коричневатый', 'Ровная', 'Темно-красный, коричневый', 'Пластинчатая', 'Сезон: с июля по конец сентября. Гриб имеет очень сильный специфический запах, а потому спутать его с другими видами данного семейства достаточно сложно. Млечник камфорный относится к съедобным видам грибов, но его вкусовые качества низкие. В пищу употребляют (варят, солят).', '/media/mushrooms/placeholder.webp', NULL),
('4e487637-1d75-5c13-ac70-71ce6bb928cd', 'Серная голова', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 3, 6, 'Утолщенная внизу', 'Белый, янтарный, голубоватый', 'Ровная', 'Желтый, каштановый', 'Пластинчатая', 'Время сбора: Август — конец декабря. Растет по отдельности или небольшими группами, на упавших деревьях, бревнах и в сырой траве. Относится к активным несъедобным грибам.', '/media/mushrooms/placeholder.webp', NULL),
('b11a159f-f409-5698-8ffc-d494ee1663ae', 'Боровик золотистый', 'Боровик вересковый', NULL, 'Болетовые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Жёлтый, красноватый, коричневый, коричневато-желтоватый, красноватый', 'Выпуклая', 'Красновато-коричневый, пурпурно-коричневый, коричневый', 'Трубчатая', 'Растут одиночно или небольшими группами, летом и осенью. В Европе этот гриб встречается очень редко. Основной регион золотистого боровика — это Северная Америка (США, Мексика, Канада), Тайвань. В Европе золотистый боровик встречается в основном в Литве. Есть сообщения, что золотистый боровик находили в Калининградской и в Ленинградской областях. Съедобный гриб. Литовские грибники утверждают, что по вкусу золотистые боровики уступают обычным литовским боровикам, но привлекают тем, что они редко бывают червивыми и растут в доступных местах.', '/media/mushrooms/placeholder.webp', NULL),
('cce7bc0b-f86a-5e5b-8454-da70154f00db', 'Рядовка заостренная', 'Рядовка мышиная, Рядовка полосатая, Рядовка жгуче-острая', NULL, 'Рядовковые', false, 'Неизвестно', true, 15, 20, 'Утолщенная внизу', 'Беловатый, сероватый', 'Выпуклая', 'Пепельно-серый, темно-серый', 'Пластинчатая', 'Растёт во влажных лиственных и хвойных лесах. Встречается часто в сентябре — октябре. Гриб ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('9636546d-5ac8-59ac-b936-5fc519fc2809', 'Подгруздок чернеющий', 'Сыроежка чернеющая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 25, 'Утолщенная вверху', 'Беловатый, грязновато-коричневый', 'Вогнутая', 'Беловатый, грязно-сероватый, коричневый, буроватый, оливковый', 'Пластинчатая', 'Подгруздок чернеющий образует с твердыми породами деревьев грибницу. Растет в лиственных, смешанных лесах. Также гриб часто можно увидеть в еловых и широколиственных лесах. Излюбленное место распространения – умеренная полоса, а также регион Западной Сибири. Гриб не редок и на территории Западной Европы. Начинает плодоносить с середины лета, и завершается этот период вплоть до зимы. Подгруздок чернеющий относится к грибам четвертой категории. Его можно употреблять свежим (после того, как тщательно отварить не менее 20 минут), а также соленым.', '/media/mushrooms/placeholder.webp', NULL),
('30380f3a-6e37-51c8-8aca-39cdda4b7c65', 'Коллибия широкопластинчатая', 'Мегаколлибия широкопластинковая, Удемансиелла широкопластинковая, Денежка широкопластинчатая', NULL, 'Негниючниковые', false, 'Неизвестно', true, 5, 30, 'Утолщенная внизу', 'Серый, грязно-белый, бурый', 'Выпуклая', 'Серый, коричневатый', 'Пластинчатая', 'Коллибия широкопластинчатая плодоносит с конца мая и встречается до окончания сентября. Наиболее урожайным является первый весенний слой. Предпочитает перегнившие пни лиственных деревьев и лесной опад. Некоторые источники указывают гриб Коллибия широкопластинчатая, как условно-съедобный, другие, относят его к съедобным.', '/media/mushrooms/placeholder.webp', NULL),
('f71f0eea-296b-58a0-b5f1-8736d2d62ea7', 'Псилоцибе кубенсис', 'Сан-Исидро, Псилоцибе кубинская', NULL, 'Гименогастровые', false, 'Неизвестно', true, 4, 10, 'С юбкой', 'Белый, голубоватый', 'Выпуклая', 'Бледно-желтоватый, коричневатый', 'Пластинчатая', 'Растет на юге США, в Центральной Америке, субтропических регионы, на навозе. В РФ выращивается искусственно в домашних условиях на субстрате культуры. Согласно перечню наркотических средств, плодовые тела любого вида грибов, содержащих псилоцибин и (или) псилоцин считаются наркотическим средством и запрещены к обороту на территории Российской Федерации. Сбор, употребление и реализация плодовых тел Psilocybe cubensis запрещены и в других странах.', '/media/mushrooms/placeholder.webp', NULL),
('6e503bd2-ef81-5c31-993a-92fc44a6d2e1', 'Белый гриб берёзовый', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 20, 40, 'Утолщенная внизу', 'Беловато-коричневый', 'Выпуклая', 'Беловато-охряный, светло-желтый, беловатый', 'Трубчатая', 'Чаще всего его можно найти вдоль дорог и на опушках. Наибольшее распространение белый гриб березовый приобрел в Мурманской области, встречается также в Западной и Восточной Сибири, на Дальнем Востоке, Западной Европе. Произрастает гриб местами довольно обильно и встречается часто, причем как группами, так и одиночно. Сезоном для белого гриба березового является период с июня по октябрь. Белый гриб березовый является съедобным грибом. Его пищевые качества ценятся так же, как и белого гриба.', '/media/mushrooms/placeholder.webp', NULL),
('74c3d304-564a-5231-994b-6f400b9ac288', 'Гигрофор поздний', 'Гигрофор бурый, Мокрица, Сластена', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Желтоватый', 'Вогнутая', 'Желто-коричневый, оливковый', 'Пластинчатая', 'Гигрофор поздний встречается с середины сентября и до глубокой осени, не боясь заморозков и первого снега, в хвойных и смешанных лесах, соседствуя с сосной. Часто растет во мхах, скрываясь в них по самую шляпку; в удачное время может плодоносить большими группами. Гигрофор бурый — вполне съедобный, невзирая на маленькие размеры, гриб; особое время плодоношения придает ему большую ценность в глазах заготовителей.', '/media/mushrooms/placeholder.webp', NULL),
('2d312e4a-4149-5238-9fb4-71502028a1ee', 'Ложнодождевик обыкновенный', 'Дождевик ложный, Ложный дождевик, Ложнодождевик оранжевый, Ложнодождевик лимонный', NULL, 'Ложнодождевиковые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Грязно-желтый, буроватый', 'Гладкая', 'Ложнодождевик обыкновенный растёт в лиственных и хвойных лесах, вдоль дорог, по опушкам, на глинистой и суглинистой почве в августе — сентябре. Ложнодождевик обыкновенный — Несьедобный, но только в больших дозах.', '/media/mushrooms/placeholder.webp', NULL),
('e641fb34-dfc7-5715-9dfd-278883b93023', 'Груздь желтый', 'Подгруздь жёлтый, Гриб подскрёбыш, Волнуха жёлтая, Груздь ямчатый', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 35, 'Ровная', 'Белый, буроватый', 'Выпуклая', 'Золотисто-желтый', 'Пластинчатая', 'Растет в северной части лесной зоны и в Сибири, в еловых, пихтовых, иногда в смешанных лесах, предпочитая молодые ельники и сосняки, реже селится в березняках, на глинистой почве. В хвойном лесу груздь желтый растет под елками даже в октябре. Условно съедобный гриб, первой категории. Собирают в июле — сентябре. Гриб солят, маринуют.', '/media/mushrooms/placeholder.webp', NULL),
('ec2ade1f-5bb6-5954-8a43-579db3376b54', 'Рядовка фиалковая', 'Леписта фиалковая', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Беловатый, розовато-кремовый', 'Выпуклая', 'Белесый, матовый, розовато-коричневый', 'Пластинчатая', 'Рядовка фиалковая — осенний гриб, встречается в сентябре-октябре одновременно с рядовкой фиолетовой, и нередко в тех же местах, предпочитая прореженные опушки лесов, как хвойных, так и лиственных. Растет рядами, кругами, группами. Рядовка фиалковая — хороший съедобный гриб, на уровне фиолетовой рядовки.', '/media/mushrooms/placeholder.webp', NULL),
('5c8d8cf2-754f-5cf7-955b-5540964a3bc0', 'Млечник обыкновенный', 'Гладыш, Дуплянка жёлтая, Груздь сизый, Ольшанка, Подольховик, Серушка болотная', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 30, 'Ровная', 'Бледно-сероватый, бледно-охряный, желтоватый, красноватый', 'Ровная', 'Сизо-серый, свинцово-серый, фиолетово-серый, серо-коричневатый, лилово-коричневатый', 'Пластинчатая', 'Вид широко распространён в Северной Америке и Евразии, в лесной зоне умеренного климатического пояса. В России распространён в Европейской части, Сибири, на Урале и Дальнем Востоке. Сезонность с июля по октябрь. Образует микоризу с берёзой, елью и сосной. Растёт во влажных лиственных, смешанных и хвойных лесах, часто во влажных местах, в низинах, по краям сфагновых болот, во мху и траве, в кустарниках и черничниках, на полянах, в зарослях ольхи, вдоль тропинок и лесных дорог. Условно-съедобный гриб 2-й категории. Традиционно используется для соления и маринования, из-за горького жгуче-едкого вкуса необходимо предварительное отмачивание или отваривание.', '/media/mushrooms/placeholder.webp', NULL),
('f348aa14-4458-5740-b930-c49cfdf230a4', 'Вёшенка лёгочная', 'Вешенка беловатая, Вешенка весенняя, Вешенка буковая', NULL, 'Вёшенковые', false, 'Неизвестно', true, 5, 20, 'Утолщенная вверху', 'Грязно-белый', 'Ровная', 'Беловато-серый, желтоватый', 'Пластинчатая', 'Вешенка легочная растет с мая до октября на гниющей древесине, реже на живых ослабленных деревьях. При хороших условиях появляется большими группами, срастаясь ножками в пучки. Нормальный съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('6a9d36a7-1ae9-522b-81ab-0d7364f7b890', 'Лаковица обыкновенная', 'Лаковица розовая, Лаковица лаковая', NULL, 'Гиднангиевые', false, 'Неизвестно', true, 1, 5, 'Ровная', 'Розовый, морковно-красный, желто-рыжий', 'Ровная', 'Розовый, морковно-красный, желто-рыжий', 'Пластинчатая', 'Лаковица розовая повсеместно встречается с июня по октябрь в лесах, на опушках, в парках и садах, избегая лишь чрезмерно сырых, сухих и затемненных мест. Относится к условно-съедобным грибам.', '/media/mushrooms/placeholder.webp', NULL),
('e615205f-9228-5fa7-9d8a-94fda380d1c8', 'Вёшенка степная', 'Вёшенка королевская, Белый степной гриб, Еринги, Однобочка, Боровик древесный, Королевский трубач', NULL, 'Вёшенковые', false, 'Неизвестно', true, 15, 20, 'Утолщенная вверху', 'Белый, охристо-бурый', 'Ровная', 'Красно-коричневый, буроватый, серовато-рыжий, грязно-белый, желтоватый', 'Пластинчатая', 'В России распространён в южных регионах: в пустынно-степных предгорьях Средней Азии, Нижнем Поволжье, причерноморских районах, Кавказе, Крыму. Сезонность с конца марта по июнь и с сентября по январь. Обитает вне леса, на открытых пространствах – полупустынной, горно-степной и сухой степной местности, на лугах, полях, пастбищах, пустошах. Превосходный съедобный гриб 3-й категории.', '/media/mushrooms/placeholder.webp', NULL),
('6d8eeab9-4f5e-55bb-aabd-5123de4dab46', 'Мухомор белый', 'Мухомор весенний, Весенняя поганка', NULL, 'Аманитовые', false, 'Неизвестно', true, 7, 25, 'С юбкой', 'Белый', 'Ровная', 'Белый', 'Пластинчатая', 'Мухомор белый растёт во влажных хвойных и смешанных лесах в июне — августе. Гриб смертельно ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('82d4a9d8-b19e-5c0f-aa12-e36e881f7da7', 'Решёточник красный', 'Решетчатка, Решетник, Клатрус красный', NULL, 'Весёлковые', true, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Красный, беловатый, желтоватый', 'Гладкая', 'Растет решеточник красный одиночно или гнездами на почве в широколиственных лесах, очень редко в смешанных. Найден однажды в Московской области, изредка встречается в Краснодарском крае. Представляет собой несъедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('73973918-9fae-54da-86cb-9e8c18f8d1ff', 'Моховик припорошенный', 'Болет запылённый, Моховик припудренный', NULL, 'Болетовые', false, 'Неизвестно', true, 10, 35, 'Утолщенная внизу', 'Желтый, красно-коричневый, красно-бурый, ржаво-коричневый, темно-синий, черновато-синий', 'Выпуклая', 'Серо-коричневый, серовато-желтоватый, темно-коричневый, красно-коричневый', 'Трубчатая', 'C августа по сентябрь в лиственных и смешанных лесах (часто с дубом елью), чаще группами и одиночно, встречается редко, чаще в теплых южных регионах (на Кавказе, в Украине, на Дальнем Востоке). Малоизвестный съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('a3c95228-c53a-51b1-8e5b-31f946b5ae15', 'Рядовка мыльная', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная вверху', 'Грязно-белый, коричневатый', 'Выпуклая', 'Охристо-серый, серый, серо-оливковый, черновато-коричневый, голубоватый, свинцовый, зеленоватый', 'Пластинчатая', 'Рядовка мыльная считается широко распространенным грибом. Гриб встречается в хвойных (образует микоризу с елью) и лиственных лесах, а также лугах с конца августа до конца октября большими группами. Рядовка мыльная по своему внешнему виду очень похожа на серую рядовку, от которой отличается более темным цветом пластинок, оливковыми тонами шляпки, розоватой мякотью (в ножке) и заметным неприятным запахом. От зеленушки отличается редкими светлыми (не зеленовато-желтыми) пластинками и неприятным запахом. Еще похожа на условно-съедобную, покрытую коричневыми пятнами рядовку бурую, растущую преимущественно на перегнойной почве под березами и обладающую выраженным грибным запахом.', '/media/mushrooms/placeholder.webp', NULL),
('29ea7c39-6b9f-5106-984d-c28ba4926900', 'Ложносвинуха рядовковидная', 'Ложносвинуха лепистовидная, Белосвинуха лепистовидная, Жировик', NULL, 'Рядовковые', true, 'Неизвестно', true, 20, 50, 'Утолщенная внизу', 'белая, желтовато-Белый, серовато-белый, серовато-голубоватый', 'Выпуклая', 'Беловатый, светло-серый, желтовато-кремовый, голубовато-зеленоватый', 'Пластинчатая', 'Оптимальным временем плодоношения является период с июля по октябрь, в более южных регионах встречается с апреля. Гумусовый сапротроф. Обитает в степях и в остепнённых лесах на плодородных почвах тяжёлого механического состава. Растет на пастбищах, лугах, на травянистых местах и лесах различного типа, предпочитает влажную почву. Хороший съедобный гриб. Ложносвинуха рядовковидная обладает отменными пищевыми качествами. Перед приготовлением любого блюда из данного ингредиента не требуется предварительная обработка.', '/media/mushrooms/placeholder.webp', NULL),
('0398be35-c3d5-5923-b0c9-3766555361c0', 'Белый гриб бронзовый', 'Рудяк, Дубовый гриб, Боровик бронзовый, Боровик темно-каштановый, Болет бронзовый, Белый гриб грабовый', NULL, 'Болетовые', true, 'Неизвестно', true, 20, 70, 'Утолщенная внизу', 'Бежевый, оранжево-коричневый, каштаново-коричневый, белый, беловатый', 'Выпуклая', 'Темно-коричневый, каштаново-коричневый, черно-коричневый', 'Трубчатая', 'Период плодоношения на территории стран СНГ с июля по октябрь. Предпочитает богатые перегноем, влажные почвы смешанных лесов, горные и холмистые местности. Растет под дубом, буком, грабом, хотя, бывает, и под сосной. В наших краях предпочитает южные регионы. Встречается редко, одиночно и малыми группами. Превосходный съедобный гриб 1-й категории, ценится наравне с настоящим Белым грибом. Может подвергаться любым видам переработки.', '/media/mushrooms/placeholder.webp', NULL),
('1765c276-f1a1-501b-8af3-0e5b318caa79', 'Чесночник обыкновенный', 'Негниючник обыкновенный', NULL, 'Омфалотовые', false, 'Неизвестно', true, 2, 8, 'Ровная', 'Красновато-бурый', 'Выпуклая', 'Желто-буроватый, охристый, палевый', 'Пластинчатая', 'Чесночник Обыкновенный встречается в лесах разного типа. Произрастает в сухих местах на лесной подстилке. Предпочитает песчаные и глинистые почвы. Как правило, встречается большими группами. Период плодоношения с июля по октябрь. Чесночник своим названием обязан сильному чесночному запаху, который усиливается в пасмурные дождливые дни. Поэтому характерному признаку, легче находить колонии этого гриба. Чесночник обыкновенный — съедобный гриб, употребляется в жареном, отварном, сушеном и маринованном виде. Применяют для приготовления острых пряностей. Характерный запах гриба после отваривания исчезает, при сушке усиливается.', '/media/mushrooms/placeholder.webp', NULL),
('259ae5b1-65dd-5ccb-9373-051e63427d3b', 'Белый гриб сосновый', 'Боровик, Белый гриб боровой, Болетус соснолюбивый', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 100, 'Утолщенная внизу', 'Белый, кремовый, красноватый', 'Выпуклая', 'Бордово-коричневый, красно-коричневый, бордовый', 'Трубчатая', 'Период плодоношения на территории стран СНГ с июня по октябрь. Отмечаются случаи нахождения грибов в мае и декабре в регионах с боле тёплым климатом. Плодоносит так называемыми «волнами» (как правило, в середине июня и в конце августа – начале сентября). Растёт в хвойных, лиственных и смешанных лесах. Чаще всего образует микоризу с сосной, реже с елью и пихтой, ещё реже с дубом, буком, грабом, каштаном. Предпочитает песчаные почвы, наиболее характерные места – светлые сосновые боры-беломшанники. Встречается одиночно, большими группами. Превосходный съедобный гриб 1-й категории, обладает великолепным вкусом и прекрасным ароматом. Может подвергаться любым видам переработки. При сушке грибы сохраняют природный цвет и приобретают особый аромат.', '/media/mushrooms/placeholder.webp', NULL),
('8245faa4-fdb1-5a26-a675-58cccb1cba09', 'Гиднеллум Пека', 'Ежовик дьявольский', NULL, 'Банкеровые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Белый, бежевый, коричневый, кроваво-красный', 'Шипастая', 'Это достаточно распространенный несъедобный гриб, который произрастает в хвойных лесах Европы и Северной Америки. Он, как и шампиньоны, относится к агариковым грибам, но, в отличие от них, несъедобен. Существуют разработки, которые направлены на получение сыворотки на основе яда из данного гриба. Гиднеллум пека обладает хорошими антибактериальными качествами и содержит в своем составе химические соединения, способные разжижать кровь.', '/media/mushrooms/placeholder.webp', NULL),
('1e14cab1-be39-5b70-93f7-5f46f5e454b3', 'Вёшенка осенняя', 'Вёшенка поздняя, Вёшенка ольховая, Панеллюс поздний', NULL, 'Миценовые', false, 'Неизвестно', true, 10, 30, 'Утолщенная вверху', 'Желтый, желтовато-белый', 'Выпуклая', 'Зелено-коричневый, серо-бурый', 'Пластинчатая', 'Вёшенка осенняя растет на пнях и останках древесины различных лиственных пород, предпочитая древесину клена, осины, вяза, липы, берёзы и тополя; реже встречается на хвойниках. Растут грибы, группами в основном срастаются ножками, друг над другом, образуя что-то похожее на кровлю. Вёшенка осенняя, гриб условно-съедобный. В пищу можно употреблять после предварительного отваривания в течение 15 минут и более. Отвар необходимо слить. Есть гриб можно только в молодом возрасте, позже он становится очень жестким со скользкой толстой кожицей. Также гриб немного утрачивает вкусовые качества после морозов, но при этом остается вполне съедобным.', '/media/mushrooms/placeholder.webp', NULL),
('3f6f5044-5f97-5308-841f-cac7e23658e4', 'Шампиньон двуспоровый', 'Шампиньон королевский, Шампиньон коричневый', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 30, 'С юбкой', 'Белый, буроватый', 'Выпуклая', 'Беловатый, желтоватый, коричневатый, бурый', 'Пластинчатая', 'Шампиньон двуспоровый растет с самого конца мая до конца сентября на открытых пространствах и окультуренной почве, рядом с человеком, в садах, огородах, в теплицах и канавах, на улицах, на пастбищах, редко в лесах, на почве, где совсем мало или нет травы, не часто. Культивируется во многих странах. Шампиньон двуспоровый — Вкусный съедобный гриб (2 категории), используется, как другие виды шампиньонов.', '/media/mushrooms/placeholder.webp', NULL),
('fd70464a-b7f5-5bc5-86c5-ce27e5613a43', 'Шампиньон полевой', 'Шампиньон обыкновенный, Шампиньон тротуарный', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 30, 'С юбкой', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Летом и осенью полевой шампиньон растет на лужайках и полянах, в садах, у живых изгородей. В лесу встречаются родственные грибы с запахом аниса и желтеющей мякотью. Широко распространён и обильно растёт на почве, в основном на открытых пространствах, поросших травой, — на лугах, лесных полянах, по обочинам дорог, на вырубках, в садах и парках, реже на пастбищах. Встречается как на равнине, так и в горах. Плодовые тела появляются одиночно, группами или большими группами; часто образуют дуги и кольца. Часто растёт рядом с крапивой. Возле деревьев редок; исключение составляют ели. Распространён по всей территории России. Обычен в северной умеренной зоне. Сезон: с конца мая до середины октября—ноября. Превосходный съедобный гриб. Многие знатоки грибов предпочитают его всем другим шампиньонам.', '/media/mushrooms/placeholder.webp', NULL),
('53e6e176-575f-580a-b19a-f5920bf327bf', 'Рыжик еловый', 'Еловик, Рыжик зелёный', NULL, 'Сыроежковые', true, 'Неизвестно', true, 8, 25, 'Утолщенная вверху', 'Оранжевый, красноватый', 'Вогнутая', 'Оранжевый, красноватый, коричневатый', 'Пластинчатая', 'Период активного плодоношения с августа по октябрь, может встречаться с июня по ноябрь. Образует микоризу с елью и толокнянкой обыкновенной. Растёт в еловых и смешанных с елью лесах на засыпанной хвоей лесной подстилке, на песчаных, торфяных, камбизольных почвах, предпочитает известняки. Не любит излишнего тепла, встречается часто, группами и большими группами, предпочитает расти под елями, в затенённых влажных местах. В смешанных сосново-еловых лесах может расти вперемежку с Рыжиком настоящим. Превосходный съедобный гриб 1-й категории. Традиционно используется солёным, маринованным, варёным, жареным и, даже, сырым. В заготовках зеленеет.', '/media/mushrooms/placeholder.webp', NULL),
('0886918e-d4b9-59d1-87af-cdf26193d136', 'Груздь водянистозоновый', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 20, 40, 'Ровная', 'Кремовый, желтоватый', 'Вогнутая', 'Белый, желтоватый', 'Пластинчатая', 'Растут грибы кучно, грудами, откуда и происходит их название. Найти их бывает не так просто — грузди умело маскируются в черных опавших листьях. Наилучшие погодные условия для роста груздей — теплые ночи и туманы, тогда грибы растут очень обильно. В дождливую погоду очень часто загнивает в молодом возрасте, т.к. полностью скрыт в прошлогодней листве. Условно-съедобный гриб. Некоторые находят возможным мариновать молодые грузди, но основные вкусовые качества гриба раскрываются в соленом виде.', '/media/mushrooms/placeholder.webp', NULL),
('7cff61de-50d7-5f04-b9c9-844bc995b1a9', 'Подберезовик розовеющий', 'Березовик окисляющийся, Березовик разноцветный, Березовик пёстрый', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 50, 'Утолщенная внизу', 'Белый, буроватый', 'Выпуклая', 'Желто-бурый, мраморный', 'Трубчатая', 'Произрастает Подберезовик розовеющий (Leccinum oxydabile) в северных сырых лесах и в тундрах, а также на высокогорьях с тем или иным видом древесных и кустарниковых берез. Известен на севере Западной Европы. В России его обычно собирают и используют в пищу вместе с березовиком обыкновенным. Съедобный гриб, второй категории. Годится для употребления в пищу в любом виде — свежем и сушеном.', '/media/mushrooms/placeholder.webp', NULL),
('b6c1d643-1158-59e2-b6d2-04d4e527813d', 'Лисичка бледная', 'Лисичка белая, Лисичка светлая', NULL, 'Лисичковые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Желтовато-белый', 'Вогнутая', 'Желтовато-белый', 'Пластинчатая', 'Гриб лисичка бледная встречается редко, отдаёт предпочтение лиственным лесам, участкам с естественной лесной подстилкой, или покрытым мхом и травой. В основном гриб растёт группами и колониями, как и все разновидности семейства лисичковых. Плодоношение бледной лисички начинается в июне, а завершается в сентябре. Бледные лисички принадлежат ко 2-й категории съедобности. Несмотря на устрашающее название, которое у многих сразу ассоциируется с бледной поганкой и её ядовитостью, бледные лисички отнюдь не представляют опасности для здоровья человека. Больше того, этот вид грибов вкусен и полезен', '/media/mushrooms/placeholder.webp', NULL),
('649f7ea3-967a-570b-946c-ed0a87128a1d', 'Груздь золотисто-желтый', 'Груздь золотисто-млечный, Млечник золотистый', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'Желто-охристый, розоватый', 'Выпуклая', 'Розовато-оранжелый', 'Пластинчатая', 'Встречается небольшими группами или поодиночке в лиственных лесах в основном под каштанами и дубами, в горах и на холмах. Сезон - лето-осень. Несъедобен.', '/media/mushrooms/placeholder.webp', NULL),
('a26b634a-7a59-5116-8c6c-56c6d7364e79', 'Паутинник голубовато-опоясанный', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 20, 60, 'Утолщенная внизу', 'Грязно-белый, коричневатый, желтоватый', 'Выпуклая', 'Сероватый, коричневый, голубоватый', 'Пластинчатая', 'Предпочитает расти в лиственных лесах, но встречается и в хвойных. Любит влажные почвы, особенно, если в них много кальция. Растет группами. Сезонность – август – сентябрь – начало октября. Считается несъедобным грибом.', '/media/mushrooms/placeholder.webp', NULL),
('709b7f9a-c6fc-583d-bc7c-e9be8e29315d', 'Рядовка исполинская', 'Рядовка-колосс, Рядовка-исполин, Рядовка огромная, Рядовка гигантская', NULL, 'Рядовковые', true, 'Неизвестно', true, 20, 60, 'Утолщенная внизу', 'Беловатый, коричневатый', 'Выпуклая', 'Рыжевато-коричневый, красноватый, коричневый', 'Пластинчатая', 'Исполинская рядовка образует микоризу с сосной, плодоносить начинает в августе и даёт урожай до конца сентября. Гриб предпочитает обитать преимущественно в сосновых лесах. Встретить рядовку исполинскую можно в смешанных лесах, в горной части Крымского полуострова. Рядовка исполинская является съедобным грибом, однако из-за редкости вида собирать такие рядовки не рекомендуется. К тому же, в некоторых регионах России и Европы этот гриб считается редким, и занесён в Красную Книгу.', '/media/mushrooms/placeholder.webp', NULL),
('fa689c4b-096a-5c0f-9f98-54378144653b', 'Чешуйчатка разрушающая', 'Чешуйчатка тополиная', NULL, 'Строфариевые', true, 'Неизвестно', true, 30, 60, 'Утолщенная внизу', 'Белый', 'Выпуклая', 'Желтовато-коричневый, беловатыми, беловато-желтоватый, желтовато-коричневый', 'Пластинчатая', 'Сапрофит. Растёт одиночно или небольшими группами, иногда в сростках на валежной древесине тополя разных видов, а иногда, реже, и на древесине других лиственных пород (особенно ив) в различных экосистемах, часто в городской черте. Не поражает живые деревья, начинает расти только там, где прекращается сокодвижение (на спиленных или повреждённых стволах). Может расти на любых элементах строений, сделанных из древесины тополя, на старых телефонных и электро столбах. Чешуйчатка разрушающая относится к несъедобным грибам. Данных о ядовитости нет.', '/media/mushrooms/placeholder.webp', NULL),
('a34046a7-84c0-5254-bdec-441bbe38cd8f', 'Подвишень', 'Подвишенник, Ивишень, Вишняк, Клитопилус обыкновенный', NULL, 'Энтоломовые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Белый, грязно-белый', 'Выпуклая', 'Белый, желтовато-серый', 'Пластинчатая', 'Различные разновидности Подвишенника встречаются с июля и до конца сентября повсеместно в лесах различного типа, в редколесье, среди травы, неизменно предпочитая кислые почвы. Гриб образует микоризу, как правило, с розовоцветными, но бывает найден и в ельниках без малейших следов яблонь и вишен. Гриб съедобный и согласно некоторым источникам считается высокоценным, однако сильный мучной запах не всем по вкусу, а сходство с ядовитыми говорушками и неизвестными в питательном смысле энтоломами заставляет поумерить гастрономические амбиции.', '/media/mushrooms/placeholder.webp', NULL),
('a409ce3a-75b4-5d55-9736-fa2a2ca1d282', 'Рядовка надломленная', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 20, 30, 'Ровная', 'Белый, мучной, желто-коричневатый', 'Выпуклая', 'Коричневато-красный, каштаново-красный, желтовато-каштановый', 'Пластинчатая', 'Рядовки надломленные произрастают преимущественно группами, на плодородных почвах, в сосновых лесах. Активное плодоношение гриба — с поздней осени и вплоть до середины зимы. Гриб съедобен, но перед употреблением в пищу его следует долго вымачивать. Рекомендован к употреблению только в солёном виде.', '/media/mushrooms/placeholder.webp', NULL),
('60cd636a-f546-5a44-a728-9f1241c8de9c', 'Строчок осенний', 'Лопастник осенний, Лопастник инфулоподобный, Гиромитра, Гельвелла инфула, Гельвелла инфулоподобная, Строчок рогатый', NULL, 'Дисциновые', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Беловатый, коричневато-сероватый', 'Выпуклая', 'Светло-коричневый, коричнево-чёрный', 'Гладкая', 'Строчок осенний единично встречается с июля, но активный рост начиает с конца августа. Часто встречается небольшими группами по 4-7 экземпляров в хвойных и лиственных лесах на почве, а также на остатках гниющей древесины. Строчок осенний любит расти или в хвойных, или в лиственных лесах, иногда поодиночке, иногда небольшими семейками и, предпочтительно, на гниющей древесине или поблизости от неё. Его можно обнаружить по всему умеренному поясу Европы и России. Основной период плодоношения у него приходится на конец июля и продолжается до конца сентября. Условно-cъедобный гриб, 4-й категории, используется в пищу после отварки (15-20 минут, вода сливается) или высушивания. В сыром виде смертельно ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('82201fd0-c6f7-57b4-bc16-7333e742465c', 'Гебелома клейкая', 'Валуй ложный', NULL, 'Гименогастровые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Беловатый, желтоватый', 'Ровная', 'Грязно-белый, ореховый, кирпично-красный, желтовато-коричневый', 'Пластинчатая', 'Встречается часто, группами, под дубом, осиной, березой, на опушках леса, у дорог, на полянах. Плодоносит с сентября по ноябрь. Широко распространена от Арктики до самой южной границы Кавказа и Средней Азии, часто встречается также в европейской части России и на Дальнем Востоке. Гебелома клейкая — несъедобный, а по некоторым источникам ядовитый гриб.', '/media/mushrooms/placeholder.webp', NULL),
('3880e3c8-48eb-5e62-a874-88b00349d8b5', 'Мицена чистая', NULL, NULL, 'Миценовые', true, 'Неизвестно', true, 5, 7, 'Ровная', 'Бледно-серо-коричневый', 'Выпуклая', 'Бледно-серо-коричневый, розоватый', 'Пластинчатая', 'Мицена чистая (Mycena pura) встречается на опаде мертвой древесины твердых пород, произрастает небольшими группами. Так же встречается на замшелых стволах в лиственном лесу. Иногда, в качестве исключения может селиться на древесине ели. Распространенный вид на территории Европы, Северной Америке и Юго-Западной Азии. Плодоносит с ранней весны и до начала лета. Иногда встречается и осенью. В пищу не употребляется из-за неприятного запаха, но в некоторых источниках, гриб относят к ядовитым. Содержит Мускарин. Считается слабо галлюциногенной.', '/media/mushrooms/placeholder.webp', NULL),
('d32af497-bbee-5bc6-8d69-07ed8b675e75', 'Моховик каштановый', 'Моховик коричневый, Моховик тёмно-коричневый', NULL, 'Болетовые', false, 'Неизвестно', true, 15, 30, 'Утолщенная в центре', 'Оливковый, желтоватый, розовый, коричневый', 'Выпуклая', 'Желтый, светло-коричневый, оливковый, коричневатый', 'Трубчатая', 'Встречается преимущественно в летний и осенний период. В сырую погоду приобретает беловатый плесневый налет, заражающий другие находящиеся рядом грибы. По съедобности относится к 3 категории.', '/media/mushrooms/placeholder.webp', NULL),
('5eb5d7c1-9763-59a1-b9d5-f0223f9f6ec1', 'Дождевик грушевидный', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Беловатый, грязно-бурый', 'Гладкая', 'Дождевик грушевидный встречается с начала июля (иногда и раньше) до конца сентября, плодоносит ровно, не проявляя какой-то особой цикличности. Растет группами, большими и плотными, на основательно перегнивших, замшелых древесных останках как лиственных, так и хвойных пород. Как и все прочие дождевики съедобен, пока его мякоть не начала темнеть. Впрочем, насчет целесообразности употребления дождевиков в пищу мнения бытуют самые разные.', '/media/mushrooms/placeholder.webp', NULL),
('01e83355-0c25-5998-83de-fcc0026047d7', 'Псилоцибе синеющая', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 5, 8, 'Ровная', 'Беловатый, синеватый', 'Ровная', 'Красноватый, коричневатый, желтоватый', 'Пластинчатая', 'Псилоцибе синеющая плодоносит в осенний период, преимущественно во влажных местностях, на почвах, богатых органикой, на лесных опушках, дорожным обочинам, на пастбищах и пустырях. Их отличительной особенностью является срастание ножками между собой. Такой вид грибов растёт на отмершей растительности. Гриб под названием синеющая Псилоцибе принадлежит к ядовитым, при употреблении в пищу вызывает сильные галлюцинации, нарушает правильную работу слуховых и зрительных органов.', '/media/mushrooms/placeholder.webp', NULL),
('b346e88f-dd52-5e5f-87b3-549761720080', 'Говорушка подогнутая', 'Клитоцибе подогнутая', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 30, 'Утолщенная в центре', 'Белый, буроватый', 'Вогнутая', 'Белый, беловатый, палевый, рыжеватый, грязно-жёлтый, коричневатый, жёлто-бурый', 'Пластинчатая', 'Растет с первой декады июля до конца октября. Массовое плодоношение с середины августа до конца сентября. При тёплой погоде и в южных регионах встречается и в ноябре-декабре, вплоть до заморозков и даже после первых заморозков и первого снега. Говорушка подогнутая считается условно-съедобным грибом с посредственными вкусовыми качествами (четвёртой категории). Рекомендуется предварительное отваривание, по разным источникам — от одного до двух-трёх раз, кипятить не менее 20 минут, отвар слить, не использовать.', '/media/mushrooms/placeholder.webp', NULL),
('57846fa5-48bb-5f5c-bc00-c36560c3f214', 'Сыроежка желтая', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Белый, сероватый', 'Ровная', 'Желтый, желто-оранжеватый, бледно-желтый', 'Пластинчатая', 'Обитание: с середины июля до конца сентября в сырых лиственных (с березой), в сосново-березовых лесах, по окраинам болот, во мху и черничниках, одиночно и небольшими группами, не редко, чаще встречается в северных регионах лесной зоны. Растет часто, но не обильно в сыроватых березовых, сосново-березовых лесах, по окраинам сфагновых болот с июля по октябрь. Гриб съедобен, отнесен к 3-й категории. Можно использовать его соленым.', '/media/mushrooms/placeholder.webp', NULL),
('2f85a8f2-a522-5ea0-8d98-5d4f4f56c4b5', 'Маслёнок лиственничный', NULL, NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Желтый, красновато-бурый', 'Выпуклая', 'Бледно-лимонно-жёлтый, ярко-жёлтый, оранжевый, оранжево-охристый, серовато-охристо-коричневый', 'Трубчатая', 'Маслёнок лиственничный растет под лиственницей, в сосновых лесах с примесью лиственницы, в лиственных лесах, особенно молодых посадках. Встречается редко и необильно, одиночно и группами. В последнее время сроки произрастания лиственничного масленка значительно расширились. Самая ранняя известная находка — 11 июня, также лиственничные маслята встречаются вплоть до конца октября. Съедобный гриб, второй категории. Употребляют свежим, маринованным и соленым', '/media/mushrooms/placeholder.webp', NULL),
('dc77093a-c923-5279-b374-710eb0335958', 'Груздь болотный', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Розовато-белый, грязно-белый, коричневатый', 'Вогнутая', 'Рыжеватый, красновато-коричневый, кирпичный, охряный', 'Пластинчатая', 'Встречается повсеместно, предпочитает увлажненные места, низины. Сезон – с июня по ноябрь, но самый пик роста приходится на август – сентябрь. Съедобный гриб. Используется в пищу.', '/media/mushrooms/placeholder.webp', NULL),
('e44611e6-d8f2-5b3b-8739-5dc395c17050', 'Лепиота ядовитая', 'Лепиота кирпично-красная', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 15, 20, 'С юбкой', 'Розоватый', 'Ровная', 'Серо-красный, бело-коричневатый', 'Пластинчатая', 'Встречается в июне — августе на Украине в окрестностях Одессы, а также в Западной Европе. Растет в парках, на лугах, среди травы. Вид редкий, сугубо осенний. Это очень ядовитый, даже смертельно ядовитый гриб. Его хилое плодовое тело, малый размер и неприглядный вид вряд ли могут привлечь внимание грибника.', '/media/mushrooms/placeholder.webp', NULL),
('2ceaf9b2-1fb4-5f17-8f12-51991082e3a2', 'Свинушка ольховая', 'Свинушка осиновая', NULL, 'Свинушковые', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Охряно-коричневый, грязно-желтый', 'Вогнутая', 'Красновато-коричневый, желтовато-коричневый, охряно-коричневый', 'Пластинчатая', 'Свинушка ольховая, ещё именуется свинушкой осиновой – довольно редкий вид, внешне похожий со свинушкой тонкой. Название своё получила из-за предпочтения расти под ольхой или осиной. В настоящее время свинушка ольховая на ряду со свинушкой тонкой отнесены к ядовитым грибам. Однако некоторые источники все же склоняются к тому, чтобы отнести ее к условно-съедобным грибам.', '/media/mushrooms/placeholder.webp', NULL),
('8ea2d3bd-ad74-5d7b-818c-060a5b58bdd5', 'Боровик жёлтый', 'Болет светло-жёлтый, Болет ярко-жёлтый, Болет жёлтый, Боровик Юнквилла', NULL, 'Болетовые', false, 'Неизвестно', true, 25, 60, 'Утолщенная внизу', 'Желто-коричневый', 'Выпуклая', 'Желто-коричневый, грязно-желтый', 'Трубчатая', 'Встречается боровик желтый преимущественно в буковых и дубовых лесах. Основной ареал этого вида – страны Западной Европы, в России этот вид встречается в Уссурийском районе на территории Супутинского заповедника. Собирают боровик желтый в осеннее-летний период – с июля по октябрь. Боровик желтый – съедобный гриб, который относится ко второй категории пищевой ценности. Употребляют его в пищу как в свежем, так в консервированном и сушеном виде.', '/media/mushrooms/placeholder.webp', NULL),
('41f73083-e35b-53e8-8709-aa46867be72b', 'Паутинник козий', 'Паутинник вонючий', NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 30, 'Утолщенная внизу', 'Фиолетово-сизый, серо-фиолетовый, сероватый', 'Выпуклая', 'Серовато-фиолетовый, фиолетово-сизый', 'Пластинчатая', 'Паутинник козий встречается с середины июля до начала октября в хвойных и смешанных лесах, как правило, с сосной; как и многие паутинники, растущие в подобных условиях, предпочитает влажные мшистые места. Гриб несъедобен по причине неаппетитного запаха, многократно усиливающегося при варке, по некоторым источникам даже ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('afcda99f-3056-59fc-9570-413e7e6f4259', 'Вешенка рожковидная', 'Вешенка обильная', NULL, 'Вёшенковые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Белый, коричневатый', 'Вогнутая', 'Белый, серо-охристый', 'Пластинчатая', 'Рожковидная вешенка произрастает с начала мая до середины сентября на останках деревьев лиственных пород; гриб не редок, но пристрастие к труднодоступным местам — бурелому, густому кустарнику, вырубкам, — делает его не таким приметным, как другие вешенки. Как и все вешенки, рожковидная съедобна и даже в каком-то смысле вкусна.', '/media/mushrooms/placeholder.webp', NULL),
('1f088784-efa7-51cf-970b-92b516f812a2', 'Рядовка серовато-сиреневая', 'Рядовка серо-голубая', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'Сероватый, лиловый, сиреневый, кремовый', 'Ровная', 'Сероватый, лиловый, сиреневый, кремовый', 'Пластинчатая', 'Растет осенью в лесах всех видов с богатой почвой, и/или с толстой листовой или хвойной подстилкой; на кучах листового перегноя и в местах, куда свозится листва; на богатых почвах в пойменных перелесках рек и ручьев, низинах, оврагах, нередко среди крапивы и кустарника. Подстилка при этом активно прорастает мицелием. Любит расти вдоль дорог, тропинок, где есть значительное количество листовой/хвойной подстилки. Растет рядами, кольцами, от нескольких и до десятков плодовых тел в кольце или ряде. Условно-съедобный гриб. Вкусный. Полностью аналогичен фиолетовой рядовке. Термическая обработка необходима, так как гриб содержит гемолизин, разрушающий красные кровяные тельца (как и фиолетовая рядовка), который полностью разрушается при термической обработке.', '/media/mushrooms/placeholder.webp', NULL),
('40d531de-820e-50c7-8973-c9ad9f651170', 'Подберезовик белый', 'Березовик болотный, Березовик белый, Болотник', NULL, 'Болетовые', false, 'Неизвестно', true, 8, 15, 'Ровная', 'Белый', 'Выпуклая', 'Кремовый, светло-серый, розоватый', 'Трубчатая', 'Подберезовик белый встречается с середины июля до начала октября в лиственных и смешанных лесах (образуя микоризу главным образом с березой), предпочитает сырые места, охотно растет по краям болот. Попадается не очень редко, но особой урожайностью не отличается. Гриб съедобен, но его вкусовые качества остаются под вопросом.', '/media/mushrooms/placeholder.webp', NULL),
('12c5b3b2-f0d5-5ea4-898a-07c4ef774b76', 'Мацутакэ', 'Рядовка обутая, Рядовка пятнистая', NULL, 'Рядовковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Орехово-коричневый, грязно-белый', 'Выпуклая', 'Коричневый', 'Пластинчатая', 'Произрастает около подножья деревьев, часто прячется под опавшими листьями. Характерной особенностью гриба мацутакэ является его симбиоз с корнями мощных деревьев, произрастающих на определённых территориях. Плодоношение мацутакэ начинается в сентябре, и продолжается до октября. На Территории Российской Федерации этот вид гриба распространён в Южном Урале, Приуралье, на Дальнем Востоке и Приморье, Восточной и Южной Сибири. Гриб Мацутакэ съедобен, причём употреблять его можно в любом виде, как в сыром, так и в отварном, тушёном или жареном. Гриб характеризуется высокими вкусовыми качествами, иногда его маринуют или засаливают, но чаще – едят свежим.', '/media/mushrooms/placeholder.webp', NULL),
('b943472c-9760-5d4e-8024-f77414914821', 'Навозник дятловый', 'Навозник сорочий, Навозник пёстрый', NULL, 'Псатирелловые', false, 'Неизвестно', true, 6, 15, 'Ровная', 'Белый', 'Выпуклая', 'Светло-бурый, охристый, черно-коричневый', 'Пластинчатая', 'Навозник дятловый предпочитает лиственные леса, где выбирает богатые гумусом известковые почвы, иногда встречается на гнилой древесине. Растет одиночно или небольшими группами, чаще в гористой или холмистой местности. Плодоносит с позднего лета, но пик плодоношения осенью. Навозник дятловый чаще упоминается как слабо ядовитый, вызывающий гастритные явления, иногда как галлюциногенный. Иногда некоторые авторы говорят о съедобности.', '/media/mushrooms/placeholder.webp', NULL),
('5d1e3aa9-79e6-52a5-97a1-ed6e48cb77f2', 'Боровик волчий', 'Ложный сатанинский гриб', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 60, 'Утолщенная внизу', 'Желтоватый, ярко-желтый, красный, красно-коричневый', 'Выпуклая', 'Розовый, красный, сероватый, молочно-кофейный, темно-розовый, красно-розовый, коричневый, красноватый, красно-рыжий', 'Трубчатая', 'Боровик волчий достаточно распространенный среди болетов вид, который растет в дубовых лесах. Встречается с ноября по январь разбросанными на почве группами. Он относится к разряду условно съедобных грибов. В пищу его можно употреблять после отваривания в течение 10-15 минут. При этом отвар нужно обязательно выливать.', '/media/mushrooms/placeholder.webp', NULL),
('a555b1d1-a5bc-56a5-a9f2-cc0aa36b1bfb', 'Трутовик берёзовый', 'Березовая губка', NULL, 'Фомитопсисовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Желтоватый, сероватый', 'Гладкая', 'Трутовик березовый является дереворазрушающим грибом. Чаще всего произрастает одиночно или небольшими группами на мертвой преющей березовой древесине, а также на больных и погибающих живых березовых деревьях. Трутовик березовый является не пригодным к употреблению грибом из-за горькой и жесткой мякоти. Есть сведения, что его мякоть может употребляться в молодом виде до приобретения жесткости.', '/media/mushrooms/placeholder.webp', NULL),
('09a33259-c948-5251-a25d-6e06203a0af7', 'Боровик пороспоровый', 'Моховик пороспоровый', NULL, 'Болетовые', false, 'Неизвестно', true, 15, 30, 'Утолщенная в центре', 'Серо-коричневый, желтоватый', 'Выпуклая', 'Темно-коричневый, серо-коричневый', 'Трубчатая', 'Боровик пороспоровый произрастает в основном в хвойных лесах и в лесах смешанного типа. Чаще всего его можно найти среди травы и на мху. Сезон произрастания боровика пороспорового приходится на лето-осень, в основном — с июня по сентябрь. Боровик пороспоровый относится к съедобным грибам.', '/media/mushrooms/placeholder.webp', NULL),
('4d079bff-7727-5361-8173-5fda133cc4e7', 'Зонтик девичий', NULL, NULL, 'Шампиньоновые', true, 'Неизвестно', true, 6, 10, 'С юбкой', 'Беловатый, грязно-коричневатый', 'Выпуклая', 'Беловатый, буроватый, светло-коричневатый', 'Пластинчатая', 'Зонтик девичий растёт на почве в сосновых и смешанных лесах, на лугах, появляется одиночно или группами, встречается редко. Сезон: август — октябрь. Съедобен, но поскольку редок и подлежит охране, собирать его не рекомендуется.', '/media/mushrooms/placeholder.webp', NULL),
('56ea4216-17c0-579d-be79-d58eb8632098', 'Млечник серо-розовый', 'Груздь серо-розовый, Груздь несъедобный, Млечник обыкновенный, Млечник чалый', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Серо-розоватый', 'Вогнутая', 'Тускло-сероватый, коричневато-розовый', 'Пластинчатая', 'Млечник серо-розовый встречается на болотах среди берез и сосен, во мхах, с начала августа до середины октября; в конце августа-начале сентября может, при благоприятствующих обстоятельствах, плодоносить в огромных количествах. В зарубежной литературе проходит по списку слабо ядовитых; у нас упоминается как несъедобный или как съедобный, но малоценный.', '/media/mushrooms/placeholder.webp', NULL),
('f55c396e-ca78-581d-aa01-bc2a0673f041', 'Трутовик настоящий', 'Кровяная губка', NULL, 'Полипоровые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Серый, светло-бежевый', 'Гладкая', 'Трутовик настоящий принадлежит к категории сапрофитов. Именно этот гриб является основной причиной появления белой гнили на стволах деревьев лиственных пород. Его негативному воздействию нередко подвергаются насаждения берёз, дубов, ольхи, осины, буков. Гриб несъедобен.', '/media/mushrooms/placeholder.webp', NULL),
('0c5c52cd-6c0a-5c15-8d53-1edf60d89f26', 'Энтолома ядовитая', 'Розовопластинник гигантский, Розовопластинник желтовато-сизый', NULL, 'Энтоломовые', false, 'Неизвестно', true, 20, 30, 'Ровная', 'Белый', 'Выпуклая', 'Белый, буроватый', 'Пластинчатая', 'Растёт в лиственных лесах, садах, скверах, парках, огородах одиночно или группами с июня по сентябрь. Встречается в Карелии, Мурманской области, на Украине. В средней полосе этот гриб пока не обнаружен. Гриб ядовит. При употреблении в пищу вызывает сильное расстройство кишечника.', '/media/mushrooms/placeholder.webp', NULL),
('1f39c8c8-5d38-53f8-a77f-73857f481914', 'Шампиньон августовский', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 15, 25, 'С юбкой', 'Белый, желтоватый', 'Выпуклая', 'Темно-коричневый, темно-оранжевый', 'Пластинчатая', 'Эти грибы начинают появляться с середины августа и растут до начала октября. Шампиньон августовский растет преимущественно в хвойных и смешанных лесах, часто около муравейников или непосредственно на них. Съедобный гриб, третьей категории.', '/media/mushrooms/placeholder.webp', NULL),
('6f466e70-b432-5c14-8d3d-843fd083d7e1', 'Рядовка вонючая', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 3, 18, 'Утолщенная внизу', 'Белый, кремовый, бледно-желтоватый', 'Ровная', 'Беловатый, кремовый, медовый, розовато-тёмно-бежевый, бледно-охряный', 'Пластинчатая', 'Рядовка вонючая образует микоризу с елью (род Picea) и пихтой (род Abies). Обычно она приурочена к влажным лесам с развитым толстым моховым покровом на почве, но её можно также встретить в хвойниках-черничниках. Она предпочитает почвы от слабокислых до известковых. Гриб несъедобен из-за отвратительного запаха и горького вкуса. Рядовка вонючая в некоторых источниках относится к разряду галлюциногенных грибов, при употреблении ее в пищу может вызывать зрительные и слуховые галлюцинации.', '/media/mushrooms/placeholder.webp', NULL),
('ee765dff-0f36-5d5b-96c3-92820eea0c0a', 'Белошампиньон длиннокорневой', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 15, 25, 'С юбкой', 'Белый, коричневатый', 'Выпуклая', 'Серовато-коричневый, беловатый', 'Пластинчатая', 'Плодоносит с июня по октябрь. Встречается в странах Евразии, Австралии и Северной Америки. В России распространен в окрестностях Ростова-на-Дону, а в других регионах страны неизвестен. Произростает в Великобритании, Франции, Украине, Италии, в Армении. Это довольно редкий гриб, чаще встречается в садах, парках, на обочинах дорог, а также на пашнях, полях и в зарослях рудералов. Может произрастать как одиночно, так и небольшими группами. Хороший сьедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('af6ac666-f584-5351-9e9d-5d4b2fe1f058', 'Боровик двухцветный', 'Болет двухцветный', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 50, 'Утолщенная внизу', 'Розово-красный, желтоватый', 'Выпуклая', 'Ярко-красный, кроваво-красный, кирпичный, коричневатый', 'Трубчатая', 'Этот гриб можно встретить в лесах хвойного и лиственного типа. Этот тип грибов считается съедобным.', '/media/mushrooms/placeholder.webp', NULL),
('31a7b29f-26a6-5424-a744-b167bb3ca0d6', 'Лепиота гребенчатая', 'Зонтик гребенчатый', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 3, 8, 'С юбкой', 'Желтоватый, розоватый, беловатый', 'Выпуклая', 'Рыже-бурый, белый', 'Пластинчатая', 'Растёт в хвойных, смешанных и широколиственных лесах, на лугах, пастбищах, огородах. Плодоносит с июля по октябрь. Встречается и в Северной Америке. Растет он с июня по сентябрь октябрь на лугах, лесных опушках и лужайках, пастбищах. Обладает острым, редечным запахом и неприятным вкусом. Гриб несъедобен, возможно, ядовит. Встречается по всей России и относится к подозрительным грибам. В западноевропейских определителях его иногда отмечают как ядовитый.', '/media/mushrooms/placeholder.webp', NULL),
('8bd9121b-4ab0-50a0-8745-80aa7ea47fca', 'Навозник мерцающий', 'Навозник крошащийся', NULL, 'Псатирелловые', false, 'Неизвестно', true, 20, 80, 'Ровная', 'Белая', 'Выпуклая', 'Медово-коричневый, желтовато-коричневый, янтарный', 'Гладкая', 'Очень часто в городах, садах, парках, во дворах и на обочинах дорог, но также встречается в лесу. Навозник мерцающий, как и все подобные навозники, вполне съедобен в молодом возрасте, пока пластины не почернели. В пищу употребляют только шляпки.', '/media/mushrooms/placeholder.webp', NULL),
('31926025-4228-5009-b62a-266bbc846be4', 'Ризопогон обыкновенный', 'Трюфель обыкновенный', NULL, 'Ризопогоновые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Серовато-коричневый, оливково-бурый', 'Гладкая', 'Распространён в еловых, сосново-дубовых и сосновых лесах. Ризопогон обыкновенный принадлежит к числу малоизученных грибов, но считается съедобным.', '/media/mushrooms/placeholder.webp', NULL),
('d62f11a9-d181-5fc9-86e0-9f45e427b51d', 'Паутинник превосходный', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 20, 50, 'Утолщенная внизу', 'Бледно-фиолетовым', 'Выпуклая', 'Красно-коричневая', 'Гладкая', 'Распространён в неморальных областях Европы, однако встречается там редко. Некоторые страны Европы даже внесли этот вид грибов в Красную книгу, как редкий и исчезающий.', '/media/mushrooms/placeholder.webp', NULL),
('03698101-3253-5692-9f60-c35fccf86791', 'Траметес разноцветный', 'Кориолус разноцветный', NULL, 'Полипоровые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Разноцветные области белого, синего, серого, бархатистого, чёрного, серебристого цветов', 'Гладкая', 'Несъедобен. Гриб этого вида предпочитает селиться на поленнице, старой древесине, трухлявых пнях, оставшихся от лиственных деревьев', '/media/mushrooms/placeholder.webp', NULL),
('1baa92d7-e64b-503c-808b-c4f74e538544', 'Волоконница патуйяра', 'Волоконница краснеющая', NULL, 'Волоконницевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Беловатая, затем красноватая, соломенно-желтая.', 'Выпуклая', 'Беловатая, затем красноватая, соломенно-желтая.', 'Пластинчатая', 'Гриб Волоконница патуйяра смертельно ядовит. Появляется с мая по октябрь, особенно обильно — в августе и сентябре.', '/media/mushrooms/placeholder.webp', NULL),
('21a8753f-6e06-5c6f-b0a7-e2d626f9f554', 'Аурикулярия уховидная', 'Иудино ухо', NULL, 'Аурикуляриевые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Вогнутая', 'Серо-коричневая, рыжевато-коричневатая', 'Гладкая', 'Аурикулярия уховидная растет с лета до поздней осени, с июля до ноября, на мертвой древесине, у основания стволов и на ветках лиственных деревьев и кустарников.', '/media/mushrooms/placeholder.webp', NULL),
('169c6749-e424-562a-990d-9db513f02ae1', 'Шапочка сморчковая', 'Сморчок нежный', NULL, 'Сморчковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Белый, кремовый.', 'Выпуклая', 'Коричневый', 'Гладкая', 'Считается самым узким видом сморчковых грибов. Плодоносит с начала до середины мая четко направленным слоем. Чаще всего встречается среди молодых лип и осин. Употреблять в пищу сморчковую шапочку можно только после предварительного отваривания в течение десяти минут.', '/media/mushrooms/placeholder.webp', NULL),
('b64901c7-94de-542d-9aa3-46339d620fed', 'Мухомор Виттадини', NULL, NULL, 'Аманитовые', false, 'Неизвестно', true, 20, 50, 'Утолщенная вверху', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Встречается в некоторых южных и юго-восточных степных районах России. Мухомор Виттадини растет с апреля по октябрь на различных почвах. Весна — осень. Молодые грибы съедобны, вкус и запах их приятен, но в связи с опасностью перепутать со смертельно ядовитыми видами лучше воздержаться от употребления их в пищу.', '/media/mushrooms/placeholder.webp', NULL),
('3b8f451e-8a4c-56b7-9ce6-ec270dc95cb2', 'Огнёвка ольховая', 'Чешуйчатка ольховая', NULL, 'Строфариевые', false, 'Неизвестно', true, 10, 10, 'Ровная', 'Желтый', 'Выпуклая', 'Желтый', 'Пластинчатая', 'Чешуйчатка ольховая считается несъедобным грибом из-за горького вкуса. Горечь не уходит после отваривания или высушивания. Чешуйчатка ольховая плодоносит с конца лета и всю осень, в теплых регионах возможно плодоношение весной.', '/media/mushrooms/placeholder.webp', NULL),
('665b7782-d5c5-56d4-bc24-ba9469f0551e', 'Говорушка беловатая', 'Говорушка выбеленная', NULL, 'Трихоломовые', false, 'Неизвестно', true, 4, 6, 'Утолщенная вверху', 'Беловатый, сероватый', 'Вогнутая', 'Мучнисто-белоый, беловато-сероватый', 'Пластинчатая', 'Смертельно-ядовитый гриб! Плодовые тела появляются группами, иногда очень большими; образуют «ведьмины круги». Распространён в умеренной зоне Северного полушария.Сезон с середины июля по ноябрь.', '/media/mushrooms/placeholder.webp', NULL),
('e4034a4a-ee6e-5047-882b-920b639dcf0d', 'Сыроежка съедобная', 'Сыроежка пищевая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 30, 'Ровная', 'Белый', 'Выпуклая', 'Коричневый', 'Пластинчатая', 'Этот гриб произрастает в лиственных и хвойных лесах в основном в летне-осенний период. Сыроежка пищевая очень широко используется в пищу благодаря своему отличному вкусу и аромату. Она полностью безопасна для здоровья.', '/media/mushrooms/placeholder.webp', NULL),
('cc3d7d6b-51cd-52f0-b641-d34d35284d0e', 'Мутинус собачий', NULL, NULL, 'Весёлковые', false, 'Неизвестно', true, 10, 10, 'Ровная', 'Желтоватый', 'Выпуклая', 'Зелёный', 'Гладкая', 'Несъедобный гриб, хотя некоторые утверждают, что когда гриб ещё в яйцевой оболочке, он съедобен.Растет мутинус собачий с последней декады июня по октябрь в лиственных лесах на богатой гумусом почве.', '/media/mushrooms/placeholder.webp', NULL),
('4b756e75-ed5d-5dd2-828e-e51b88a974f7', 'Поплавок шафрановый', 'Поплавок шафранный', NULL, 'Аманитовые', false, 'Неизвестно', true, 10, 15, 'Утолщенная внизу', 'Белый', 'Выпуклая', 'Желто-шафрановый', 'Пластинчатая', 'Малоценный съедобный гриб. Поплавок шафрановый встречается с начала июля до конца сентября в лиственных и смешанных лесах, предпочитая светлые места, опушки, редколесья.', '/media/mushrooms/placeholder.webp', NULL),
('294423ea-d272-5d66-9130-827e88453a8b', 'Белонавозник Бирнбаума', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 5, 6, 'С юбкой', 'Желтоваятая', 'Выпуклая', 'Желтоватая', 'Пластинчатая', 'Несъедобный декоративный гриб. Произрастает на компосте, в оранжереях, теплицах, парниках в течении всего года.', '/media/mushrooms/placeholder.webp', NULL),
('5045ae2b-df89-507d-b80f-fcca1a15fbc8', 'Говорушка булавоногая', 'Говорушка булавовидноногая', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 5, 35, 'Утолщенная внизу', 'Белый, буровато-серый', 'Выпуклая', 'Белый, серый, коричневый', 'Пластинчатая', 'Считается съедобным грибом весьма низкого качества. Говорушка булавоногая встечается с середины июля до середины октября в лесах различного типа, предпочитая, очевидно, из хвойных деревьев сосну, а из лиственных — березу; в период наиболее активного плодоношения (конец августа — начало сентября) произрастает очень обильно, большими группами.', '/media/mushrooms/placeholder.webp', NULL),
('ddc92293-0da8-53d5-9a7f-afbf50db996c', 'Омфалотус масличный', 'Омфалот маслиновый', NULL, 'Омфалотовые', false, 'Неизвестно', true, 5, 10, 'Утолщенная вверху', 'Желто-оранжевый, красновато-коричнеывый', 'Выпуклая', 'Желто-оранжевый, красновато-коричнеывый', 'Пластинчатая', 'Гриб ядовит, но не смертельно. Его употребление приводит к тяжелым желудочно-кишечным расстройствам. Омфалотус Масличный растет колониями на пнях олив и других лиственных пород деревьев. Встречается на невысоких горах и равнинах. Плодоносит с лета и до поздней осени.', '/media/mushrooms/placeholder.webp', NULL),
('55c5590d-fe91-5f5d-b265-154fa3c48448', 'Головач мешковатый', 'Головач пузыревидный', NULL, 'Шампиньоновые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Белый', 'Гладкая', 'Хороший съедобный гриб 4-й категории, как и большинство Дождевиков. Почвенный гумусовый сапротроф. Растёт на почве всех типов лесов, на выгонах, пашнях, в садах, на суходольных, горных и предгорных лугах, на низкорослых лугах среди культивируемых земель и на склонах холмов в низкой траве, на опушках и полянах, предпочитает открытые песчаные пастбища-пустоши с удобренной почвой.', '/media/mushrooms/placeholder.webp', NULL),
('a85c132b-8ae8-5902-9944-848596376f0f', 'Трутовик овечий', 'Альбатреллус овечий', NULL, 'Альбатрелловые', true, 'Неизвестно', true, 10, 30, 'Утолщенная вверху', 'Белый', 'Выпуклая', 'Белый', 'Трубчатая', 'Вид занесен в Красную книгу Московской области (3 категория, редкий вид). Трутовик овечий встречается нечасто с июля по октябрь на почве под елями в сухих хвойных и смешанных лесах на полянах, просеках, опушках, у дорог, а также в горах. Предпочитает нейтральные и щелочные почвы, часто растет во мху.', '/media/mushrooms/placeholder.webp', NULL),
('58bab4f1-1a92-5090-93e6-8b829bba0ea4', 'Феолепиота золотистая', 'Зонтик золотистый', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 5, 10, 'С юбкой', 'Золотисто-желтый, охряный цвет', 'Выпуклая', 'Золотисто-желтый, охряный цвет', 'Пластинчатая', 'Раньше феолепиота золотистая считалась условно-съедобным грибом, который употребляется в пищу после 20 минутного отваривания. Однако, сейчас информация противоречивая, по некоторым данным гриб накапливает цианиды, и может привести к отравлению. Поэтому, последнее время, его причисляют к несъедобным грибам. Феолепиота золотистая растет со второй половины июля, и до конца октября, группами, в том числе и большими.', '/media/mushrooms/placeholder.webp', NULL),
('dfe5fe50-88f7-50bd-957b-b65f7ab09283', 'Волоконница острая', NULL, NULL, 'Волоконницевые', false, 'Неизвестно', true, 2, 5, 'Ровная', 'Умброво-коричневый', 'Выпуклая', 'Умброво-коричневый', 'Пластинчатая', 'В грибе много элемента алкалоида мускарина. Может вызывать галлюциногенное состояние, похожее на опьянение. Гриб несъедобный. Встречается нечасто. Можно найти в Европе, также иногда в Восточной Сибири. Растет в хвойных лесах и болотах в субарктическом поясе, иногда прорастает среди сфагновых мхов.', '/media/mushrooms/placeholder.webp', NULL),
('e616954d-cfee-5493-ae9d-e274aeb8d765', 'Мухомор яйцевидный', NULL, NULL, 'Аманитовые', true, 'Неизвестно', true, 30, 50, 'Утолщенная внизу', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'В России данный гриб занесен в Красную книгу Краснодарского края. Несмотря на то, что гриб является съедобным, рекомендуется собирать его только опытным профессиональным грибникам. Это связано с высокой вероятностью того, что вместо мухомора яйцевидного будет срезана ядовитая поганка.', '/media/mushrooms/placeholder.webp', NULL),
('f2717c97-5baa-5b64-9913-2ce16412caac', 'Моховик красный', 'Моховик краснеющий', NULL, 'Болетовые', false, 'Неизвестно', true, 5, 10, 'Утолщенная внизу', 'Ярко-желтый', 'Выпуклая', 'Розовато-пурпурный', 'Трубчатая', 'Съедобный гриб, четвертой категории, собирают в августе-сентябре. Годится для употребления в вареном, маринованном и сушёном виде.', '/media/mushrooms/placeholder.webp', NULL),
('66542d22-b9f4-561f-a4dc-6ec5a0fa21b8', 'Поплавок серый', 'Мухомор влагалищный', NULL, 'Аманитовые', true, 'Неизвестно', true, 5, 20, 'Ровная', 'Серый', 'Выпуклая', 'Серый', 'Пластинчатая', 'В некоторых регионах (Астраханская область) внесён в Красную Книгу. Поплавок Серый считается съедобным грибом с низкими вкусовыми качествами (видимо, из-за совершенно безвкусной мякоти). Имеет смысл собирать только молодые экземпляры с нераскрывшейся шляпкой: есть шанс донести до дома непереломанные грибы. Плодоносит Серый Поплавок всё тёплое время года: поздняя весна, лето и осень. Распространён повсеместно.', '/media/mushrooms/placeholder.webp', NULL),
('f38f8211-8877-52e8-9192-df9ada25e169', 'Лопастник курчавый', 'Гельвелла курчавая', NULL, 'Гельвелловые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Белый', 'Вогнутая', 'Белый', 'Гладкая', 'Лопастник курчавый — относится к условно-съедобным грибам. Лопастник курчавый — это довольно редкий гриб. А основными местами его произрастания можно считать лиственные и хвойные леса Европы и европейской части России, в которых он встречается небольшими группами, часто вдоль лесных дорог и, в отличие от лопастника обыкновенного (гельвеллы обыкновенной) он растёт не в весенний, а в осенний период — с начала августа и по конец октября.', '/media/mushrooms/placeholder.webp', NULL),
('dedf4dc0-00dd-50e6-921d-10ee2baec296', 'Мухомор поганковидный', 'Мухомор лимонный', NULL, 'Аманитовые', false, 'Неизвестно', true, 5, 23, 'С юбкой', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Ряд источников причисляет Поганковидный мухомор к смертельно ядовитым грибам, но это, с большой вероятностью, перестраховка: слишком велик риск спутать его с Бледной Поганкой. Растет поодиночке, небольшими группами, реже небольшими полянками. Плодоносит летом и осенью. Широко распространен в Европе и Азии, и — пока еще под старым названием — в Северной Америке.', '/media/mushrooms/placeholder.webp', NULL),
('29f4f4a3-b8ec-5865-96a3-91704961d751', 'Саркосома шаровидная', NULL, NULL, 'Саркосомовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Темно-коричневый', 'Гладкая', 'Редкий гриб, занесен в Красную книгу некоторых областей России. Относится к несъедобным грибам, хотя в ряде регионов нашей страны употребляется в пищу (в жареном виде). Его масло давно используется в народной медицине. Из него делают отвары, мази, пьют в сыром виде — кто для омоложения, кто для роста волос, а кто просто применяет как косметическое средство. Сезон – ранняя весна, конец апреля – конец мая, после того, как стает снег.', '/media/mushrooms/placeholder.webp', NULL),
('32bdfbf0-b3c0-5e76-876e-e325639a8520', 'Ксилярия многообразная', 'Пальцы мертвеца', NULL, 'Ксиляриевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Черный', 'Выпуклая', 'Черный', 'Гладкая', 'Несъедобен. Данных о ядовитости нет. Этот странный гриб, часто называемый «Пальцы мертвеца», можно встретить с весны до поздней осени, так как развивается он весьма неторопливо. Молодой — бледный, голубоватый, часто с беловатым кончиком. Его бледное внешнее покрытие — это «бесполые» споры, конидии, появляющиеся на ранней стадии развития. К лету, однако, гриб начинает чернеть, и к концу лета или осени он полностью черный и высохший.', '/media/mushrooms/placeholder.webp', NULL),
('7bf8cc52-e803-5665-b27e-c22a00f3039e', 'Шампиньон перелесковый', 'Шампиньон тонкий', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 5, 20, 'Ровная', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Шампиньон перелесковый — Это хороший съедобный гриб, не уступающий лучшим из шампиньонов. Шампиньон перелесковый произрастает одиночно и группами в лиственных и хвойных лесах с июня по конец сентября.', '/media/mushrooms/placeholder.webp', NULL),
('92b06452-a5f9-50cd-94c3-c1e3b03e0d2c', 'Гигрофор Персона', NULL, NULL, 'Гигрофоровые', false, 'Неизвестно', true, 6, 17, 'Ровная', 'Оливково-бурый', 'Выпуклая', 'Оливково-бурый', 'Пластинчатая', 'Гриб съедобен. Растет в широколиственных лесах, образует микоризу с дубом, встречается также в буковых и грабовых лесах. Растет небольшими группами. Сезон: август-ноябрь. Вид редкий, встречается в Европе, Азии, на Северном Кавказе, в России — в Пензенской, Свердловский областях, на Дальнем Востоке и в Приморском крае, ареал распространения скорее всего значительно шире, нет точных данных.', '/media/mushrooms/placeholder.webp', NULL),
('8418b7fe-e3fc-5336-bea0-d8d99f33ac18', 'Моховик бархатный', 'Моховик восковатый', NULL, 'Болетовые', false, 'Неизвестно', true, 5, 20, 'Утолщенная внизу', 'Желтый, Красновато-желтый', 'Выпуклая', 'Коричневый, красно-коричневый', 'Лабиринтовидная', 'Гриб моховик бархатный (Xerocomellus pruinatus) съедобен, может употребляться в любом виде (свежем, жареном, отварном, засоленном или высушенным). Бархатный моховик произрастает на территории лиственных лесов, преимущественно под дубами и буками, а кроме того – в хвойных лесах с елями и соснами, а также – лесистых местностях смешанного типа. Активное плодоношение начинается в конце лета и продолжается в течение первой половины осени. Произрастает преимущественно группами.', '/media/mushrooms/placeholder.webp', NULL),
('88735d95-e6fa-50f3-95ce-8ac4b90be6fc', 'Болет пурпурный', 'Боровик пурпурный', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 70, 'Утолщенная внизу', 'Лимонно-желтый', 'Выпуклая', 'Красноватый, винный, розовый', 'Лабиринтовидная', 'В сыром или недоваренном виде ядовит. В западной литературе позиционируется как несъедобный или ядовитый. Ввиду редкости лучше не собирать. Гриб встречается довольно редко. Распространен в России, в Украине, в странах Европы, в основном в местах с теплым климатом. Предпочитает известковые почвы, чаще обитает в холмистых и горных районах. Встречается в широколиственных и смешанных лесах рядом с буками и дубами. Плодоносит в июне-сентябре.', '/media/mushrooms/placeholder.webp', NULL),
('70ec866a-b653-56ef-bd6d-bb7be4f7b106', 'Боровик ле Галь', 'Боровик законный', NULL, 'Болетовые', false, 'Неизвестно', true, 25, 50, 'Утолщенная внизу', 'Розовато-оранжевый', 'Выпуклая', 'Розовато-оранжевый', 'Лабиринтовидная', 'Этот гриб является ядовитым и не допускается использование этого гриба в пищевых целях. Боровик ле Галь широко распространен в Европе и встречается преимущественно в лиственных лесах, где является микоризообразоватлем с дубом, буком, грабом. Предпочитает расти на щелочных почвах. Встречается летом и ранней осенью.', '/media/mushrooms/placeholder.webp', NULL),
('78ad3a6e-4552-5a0f-a4a8-f393ae0e0eab', 'Навозная лысина', NULL, NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Светло — желтоватый.', 'Выпуклая', 'Бледно-охряный, желтовато- коричневый', 'Пластинчатая', 'Местонахождение: на сгнившем лошадином навозе и хорошо удобренных почвах, в траве, в саду и полях.', '/media/mushrooms/placeholder.webp', NULL),
('66cac364-3196-55cc-b450-8b8f0e11d570', 'Рамария красивая', 'Рогатик красивый', NULL, 'Гомфовые', false, 'Неизвестно', true, 5, 200, 'Ровная', 'Белый, розовый, желтый', 'Ровная', 'Белый, розовый, желтый', 'Трубчатая', 'Этот гриб ядовит, при приеме внутрь нарушает работу желудочно-кишечного тракта. Рамария красивая обычно встречается в лиственных лесах. Старые грибы по внешнему виду сходны с другими желтоватыми или бурыми рогатиками.', '/media/mushrooms/placeholder.webp', NULL),
('82f44cdb-26b1-568d-837a-ddb2e83dd5ac', 'Подосиновик белый', 'Осиновик белый', NULL, 'Болетовые', false, 'Неизвестно', true, 5, 20, 'Утолщенная внизу', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Подосиновик белый (Leccinum percandidum) — cъедобный гриб второй категории. Собирают с середины августа и до конца сентября. Употребляют в пищу так же, как подосиновик красный. Молодые грибы лучше мариновать, а крупные зрелые — жарить или сушить.', '/media/mushrooms/placeholder.webp', NULL),
('280dcff5-78ee-5c5e-97b8-ef85c3980bc9', 'Белошампиньон краснопластинчатый', 'Зонтик румянящийся', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 5, 10, 'С юбкой', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Благодаря большому распространению, многие с удовольствием потребляют в пищу данный гриб, тем более у него оригинальный фруктовый запах, он многим очень приятен. Найти его можно практически в течение всего сезона, начиная с середины лета и до середины осени. Он встречается во многих местах, на пастбищах, в садах, у дорог, потому что основное место обитания это трава.', '/media/mushrooms/placeholder.webp', NULL),
('944bcb94-9963-5c79-98fe-11873eb93a91', 'Сморчок конический', NULL, NULL, 'Сморчковые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Белый, желтый', 'Выпуклая', 'Рыжевато-бурый, черный', 'Трубчатая', 'Сморчок конический – съедобный гриб с нежной вкусной мякотью. При этом считается условно-съедобным и требует предварительного приваривания в течение 15 минут. стречается на хорошо прогретых почвах, пожарищах и вырубках лесов. Часто гриб можно встретить и в осинниках. Сморчок конический, как и все сморчки плодоносит весной, искать его нужно начиная с апреля и до середины мая. Сморчки предпочитают места, где есть падалица, поэтому любители данного вида, иногда разводят их дома в саду вокруг старых яблонь.', '/media/mushrooms/placeholder.webp', NULL),
('173b91d8-44b1-5ba3-8586-81dfc32863c5', 'Млечник Мэра', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 6, 15, 'Ровная', 'Розово-кремовый, кремово-жёлтый, кремовый', 'Выпуклая', 'Светло-кремовый, глинисто-кремовый', 'Пластинчатая', 'Млечник Мэра принадлежит к числу съедобных грибов, пригоден для употребления в пищу в любом виде. Млечник Мэра встречается преимущественно в широколиственных лесах, произрастает группами небольшой величины. Гриб этого вида широко распространён на территории Европы, Юго-Западной части Азии и в Марокко. Активное плодоношение гриба приходится на период с сентября по октябрь.', '/media/mushrooms/placeholder.webp', NULL),
('273fcb56-ff34-510d-915f-3f6a39526e74', 'Коллибия лесолюбивая', 'Коллибия дуболюбивая', NULL, 'Омфалотовые', false, 'Неизвестно', true, 5, 10, 'Утолщенная внизу', 'Коричневый, светло-рыжый', 'Выпуклая', 'Восково-беловатый', 'Пластинчатая', 'Различные источники сходятся на том, что гриб Коллибия лесолюбивая, в общем-то, съедобен, но есть его смысла нет: мяса мало, вкус отсутствует. Впрочем, попробовать никто не запрещает. Распространение: Коллибия лесолюбивая растет с середины мая до поздней осени в лесах различного типа — как на подстилке, так и на гниющих остатках деревьев. В июне-июле встречается в больших количествах.', '/media/mushrooms/placeholder.webp', NULL),
('84d0475c-d106-550f-a225-20f7d617536f', 'Паутинник светло-охристый', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 5, 25, 'Ровная', 'Светло-охристый', 'Выпуклая', 'Светло-охристый, коричневатый', 'Пластинчатая', 'Паутинник в официальных источниках называют несъедобным, слабо-ядовитым грибом. Однако бывалые грибники, которые пробовали его на вкус, рассказывают, что светло-охристый паутинник очень вкусный и упругий. Его перед употреблением нужно отварить, а потом – поджарить. Но рекомендовать этот вид для употребления в пищу всё-таки нельзя. Паутинник светло-охристый (Cortinarius claricolor) произрастает преимущественно группами, может образовывать ведьмины круги, по 45-50 плодовых тел. Выглядит гриб аппетитно, но попадается грибникам редко. Произрастает в сухих лесах хвойного типа, где преобладают сосны. Встречается такой гриб и в сосновых борах с минимальной влажностью. Любит расти посреди белых и зелёных мхов, на открытых участках местности, вблизи брусничников. Плодоносит в сентябре.', '/media/mushrooms/placeholder.webp', NULL),
('08838b4a-ec1c-52dc-98d4-dad6c4109492', 'Маслёнок рыжий', 'Масленок неокольцованный', NULL, 'Маслёнковые', false, 'Неизвестно', true, 5, 25, 'Ровная', 'Красновато-рыжий, желтый', 'Выпуклая', 'Красновато-рыжий', 'Трубчатая', 'Гриб считается съедобным, обладающим пищевой ценностью второй категории. Среди съедобных грибов он занимает первое место среди грибов, растущих в смешанном лесу. Излюбленным местом произрастания является почва под лиственницей, с которой гриб образует грибницу. В начале лета первый слой маслят появляется в молодых сосновых и еловых посадках. Пора похода за рыжим масленком совпадает со временем цветения сосны. Второй слой маслят появляется в середине июля, во время цветения липы. Третий слой масленка рыжего собирается с начала августа и до наступления первых сильных заморозков. Произрастает большими группами, чем представляет удобство грибникам при собирании.', '/media/mushrooms/placeholder.webp', NULL),
('c4eb0b96-fdb0-57c2-a22e-4edb0bb6f3a6', 'Трутовик каштановый', NULL, NULL, 'Полипоровые', false, 'Неизвестно', true, 5, 20, 'Ровная', 'Черный, коричневый', 'Вогнутая', 'Коричневый', 'Трубчатая', ': Съедобен ли гриб проверить очень сложно, так как он очень жесткий даже в молодом возрасте. Встречается Каштановый Трутовик на останках лиственных пород деревьев. Предпочитает сырые почвы. Период плодоношения с конца мая и до середины октября. В хорошие сезоны Трутовик встречается повсеместно и обильно. Часто произрастает вместе с Чешуйчатым Трутовиком, наиболее приметным грибов этого рода.', '/media/mushrooms/placeholder.webp', NULL),
('b9a6cd54-485f-5eba-bc5b-6edd1807d9dd', 'Сыроежка чешуйчатая', 'Сыроежка зеленоватая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Белый', 'Вогнутая', 'Зеленый, серо-зеленый', 'Пластинчатая', 'Зеленоватая сыроежка относится к съедобным грибам и считается лучшей среди всех остальных сыроежек по вкусовым качествам. Ее можно применять в пищу в отваренном виде, а также сушеную, маринованную или соленую. Сыроежка чешуйчатая в основном произрастает в лиственных лесах, преимущественно на участках, имеющих кислую почву. Лучше всего ее собирать летом и осенью.', '/media/mushrooms/placeholder.webp', NULL),
('1828b684-ccd4-52b5-9f31-6efdeedbd23c', 'Клатрус Арчера', 'Цветохвостник арчера', NULL, 'Весёлковые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Белый, красный, розовый, серый', 'Гладкая', 'Резкий, отталкивающий запах плодового тела цветохвостника Арчера, а также плохой вкус мякоти обуславливает тот факт, что плодовые тела данного вида соотносят с несъедобными грибами. Описываемый гриб в пищу не употребляют. Клатрус Арчера произрастает с июля по октябрь на почве лиственных и смешанных лесов, встречается на лугах и в парках, так же отмечен на песчаных дюнах. Сапрофит. Встречается редко, но при хороших условиях растет в больших количествах.', '/media/mushrooms/placeholder.webp', NULL),
('aa68134f-33c2-5d67-9d47-458035b5b074', 'Паутинник пачкающий', 'Паутинник голубоствольный', NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый', 'Выпуклая', 'Красно-буроватый, хряно-коричневатый, желто-оранжево-коричневый', 'Пластинчатая', 'Хороший съедобный гриб, используется свежим (отваривание около 15 минут) во вторых блюдах, соленым и маринованным. Паутинник пачкающий обитает с конца июля до конца сентября в лиственных и смешанных (с осиной) лесах, в осинниках, во влажных местах, одиночно и небольшими группами, не часто', '/media/mushrooms/placeholder.webp', NULL),
('fd2b70d7-06e5-5a64-944b-7cb1bee9c4fe', 'Ежовик белый', 'Ежовик беловатый', NULL, 'Ежовиковые', false, 'Неизвестно', true, 5, 30, 'Ровная', 'Белый', 'Ровная', 'Белый', 'Трубчатая', 'Съедобен. Употребляется в отварном, жареном, маринованом виде. Хорош для сушки. Распространение: Северная Америка, страны Европы и Азии. Массово распространён в таких странах, как, например, Болгария, Испания, Италия, Франция. В России замечен в южных регионах, в умеренной лесной зоне.', '/media/mushrooms/placeholder.webp', NULL),
('84f9b796-ba60-5312-9e1c-15905a690e61', 'Обабок чернеющий', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 5, 30, 'Утолщенная внизу', 'Желтоватый, светло-желтый', 'Выпуклая', 'Желтоватый, светло-желтый', 'Лабиринтовидная', 'Известен в Европе. Отмечен в Карпатах и на Кавказе. Гриб съедобен. Употребляется в свежеприготовленном, сушеном и маринованном виде. При сушке чернеет.', '/media/mushrooms/placeholder.webp', NULL),
('be33425d-6948-54d5-98e7-3f82c70e7e32', 'Дисцина щитовидная', 'Блюдцевик розово-красный', NULL, 'Дисциновые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Коричневый, розовато-оливковый', 'Вогнутая', 'Коричневый, розовато-оливковый', 'Гладкая', 'Считается съедобным грибом не самого высокого качества. Дисцина щитовидная попадается с начала мая до середины лета (массовый выход, как правило, приходится на середину или конец мая) в лесах различного типа, в парках, часто располагаясь около гниющих остатков деревьев или прямо на них. Предпочитает, очевидно, древесину хвойных пород.', '/media/mushrooms/placeholder.webp', NULL),
('3da65af5-c10d-57c4-bfd4-81c31b683d1e', 'Альбатреллус сливающийся', 'Альбатреллус сросшийся', NULL, 'Альбатрелловые', false, 'Неизвестно', true, 5, 20, 'Ровная', 'Кремовый', 'Выпуклая', 'Рыжий, розово-бурый', 'Гладкая', 'Альбатреллус сливающийся – однолетний съедобный гриб. Если составлять карту месторасположения этого гриба, то следует отметить часть Европы ( Германия, Украина, Финляндия, Эстония, Швеция, Норвегия), Восточной Азии (Япония), Северной Америки и Австрали. Россияне могут направится собирать Альбатреллус сливающийся в Мурманске, Урале и Сибири.', '/media/mushrooms/placeholder.webp', NULL),
('fe5f514f-b915-5841-be1b-4005bbc8c1a7', 'Подберезовик жестковатый', 'Подберёзовик твердоватый', NULL, 'Болетовые', false, 'Неизвестно', true, 10, 50, 'Ровная', 'Беловатый, бежевый, буроватый', 'Выпуклая', 'Серо-бурый, охряно-бурый, красновато-коричневый, кофейно-молочный', 'Трубчатая', 'Съедобный гриб 2-й категории. За счёт плотной мякоти, богатырских размеров, малой червивости и стойкости к жаре и засухе сопоставим по качеству с Подосиновиками. Может использоваться при любых способах приготовления и заготовки. Вкусный и ароматный гриб в различных блюдах. В России растёт с середины июля и до конца октября (иногда можно встретить и в середине ноября). Образует микоризу с осиной и тополем, в частности с тополем белым и осиной обыкновенной . Растёт в лиственных и смешанных лесах предпочтительно на известковых почвах, но может встретиться и на суглинистых и песчаных почвах. Хорошо переносит жару и засуху. Встречается не часто, одиночно и небольшими группами.', '/media/mushrooms/placeholder.webp', NULL),
('042abd05-66ae-5d94-b6bf-90a5d14c74db', 'Груздь сизоватый', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Белый', 'Выпуклая', 'Белый', 'Пластинчатая', 'Съедобный гриб, но при приготовлении требуется тщательная предварительная обработка (вымачивание в соляном растворе). Также для улучшения вкусовых качеств рекомендуется добавлять различные специи. Груздь сизоватый неплохо переносит засушливые периоды, при этом и вкус мякоти также зависит от погодных условий.', '/media/mushrooms/placeholder.webp', NULL),
('0eb8baa7-fadd-5b19-a920-559eee95cb83', 'Мухомор порфировый', 'Мухомор серый', NULL, 'Аманитовые', false, 'Неизвестно', true, 6, 14, 'С юбкой', 'Белый', 'Ровная', 'Серовато-коричневый, коричневый', 'Пластинчатая', 'По разным источниками Мухомор порфировый считается либо несъедобным из-за неприятного вкуса и запаха, либо ядовитым. Страны Европы и Азии, где есть хвойные и смешанные леса, Северная Америка (США, Канада). Плодовые тела образуются со второй половины лета и до наступления холодов.', '/media/mushrooms/placeholder.webp', NULL),
('1d16156d-5021-5a59-952e-b84f7c4e317a', 'Панус уховидный', 'Пилолистник уховидный', NULL, 'Полипоровые', false, 'Неизвестно', true, 5, 20, 'Ровная', 'Коричневатый', 'Вогнутая', 'Коричневатый', 'Пластинчатая', 'Паннус уховидный малоизвестен, но не ядовит. Никакого вреда человеку, съевшему его, гриб не принесет. В пищу употребляется в свежем и маринованном виде. В Грузии данный гриб используют в сыроварении. Панус уховидный встречается в лиственных лесах, обычно на мертвой древесине. Гриб произрастает целыми пучками. Плодоносит все лето и осень.', '/media/mushrooms/placeholder.webp', NULL),
('4f345464-25af-5bb1-9d1c-03945e482221', 'Дубовик Келе', 'Болет Келе', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 50, 'Ровная', 'Желтоватый', 'Выпуклая', 'Коричневый', 'Трубчатая', 'Дубовик Келе — В принципе съедобный гриб. Но в сыром виде не употребляется. Перед употреблением грибы необходимо прожарить, чтобы устранить вещества, раздражающие кишечник, содержащиеся в грибе. Распространение: Дубовик Келле (Suillellus queletii) встречается в светлых лиственных лесах. Произрастает на пролесках и полянках, а так же в дубовом лесу, и изредка в хвойном. Предпочитает неплодородные, кислые и жесткие почвы, невысокую траву, опавшую листву или мох. Время плодоношения с мая по октябрь. Растет группами. Рядом с дубовиком часто можно встретить мухомор жемчужный, лисичку обыкновенную, пестрый', '/media/mushrooms/placeholder.webp', NULL),
('88a4fe16-ba75-5b31-877f-4bc0980050fd', 'Боровик розово-пурпурный', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 50, 70, 'Утолщенная внизу', 'Лимонно-желтый', 'Выпуклая', 'Красный', 'Трубчатая', 'В сыром виде или недоваренном состоянии гриб употреблять нельзя, потому что он ядовит. Лучше его вообще не собирать, так как он встречается достаточно редко и мало изучен. Ареал обитания данного гриба распространяется на Россию, Украину, Европейские страны. Предпочтительными являются места с теплым климатом. Он очень похож на такие съедобные грибы как Boletus erythropus и Boletus luridus, а также на сатанинский гриб (Boletus satanas) и другие, похожие по окраске, болеты. Источник материала: https://wikigrib.ru/borovik-rozovo-purpurnyj/', '/media/mushrooms/placeholder.webp', NULL),
('bd88c75d-cbc9-5598-8760-c0843da445ea', 'Псилоцибе чешская', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 1, 2, 'Ровная', 'Кремовый', 'Выпуклая', 'Кремовый', 'Пластинчатая', 'Гриб Псилоцибе чешская принадлежит к категории несъедобных и ядовитых грибов, и его употребление человеком нередко приводит к возникновению серьёзных галлюцинаций. На некоторых участках местности описываемый гриб встречается довольно-таки часто. Активно плодоносит только осенью, в период с сентября по октябрь. Найти псилоцибе чешскую грибники могут на подгнивающих ветках деревьев, принадлежащих к лиственным и хвойным породам. Плодовые тела этого гриба произрастают на территории смешанных, хвойных и лиственных лесов.', '/media/mushrooms/placeholder.webp', NULL),
('a12e4bb7-7954-559b-abcb-e2480cae13bc', 'Псатирелла серо-бурая', NULL, NULL, 'Псатирелловые', false, 'Неизвестно', true, 2, 8, 'Ровная', 'Белый', 'Выпуклая', 'Коричневый', 'Пластинчатая', 'Гриб безоговорочно съедобный. Период плодоношения этого гриба начинается в первой половине мая. Встречается Псатирелла серо-бурая на гниющей древесине. Произрастает относительно разрозненными группами, иногда образует плотные сростки. Плодоношение происходит несколькими волнами, последняя волна приходится на середину октября, но это не достоверная информация.', '/media/mushrooms/placeholder.webp', NULL),
('61788dab-082b-5016-9b06-bf27e59ac090', 'Говорушка зимняя', NULL, NULL, 'Трихоломовые', false, 'Неизвестно', true, 4, 6, 'Ровная', 'Оливково-бурый', 'Вогнутая', 'Оливково-бурый', 'Пластинчатая', 'Гриб относится к съедобным, в пищу используется во вторых блюдах и супах, а также его можно мариновать, солить или сушить. Говорушка зимняя произрастает в хвойных лесах на подстилке, периода созревания достигает поздней осенью. Ареал распространения – европейская часть бывшей территории Советского союза, Сибирь, Дальний Восток, Кавказ, Западная Европа, Южная Америка, Северная Африка.', '/media/mushrooms/placeholder.webp', NULL),
('6038bf09-f3cb-5d3b-b026-2658bd0b6623', 'Гипсизигус ильмовый', 'Рядовка ильмовая', NULL, 'Лиофилловые', false, 'Неизвестно', true, 5, 20, 'Утолщенная внизу', 'Светло-бежевый', 'Выпуклая', 'Светло-бежевый', 'Пластинчатая', 'Нормальный съедобный гриб. Гипсизигус ильмовый встречается в августе-сентябре как на гниющей древесине, так и на почве у корней живых деревьев. Как и многие другие представители этого рода, часто встречается большими семьями.', '/media/mushrooms/placeholder.webp', NULL),
('50173907-a391-575a-b9be-dacb85692e9f', 'Трюфель олений', 'Элафомицес зернистый', NULL, 'Элафомицетовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Охряно-коричневый, желтовато-охряный', 'Гладкая', 'Не рекомендован для употребления в пищу человеком. Многие микологи считают олений трюфель несъедобным, однако лесные животные с большим удовольствием едят его. Особенно по вкусу этот вид грибов приходится зайцам, белкам и оленям. рюфель олений (Elaphomyces granulatus) можно встретить достаточно часто в летний и осенний период. Активное плодоношение вида приходится на период с июля по октябрь. Плодовые тела трутовика оленьего предпочитают расти в смешанных и хвойных (еловых) лесах. Изредка этот вид грибов растёт также и в лиственных лесах, выбирая участки в ельниках и под хвойными деревьями.', '/media/mushrooms/placeholder.webp', NULL),
('4ddcd8c0-86d5-5e41-97fe-82faff20b8bf', 'Зонтик Конрада', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 5, 15, 'С юбкой', 'Белый', 'Выпуклая', 'Коричневатый', 'Пластинчатая', 'Съедобный гриб, уступает по вкусовым качествам зонтику пёстрому. В пищу употребляются только шляпки, ножки считаются жёсткими и слишком волокнистыми. Зонтик Конрада обильно плодоносит в конце лета — начале осени, для разных регионов указывается несколько разный диапазон. Пик плодоношения, вероятно, приходится на август-сентябрь, но встретить этот гриб можно с июня по октябрь, при тёплой осени — и в ноябре. Гриб распространён во всей средней полосе, в лесах различных типов (хвойные, смешанные, лиственные), может расти на опушках и открытых полянах, на богатых перегноем почвах и листовом отпаде. Встречается и в городской черте, в больших парках.', '/media/mushrooms/placeholder.webp', NULL),
('4c6af800-aafa-5128-8587-fc22d9a594d4', 'Эксидия железистая', NULL, NULL, 'Эксидиевые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Черный, темно-бурый', 'Гладкая', 'Гриб несъедобен, но не ядовит. Появляется уже весной в апреле-мае и при благоприятных условиях может расти до поздней осени. Распространение — Европа, Европейская часть России, Кавказ, Приморский край.', '/media/mushrooms/placeholder.webp', NULL),
('530c0d2a-1a70-58ab-b3b5-1f97eff9ab71', 'Панеолус синеющий', NULL, NULL, 'Псатирелловые', false, 'Неизвестно', true, 2, 8, 'Ровная', 'Светло-коричневый', 'Выпуклая', 'Светло-коричневый', 'Пластинчатая', 'Синеющий панеолус принадлежит к категории условно-съедобных грибов, но употреблять его в пищу без вреда для здоровья можно только после хорошей термической обработки (отваривания). На территории России панэолус синеющий распространён на Дальнем Востоке, в Приморье, а также – в центральных европейских регионах. Активное его плодоношение начинается в июне, и продолжается до конца сентября. Гриб предпочитает произрастать на луговых пастбищах, на навозе животных, местностях с травянистым ландшафтом.', '/media/mushrooms/placeholder.webp', NULL),
('f84047fe-dfb9-5bcd-8d39-11462eae9ea3', 'Саркосцифа австрийская', 'Эльфова чаша', NULL, 'Саркосцифовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Вогнутая', 'Ярко-красный', 'Гладкая', 'Гриб съедобен. О вкусовых качествах можно спорить, так как явного, хорошо выраженного грибного или какого-то экзотического вкуса тут нет. Однако, несмотря на маленький размер плодовых тел и довольно тонкую мякоть, текстура у этой мякоти — превосходная, плотная, но не резинистая. Ранняя весна. Некоторые источники указывают, что при затяжной осени гриб можно встретить поздней осенью, перед морозами, и даже зимой (декабрь). Распространён в северных регионах Европы и в восточных областях США. Растёт небольшими группами. Так же, как и Саркосцифа алая, этот вид является своеобразным показателем «экологической чистоты»: в промышленных регионах или возле трасс саркосцифы не растут.', '/media/mushrooms/placeholder.webp', NULL),
('f437c7c0-4071-5224-9678-929a835fbd25', 'Боровик красивоокрашенный', 'Болет красивоокрашенный', NULL, 'Болетовые', false, 'Неизвестно', true, 30, 50, 'Утолщенная вверху', 'Кремовый', 'Выпуклая', 'Кремовый', 'Трубчатая', 'Ядовит в сыром виде. Съедобен, низко-среднего качества после варки или сушки. Непопулярен для употребления из-за его редкости и токсичности. В основном устанавливает микоризу с буковыми, которые растут на известняковых почвах, особенно с португальским дубом в южных краях, хотя также ассоциируется с дубом скальным и с дубом черешчатым, которые предпочитают кремнистые почвы. Произрастает с конца лета до глубокой осени. Термофильный вид, связан с теплыми регионами, особенно распространён в Средиземноморье.', '/media/mushrooms/placeholder.webp', NULL),
('61361531-1199-5877-b23f-e6bed0ebb78a', 'Говорушка бледноокрашенная', 'Говорушка серая', NULL, 'Трихоломовые', false, 'Неизвестно', true, 3, 5, 'Утолщенная вверху', 'Серовато-коричневатый', 'Вогнутая', 'Серовато-коричневатый', 'Пластинчатая', 'Считается ядовитым грибом. Распространен со второй половины августа до ноября (поздний вид) в хвойных и смешанных лесах (ель, сосна), группами, не часто.', '/media/mushrooms/placeholder.webp', NULL),
('154eca3e-fe67-5037-812d-2d5fcf2fb100', 'Полевик ранний', 'Полёвка ранняя', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Неопределенно-желтоватый, светло-глинистый, грязно-беловатый', 'Выпуклая', 'Неопределенно-желтоватый, светло-глинистый, грязно-беловатый', 'Пластинчатая', 'Полевик ранний — Нормальный съедобный гриб, хотя некоторые источники указывают на горечь. Полевик ранний встречается с начала июня до середины июля в садах, парках, по краям лесных дорог, предпочитая богатые почвы; может селиться на сильно перегнивших древесных останках. В некоторые сезоны может плодоносить очень обильно, хотя обычно попадается не так часто.', '/media/mushrooms/placeholder.webp', NULL),
('ea16a6ef-034a-5564-9bf5-1498d2d6644c', 'Трутовик плоский', NULL, NULL, 'Ганодермовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Серовато-коричневый, ржаво-коричневый', 'Гладкая', 'Съедобность — гриб не съедобен, его мякоть жесткая и не имеет приятного вкуса. Распространение — растет везде на пнях и валежнике лиственных деревьев, чаще расположен невысоко. Разрушитель древесины! Там где гриб растет, происходит процесс гнили древесины белого или желто-белого цвета. Иногда разрушает ослабленные лиственные деревья( особенно березу) и древесину хвойных пород. В основном растет с мая по сентябрь. Широко распространен в умеренном поясе северного полушария.', '/media/mushrooms/placeholder.webp', NULL),
('5d356fd2-4c31-5b8e-957a-0bfd885627ce', 'Гимнопил сосновый', 'Огневка', NULL, 'Гименогастровые', false, 'Неизвестно', true, 5, 12, 'Утолщенная вверху', 'Бурый, сливочный', 'Выпуклая', 'Золотистый, охряной, желтый, коричневый', 'Пластинчатая', 'Gymnopilus sapineus относится к категории несъедобных грибов. Растет повсеместно (Европа, Россия, Северная Америка), при этом в разных регионах время появления этих грибов различно. Общий срок – с конца июня по начало октября. Предпочитает хвойники, но часто встречается и в лиственных лесах. Растет на пнях, гниющих ветках, целые группы гимнопила встречаются на валежнике.', '/media/mushrooms/placeholder.webp', NULL),
('afb7f34c-8398-5ceb-8ee7-8c20448b8438', 'Родотус дланевидный', NULL, NULL, 'Физалакриевые', false, 'Неизвестно', true, 3, 15, 'Ровная', 'Розоватый', 'Выпуклая', 'Оранжевый, лососевый, розовый', 'Пластинчатая', 'Дланевидный родотус несъедобен. Вообще его пищевые свойства изучены мало, однако слишком жёсткая мякоть не позволяет употреблять этот гриб в пищу. Собственно эти свойства мякоти и делают описываемый вид грибов несъедобным. Родотус дланевидный принадлежит к категории сапротрофов. Он предпочитает обитать преимущественно на пнях и стволах валежника лиственных пород деревьев. Встречается одиночно или небольшими группами, преимущественно на вязовом валежнике. Существуют сведения о произрастании описываемого вида грибов на древесине клёна, американской липы, конского каштана. Грию родотус дланевидный широко распространён на территории многих европейских стран, в Азии, Северной Америке, Новой Зеландии, Африки. В смешанных хвойных и широколиственных лесах увидеть такие грибы можно очень редко. Активное плодоношение дланевидного родотуса приходится на период с весны по глубокую осень.', '/media/mushrooms/placeholder.webp', NULL),
('e369a455-cb41-5050-a194-6cc2f6c752a3', 'Чешуйчатка чешуйчатовидная', NULL, NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 15, 'С юбкой', 'Беловатый, коричневатый, охряно-коричневатый, охряно-бурый, буроватый', 'Выпуклая', 'Беловатый, коричневатый, охряно-коричневатый, охряно-бурый, буроватый', 'Пластинчатая', 'Гриб официально съедобен, в отличие от упомянутой выше Чешуйчатки обыкновенной, которая относительно недавно была переведена в разряд несъедобных грибов. Для тех, кто пробовал Чешуйчатку обыкновенную, замечу, что, поскольку у Чешуйчатки чешуйчатовидной мякоть не горчит и не бывает неприятного запаха, с кулинарной точки зрения этот гриб даже лучше, чем Чешуйчатка обыкновенная. Сезон и распространение: лето и осень. Довольно широко распространен в Северной Америке, Европе, Азиатских странах. Некоторые источники указывают более узкое окно: август-сентябрь.', '/media/mushrooms/placeholder.webp', NULL),
('566784d6-fc4e-5ce3-90e6-fcf1c6a4f2d0', 'Рядовка обутая', NULL, NULL, 'Трихоломовые', false, 'Неизвестно', true, 15, 25, 'С юбкой', 'Белый', 'Вогнутая', 'Буровато-каштановый, буро-серый', 'Пластинчатая', 'Рядовка обутая принадлежит к числу съедобных грибов, и обладает хорошими вкусовыми свойствами. Его особенно сильно ценят в Японии и странах Востока. Этот гриб можно жарить, при этом термическая обработка позволяет устранить неприятный привкус, оставляя лишь сладковатое послевкусие. Хороша рядовка обутая и для маринования. Рядовка обутая произрастает в хвойных (преимущественно – сосновых), а также – в смешанных (сосново-дубовых) лесах. Наиболее активное плодоношение приходится на период с сентября по ноябрь (то есть, на протяжении всей осени). Формирование плодовых тел пятнистых рядовок происходит на достаточно большой для таких растений глубине в грунте. Ножка этого гриба расположена глубоко от поверхности почвы, и поэтому при сборе урожая гриб приходится выкапывать. Аромат рядовки обутой очень своеобразен, похож на запах аниса. Интересно, что когда плодовое тело описываемого вида гриба появляется на поверхности, почва начинает сильно трещать. Такой гриб редко встречается в одиночном виде, произрастает преимущественно большими группами.', '/media/mushrooms/placeholder.webp', NULL),
('ca5df367-518c-51bc-ab0d-1e576baf9547', 'Опёнок тополиный', 'Полёвка цилиндрическая', NULL, 'Строфариевые', false, 'Неизвестно', true, 10, 30, 'Ровная', 'Беловатый, кремовый', 'Вогнутая', 'Беловатый, кремовый', 'Пластинчатая', 'Хороший съедобный гриб, сопоставимый по качествам с Опёнком осенним. По ряду оценок — очень вкусный, с плотной хрустящей текстурой, которая сохраняется при тепловой обработке, и ярким ароматом. Вид распространён в Субтропическом климатическом поясе и в южной части Северного Умеренного климатического пояса, на равнинах и в горах. Широко представлен в Средиземноморском регионе, встречается на юге Центральной и Восточной Европы, Центральной Америке и востоке Северной Америки, Северной Африке, в Юго-Восточной и Передней Азии, в Скандинавии. Отмечен в США, Чили, Канаде, Италии, Франции, Португалии, Испании, Англии, Ирландии, Китае, Японии. В России предпочитает южные регионы Европейской части и Дальнего Востока (Приморский край).', '/media/mushrooms/placeholder.webp', NULL),
('a35d9ecc-4417-55da-96d6-9074f226c0b8', 'Поплавок чёрный', 'Мухомор чёрный', NULL, 'Аманитовые', false, 'Неизвестно', true, 10, 30, 'Ровная', 'Белый', 'Выпуклая', 'Черный', 'Пластинчатая', 'Достоверных сведений из русскоязычных источников нет. Все поплавки считаются условно-съедобными грибами, однако их мало собирают. Неопытные грибники опасаются спутать поплавок с каким-нибудь ядовитым мухомором или бледной поганкой. Кроме того, гриб достаточно хрупкий, что изрядно затрудняет его транспортировку. Растет в одиночку или небольшими группами, встречается с середины осени и до зимы (данные для западного побережья Северной Америки). Официально отмечены наблюдения гриба на юго-западе Канады, в северной Калифорнии, имеются сведения о находках на побережье Тихого океана в штатах Орегон и Вашингтон, а так же в Британской Колумбии. Данных по другим странам пока нет, но это не значит, что Чёрный мухомор не может расти где-то в других местах земного шара.', '/media/mushrooms/placeholder.webp', NULL),
('61646e0e-70c4-58f3-a8fb-cc094cd4922f', 'Звездовик сводчатый', NULL, NULL, 'Геастровые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'желто — коричневый', 'Гладкая', 'Гриб пригоден к употреблению в самом молодом своем возрасте, когда по форме он напоминает шарик. Но в таком виде его достаточно трудно найти, так как гриб почти полностью в это время погружен в землю. Может употребляться без предварительного отваривания или обжаривания. Ареал распространения гриба захватывает леса умеренной российской полосы. Излюбленным местом поселения гриба являются карбонатные почвы. Звездовик сводчатый растет небольшими группами, образующими ведьмины кольца. Его активное плодоношение приходится на начало и конец осени.', '/media/mushrooms/placeholder.webp', NULL),
('9eb3455e-ddf2-5adc-ba51-772ce60b7467', 'Ежовик гребенчатый', NULL, NULL, 'Герициевые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Белый', 'Гладкая', 'Ежовик съедобен. Гриб по вкусовых качествам похож на мясо креветок. Растет в Хабаровском крае, Амурской области, на севере Китая, Приморском крае, в Крыму и предгорьях Кавказа. Очень редко встречается в лесах на стволах живых дубов, в их дуплах и на пнях. В большинстве стран числится в «Красной книге».', '/media/mushrooms/placeholder.webp', NULL),
('5639e726-494a-50bc-8c8a-a00f9a642337', 'Сыроежка буреющая', 'Сыроежка ароматная', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Белый, красноватый', 'Выпуклая', 'Красный, пурпурный, фиолетово-пурпурный, желтовато-коричневый, буровато-оливковый', 'Пластинчатая', 'Съедобный гриб 3 категории. Рекомендуется непродолжительное предварительное отваривание, но можно обойтись и без него, варка помогает моментально избавиться от запаха: после закипания «селёдочный» запах полностью исчезает. При жарке без предварительного отваривания соседям может показаться, что вы жарите селёдку. Но этот запах тоже довольно быстро выпаривается. Гриб употребляют вареным, жареным, маринованным или солёным. Сыроежка буреющая плодоносит с конца июня — начала июля до ноября, в хвойных и смешанных лесах, в одиночку и группами, образует микоризу с соснами и елями. Растёт в странах Европы и Азии. В Северной Америке есть свои «селёдочные» сыроежки, очень схожие с буреющей, однако Russula xerampelina считается европейским (евразийским) видом.', '/media/mushrooms/placeholder.webp', NULL),
('2578c0b2-2d69-53d0-a19a-353f8bce8505', 'Климакодон северный', NULL, NULL, 'Фанерохетовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Белый', 'Гладкая', 'Несъедобный гриб из-за твердой консистенции. Встречается с середины июля в лесах различного типа, поражая ослабленные лиственные деревья. Однолетние плодовые тела могут держаться до осени, но в конце концов, как правило, бывают поглощены насекомыми. Сростки климакодона северного могут достигать весьма внушительных объемов — до 30 кг.', '/media/mushrooms/placeholder.webp', NULL),
('628a4b01-5b57-5bae-8562-fe49e7269acc', 'Рогатик гроздевой', 'Рамария гроздевидная', NULL, 'Гомфовые', false, 'Неизвестно', true, 15, 60, 'Ровная', 'Желтовато-бурый, охряный, розовато-красный', 'Ровная', 'Желтовато-бурый, охряный, розовато-красный', 'Гладкая', 'Гриб съедобен, употребляется в свежем виде исключительно в молодом возрасте. Это один из самых вкусных съедобных грибов семейства Рогатиковых. Рогатик Гроздевой встречается в смешанных и лиственных лесах, преимущественно возле буков, реже под хвойными породами деревьев. Растет с июля по октябрь, пока температура почвы держится в пределах 12-20 градусов. Гриб встречается не часто.', '/media/mushrooms/placeholder.webp', NULL),
('7e837070-c749-5bbe-99e4-c76a6d2f3fbb', 'Сыроежка зелёная', NULL, NULL, 'Сыроежуовые', false, 'Неизвестно', true, 10, 20, 'Утолщенная вверху', 'Беловатый', 'Выпуклая', 'Серовато-зеленый, желтовато-зеленый, оливково-зелёный', 'Пластинчатая', 'Съедобный гриб со спорными вкусовыми качествами. Старые бумажные справочники относят зелёную сыроежку к грибам 3 категории и даже 4 категории. Растёт летом и осенью, одиночно или небольшими скоплениями, не редко. Широко распространена во многих странах.', '/media/mushrooms/placeholder.webp', NULL),
('2e95cdf1-3195-57b4-87ad-57c27f58ba3c', 'Рамария обыкновенная', 'Рогатик Инвала', NULL, 'Гомфовые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Бледно-охряный, охряно-коричневый', 'Гладкая', 'Условно-съедобный (в некоторых справочниках — съедобный) гриб низкого качества, используется свежим после отваривания. Чтобы избавиться от горечи, в некоторых рецептах рекомендуется длительное, 10-12 часов, вымачивание в холодной воде, несколько раз меняя воду. Лето-осень, с начала июля до октября. Растёт на подстилке в хвойных лесах, обильно, часто, ежегодно.', '/media/mushrooms/placeholder.webp', NULL),
('4accfe97-1239-523e-b443-508a36cebca3', 'Трутовик ячеистый', NULL, NULL, 'Полипоровые', false, 'Неизвестно', true, 10, 30, 'Ровная', 'Оранжеватый, желтоватый', 'Вогнутая', 'Оранжеватый, желтоватый', 'Лабиринтовидная', 'Ячеистый трутовик считается съедобным в молодом возрасте. Сезон и распространение: Обычно первые плодовые тела появляются поздней весной, но часто встречается летом и осенью. Гриб растет как поодиночке, разбросанно, так и довольно большими скоплениями. Иногда на одной небольшой ветке можно встретить с десяток грибов разного возраста и размера.', '/media/mushrooms/placeholder.webp', NULL),
('99f7fd50-5749-52de-8951-677fb7c90889', 'Порховка свинцово-серая', 'Чёртов табак', NULL, 'Шампиньоновые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Белый, светло-коричневый', 'Гладкая', 'Съедобный гриб 4-й категории. Съедобен в молодом возрасте, когда мякоть белая, только пока не перешёл в стадию созревания. Можно жарить, мариновать, солить, сушить, морозить. Распространён в регионах с умеренным климатом. Отмечен в Северной Америке, Европе и Азии. В России также встречается в зоне умеренного климата Европейской части, Урала, Сибири, Дальнего Востока. Почвенный сапротроф открытых пространств. Предпочитает бедные песчаные почвы, растёт на лугах, степных пастбищах, вдоль дорог, оврагов, канав, на лесных полянах, вырубках, нарушенных участках, в редкой траве, тундре, песчаных дюнах, встречается на высокогорных альпийских лугах Кавказа. Растёт небольшими группами и одиночно, встречается относительно часто. На территории России растёт с июля по сентябрь, на юге России до ноября.', '/media/mushrooms/placeholder.webp', NULL),
('f59db155-0709-5f29-a72b-1612476ffbdd', 'Строфария морщинисто-кольцевая (Кольцевик)', 'Строфария морщинисто-кольцевая', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Белый', 'Выпуклая', 'Желтоватый, красно-коричневый', 'Пластинчатая', 'Кольцевик съедобный ценный гриб, по вкусу напоминает белый гриб, хотя и отличается специфичным запахом. Мякоть гриба содержит много витаминов группы В и много минеральных веществ. В нем содержится больше никотиновой кислоты, чем в огурцах, капусте и помидорах. Эта кислота благотворно воздействует на пищеварительные органы и нервную систему. Для грибов этого вида достаточно просто подготовить питательный субстрат. По сравнению с шампиньонами они не прихотливы к условиям выращивания на приусадебных участках. Кольцевик преимущественно произрастает на хорошо удобренной почве, на останках растений вне леса, реже в лиственных лесах. Период плодоношения с начала лета и до середины осени. Для приусадебного выращивания, для них выбирают защищенные от ветра, теплые места. Так же его можно выращивать под пленкой, в парниках, подвалах и на грядках.', '/media/mushrooms/placeholder.webp', NULL),
('9239ec34-0dad-5cb0-9095-7a38816a7c0f', 'Маслёнок Беллини', NULL, NULL, 'Маслёнковые', false, 'Неизвестно', true, 20, 30, 'Утолщенная внизу', 'Красноватый, коричневатый', 'Выпуклая', 'Коричневый, белый', 'Лабиринтовидная', 'Масленок Беллини – съедобный гриб, который можно мариновать и отваривать. Гриб под названием Масленок Беллини предпочитает обитать в хвойных или сосновых лесах, при этом, не предъявляя особых требований к составу почвы. Может произрастать как одиночно, так и группами. Плодоношение гриба происходит только осенью.', '/media/mushrooms/placeholder.webp', NULL),
('ec4fc059-776d-515e-88d0-461b70aa5a6b', 'Гигрофор пятнистый', NULL, NULL, 'Гигрофоровые', false, 'Неизвестно', true, 1, 5, 'Ровная', 'Сероватый', 'Выпуклая', 'Сероватый', 'Пластинчатая', 'Съедобен, как и подавляющее большинство гигрофоров; правда, трудно сказать, насколько именно. Считается малоизвестным съедобным грибом с нежным сладковатым вкусом, используется свежим (отваривание около 5 минут), в супах и вторых блюдах. Гигрофор пятнистый встречается с середины сентября по конец октября в хвойных или смешанных лесах, образуя микоризу с елью; в хорошие сезоны плодоносит очень большими группами, хотя общая неприметность не позволяет этому достойному гигрофору снискать славы.', '/media/mushrooms/placeholder.webp', NULL),
('9f7045a9-283a-5397-9c57-3d894c75fc1a', 'Мухомор щетинистый', NULL, NULL, 'Аманитовые', false, 'Неизвестно', true, 10, 40, 'Утолщенная внизу', 'Желтоватый, белый', 'Выпуклая', 'Белый, сероватый, светло-охряный, зеленоватый', 'Пластинчатая', 'Мухомор щетинистый (Amanita echinocephala) принадлежит к категории несъедобных грибов. Щетинистый мухомор распространён в лиственных и смешанных лесах, где также растут дубы. Встретить такой вид грибов можно редко. Он предпочитает произрастать в прибрежных зонах около озёр или рек, хорошо себя чувствуют в известковых почвах. Большее распространение щетинистые мухоморы получили на территории Европы (преимущественно в её южных регионах). Известны случаи обнаружения этого вида грибов на Британских островах, в Скандинавии, Германии и в Украине. На территории Азии описываемый вид грибов может расти в Израиле, Западной Сибири и Азербайджане (Закавказье). Щетинистый мухомор активно плодоносит в период с июня по октябрь.', '/media/mushrooms/placeholder.webp', NULL),
('78b8604b-7dff-5dcc-aeef-5baf5a5fb91b', 'Опёнок ссыхающийся', NULL, NULL, 'Физалакриевые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Белый, коричневатый, желтоватый', 'Вогнутая', 'Рыжевато-коричневый', 'Пластинчатая', 'Гриб под названием опенок ссыхающийся на вкус очень приятный, пригоден для употребления в пищу в различных видах. Опенок ссыхающийся (Armillaria tabescens) произрастает группами, преимущественно на стволах и ветках деревьев. Встретить их можно также на гнилых, трухлявых пнях. Обильное плодоношение данных грибов начинается в июне, и продолжается до середины декабря.', '/media/mushrooms/placeholder.webp', NULL),
('a68a5026-8f3a-5c57-8c62-eb505fc1c954', 'Сыроежка болотная', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 30, 'Ровная', 'Белый', 'Выпуклая', 'Ярко-красный, оранжево-красный', 'Пластинчатая', 'Сыроежка болотная — хороший и вкусный съедобный гриб. Его используют для маринования и соления, но можно употреблять и в жареном виде. Обитание: Болотная сыроежка чаще всего встречается в хвойных лесах. Сезоном ее активного роста являются летние и осенние месяцы. Встречается гриб в сыроватых сосновых лесах, по краю болот, на влажных торфянисто-песчаных почвах с июня по сентябрь. Образует микоризу с сосной.', '/media/mushrooms/placeholder.webp', NULL),
('19284681-d06f-5130-b487-f021d5a4e9cf', 'Строфария полушаровидная', NULL, NULL, 'Строфариевые', false, 'Неизвестно', true, 3, 8, 'Ровная', 'Бледно — желтый', 'Выпуклая', 'Охрянный, лимонный', 'Пластинчатая', 'Строфария полушаровидная признан как гриб ''Сомнительная съедобность'', что указывает на потенциальные риски при употреблении. Его практическое использование ограничено из-за неоднозначной съедобности. Собиратели должны проявлять осторожность, так как он не является популярным выбором для кулинарных целей. Время сбора: с весны до осени. Местонахождение: на навозе. АКТИВHОСТЬ: отсутствует или очень незначительная.', '/media/mushrooms/placeholder.webp', NULL),
('b4996372-e5df-5f19-83ad-82027ee43114', 'Боровик Берроуза', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 20, 40, 'Утолщенная в центре', 'Беловатый, кремовый, розовато-коричневый, коричневый', 'Выпуклая', 'Беловатый, кремовый, розовато-коричневый, коричневый, сероватый', 'Лабиринтовидная', 'Съедобный гриб 2-й категории. Из этого гриба готовят самые разнообразные блюда: супы, соусы, поджарки и дополнения к гарнирам. Также Боровик Берроуза можно сушить, ведь в его мякоти немного влаги. Распространён в Северной Америке, в основном на территории США. Отмечен в Колорадо, Нью-Мексико, Аризоне, Юте, на западе Калифорнии. Период плодоношения с июня по август. Предпочитает тёплый климат, хвойные, реже, светлые лиственные (с дубом, буком, грабом, каштаном) леса. Встречается не часто малыми группами. На территории Европы и России не произрастает.', '/media/mushrooms/placeholder.webp', NULL),
('f2042d0a-e224-5ba4-bfbf-4cc20765e50e', 'Энтолома сепиум', 'Энтолома светло-коричневая', NULL, 'Энтоломовые', false, 'Неизвестно', true, 10, 20, 'Утолщенная вверху', 'Белый, кремово-белый', 'Вогнутая', 'Желтоватый, желтовато-бурый, коричнево-серый', 'Пластинчатая', 'Гриб является съедобным, используется для приготовления первых и вторых блюд, но вкуснее всего он в маринованном виде. Энтолома сепиум образует микоризу с плодовыми деревьями: абрикосом обыкновенным и боярышником джунгарским, может расти рядом со сливой, алычой, терном и другими подобными садовыми деревьями и кустарниками. Произрастает на горных склонах, но также может встречаться и в культурных плантациях (садах, парках). Часто образует рассеянные группы. Сезон роста начинается в конце апреля и заканчивается в конце июня. Этот гриб встречается в Казахстане и Западном Тянь-Шане, там, где растут деревья-симбионты. Она любит расти на северных склонах гор, в промоинах и оврагах.', '/media/mushrooms/placeholder.webp', NULL),
('045f8c3b-9ab2-5545-b35f-c54986b46231', 'Трутовик ямчатый', NULL, NULL, 'Полипопровые', false, 'Неизвестно', true, 2, 4, 'Ровная', 'Коричневый, желтовато-коричневый', 'Ровная', 'Тускло-коричневый', 'Лабиринтовидная', 'Сведения противоречивы. Одно можно сказать с большой долей уверенности: гриб не ядовит. Европейская традиция относит его к несъедобным грибам, хотя он, подобно множеству других полипорусов, вполне съедобен в молодом возрасте, пока мякоть не стала слишком жёсткой. Другое дело, что ножка у него жёсткая почти всегда, а в шляпке слой мякоти катастрофически тонкий, около одного миллиметра, и есть там особо нечего. Трутовик ямчатый находится в списках съедобных грибов в таких странах, как, например, Гонконг, Непал, Папуа — Новая Гвинея и Перу.', '/media/mushrooms/placeholder.webp', NULL),
('21ca8fb0-ac70-591f-b634-e59b82abbcab', 'Вольвариелла шелковистая', 'Вольвариелла бомбицина', NULL, 'Плютеевые', true, 'Неизвестно', true, 10, 25, 'С юбкой', 'Мучной, желтоватый', 'Выпуклая', 'Мучной, желтоватый', 'Пластинчатая', 'Вольвариелла шелковистая встречается грибникам достаточно редко. Она распространена в лесах смешанного типа и в крупных природных парках. Излюбленным местом для поселения выбирает мертвые и ослабленные болезнями стволы лиственных деревьев. Из деревьев предпочтение отдает клену, иве и тополю. Период активного плодоношения длится с начала июля по конец августа. Вольвариела пригодна к употреблению в свежем виде после предварительного отваривания. Отвар после приготовления сливается.', '/media/mushrooms/placeholder.webp', NULL),
('49a0ab87-9cb5-56a6-9777-b0844e03a6c6', 'Плютей ивовый', 'Плютей вербовый', NULL, 'Плютеевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Сероватый, оливковый, голубоватый, зеленоватый', 'Выпуклая', 'Серовато-зелёный, серо-голубоватый, коричнево-серый, пепельно-серый', 'Пластинчатая', 'Активное плодоношение ивовых плютеев приходится на период с июня по октябрь (а при произрастании в тёплых климатических условиях гриб плодоносит с ранней весны и до самой поздней осени). Описываемый вид грибов произрастает преимущественно в смешанных и лиственных лесах, отдаёт предпочтение влажным местностям и принадлежит к категории сапротрофов. Ивовый плютей принадлежит к числу съедобных грибов, однако его маленькие размеры, слабый, невыразительный вкус и редкость обнаружения не дают возможности собирать этот вид и применять его в пищу.', '/media/mushrooms/placeholder.webp', NULL),
('fccd348b-626f-5514-bc31-dd815e658e97', 'Рядовка серебристая', 'Рядовка желтеющая, Рядовка резная', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 7, 'Ровная', 'Серый, беловатый', 'Выпуклая', 'Серый, серо-буро-жёлтый, серебристо-коричневатый', 'Пластинчатая', 'Рядовка серебристая произрастает в лесах различных типов. Нередко этот вид грибов можно встретить посреди парков, скверов, садов, лесозащитных полос, вдоль обочин дорог, на травянистых участках местности. Гриб предпочитает произрастать на известковых почвах. На территории России и, в частности, Подмосковья, плодоношение серебристых рядовок начинается в июне и продолжается до второй половины осени. Вкус у рядовки серебристой – посредственный, этот гриб рекомендуют употреблять в пищу солёным, маринованным либо свежим.', '/media/mushrooms/placeholder.webp', NULL),
('e522e40f-c40c-59d4-ad84-68d902b5049c', 'Груздь пергаментный', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 25, 'Утолщенная вверху', 'Белый, желтоватый', 'Ровная', 'Белый, желтоватый, кремоватый', 'Пластинчатая', 'Груздь пергаментный растёт иногда большими группами в смешанных лесах. Условно съедобный гриб, второй категории. Собирают в августе-сентябре. Годится гриб только для засола после длительного вымачивания.', '/media/mushrooms/placeholder.webp', NULL),
('3e0382d9-f24b-554f-8fcc-b377c64941d2', 'Паутинник большой', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Белый, бледно-лиловый, бурый', 'Выпуклая', 'Серо-фиолетовый, коричневатый', 'Пластинчатая', 'Большой паутинник произрастает преимущественно в хвойных и лиственных лесах, на почвах песчаного типа. Очень часто этот вид гриба можно встретить на лесных опушках. Широко распространён на территории многих европейских стран. Наилучшим временем для сбора большого паутинника является первый месяц осени Паутинник большой является съедобным грибом, который можно приготавливать сразу для употребления в пищу, или делать заготовки из гриба впрок (консервировать, мариновать, сушить).', '/media/mushrooms/placeholder.webp', NULL),
('c7b61c94-daa6-5bbd-80a7-4954fb5e1def', 'Сыроежка зелёно-красная', 'Сыроежка Лайковая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Белый, розоватый, желтоватый', 'Вогнутая', 'Фиолетово-красный, красно-коричневый, охристый', 'Пластинчатая', 'Сыроежка зелёно-красная произрастает небольшими группами или одиночно на земле в лиственных лесах (березовые рощи, леса с примесью дуба и клена) с начала июля до конца сентября. Популярна как и в Евразии так и в Северной Америке. Гриб съедобен и относится к третьей категории. Употребляется в соленом или вареном виде.', '/media/mushrooms/placeholder.webp', NULL),
('9226c4c4-48ce-513c-a281-3d27c22cb86e', 'Подосиновик дубовый', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 20, 50, 'Утолщенная внизу', 'Беловатый, коричневатый', 'Выпуклая', 'Коричневый, сине-лиловый, кирпичный, оранжеватый', 'Трубчатая', 'Подосиновик дубовый растет с июня до конца сентября небольшими группами, предпочитая, в отличие от своего более известного родственника, заключать союз с дубом.', '/media/mushrooms/placeholder.webp', NULL),
('b3ccbf0d-2ecb-590c-87e6-7c5623fdf305', 'Обабок дальневосточный', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 20, 35, 'Утолщенная внизу', 'Бурый, охряный', 'Выпуклая', 'Буроватый, желтоватый', 'Трубчатая', 'Встречается в южной части Приморского края, произрастает в дубняках. Местами произрастает достаточно обильно. Время плодоношения август – сентябрь. Обабок дальневосточный годен для употребления в пищу.', '/media/mushrooms/placeholder.webp', NULL),
('c4b2cf1d-74de-51af-918d-03229dee7a8b', 'Болетин азиатский', NULL, NULL, 'Маслёнковые', false, 'Неизвестно', true, 15, 25, 'Утолщенная вверху', 'Грязно-оливковый, красноватый, желтоватый', 'Ровная', 'Пурпурно-красный', 'Трубчатая', 'Болетин азиатский произрастает только в Западной и Восточной Сибири, на Дальнем Востоке (преимущественно в Амурской области), а кроме того на Южном Урале. Распространен среди лиственницы, и в ее культурах встречается в Европе (в Финляндии). Период плодоношения наступает в августе-сентябре. Гриб образует с лиственницей микоризу, поэтому растет только там, где есть эти деревья. Относится к числу съедобных грибов.', '/media/mushrooms/placeholder.webp', NULL),
('fb380732-df0d-5cc3-8c0e-e770656fcbff', 'Рыжик красный', 'Рыжик кровавый, Рыжик кроваво-красный, Млечник красный', NULL, 'Сыроежковые', true, 'Неизвестно', true, 10, 25, 'Утолщенная вверху', 'Тёмно-красноватый', 'Вогнутая', 'Красновато-оранжевый, светло-красный, красновато-коричневый, кроваво-красный', 'Пластинчатая', 'Период плодоношения с августа по ноябрь. Образует микоризу с сосной. Растёт в сосновых и смешанных с сосной лесах, на известковых почвах в светлых местах, предпочитает гористую местность, любит расти под папоротником, теплолюбивый вид. В странах СНГ встречается не очень часто, группами. Превосходный съедобный гриб 1-й категории. Используется солёным, маринованным, варёным, жареным.', '/media/mushrooms/placeholder.webp', NULL),
('b7e2f80d-e564-55e2-9b38-9985205c299c', 'Сыроежка сереющая', 'Сыроежка выцветающая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Белый, сероватый', 'Ровная', 'Желтовато-красно-оранжевый, желто-коричневый', 'Пластинчатая', 'Сыроежка сереющая широко распространена в еловых лесах Евразии, а также в Северной Америке, однако во многих странах редка и занесена в местные Красные книги. Гриб съедобен, третьей категории. В пищу употребляется шляпка в свежем и соленом виде.', '/media/mushrooms/placeholder.webp', NULL),
('21fb015c-a2a9-554e-afd7-9bb0e96f3b96', 'Болетин болотный', 'Решётник болотный, Маслёнок ложный, Иванчик', NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная вверху', 'Желтый, красноватый', 'Выпуклая', 'Бордовый, вишнёво-красный, пурпурно-красный, желтоватый, красно-охристый', 'Трубчатая', 'Болетин болотный обитает в лиственничниках и смешанных лесах с присутствием лиственницы, в сухих и влажных местах, в июле – сентябре. Широко распространен в Западной и Восточной Сибири, а также на Дальнем Востоке. В европейской части России встречается в культурных насаждениях лиственницы. Болетин болотный — Съедобный гриб, но высокими вкусовыми качествами не отличается.', '/media/mushrooms/placeholder.webp', NULL),
('6f50bb0c-3c56-5da6-94a7-1859a56e07be', 'Млечник неедкий', 'Млечник оранжевый', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Светло-оранжевый, желтоватый', 'Ровная', 'Оранжевый', 'Пластинчатая', 'Млечник неедкий встречается с середины лета до октября месяца как в хвойных, так и в смешанных лесах, предпочитая образовывать микоризу с елью. Часто может быть обнаружен во мху, где и выглядит наиболее характерно. Млечник неедкий — съедобный гриб; однако любой грибник без подготовки назовет вам десяток видов, плодоносящих в те же сроки, которые будут гораздо более уместны в корзине, нежели чем млечник неедкий.', '/media/mushrooms/placeholder.webp', NULL),
('e7a698e8-7058-5b23-9d65-906963fa08f8', 'Шампиньон плоскошляпковый', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Мучноватый, белый', 'Выпуклая', 'Белый, сероватый, серовато-коричневый', 'Пластинчатая', 'Встречается, как правило, осенью в лиственных и смешанных лесах, иногда вблизи жилья. Гриб в некоторых источниках объявлен несъедобным, в других слабо ядовитым. Лучше избегать употребления в пищу, так как у некоторых людей может вызвать желудочно-кишечные расстройства.', '/media/mushrooms/placeholder.webp', NULL),
('ea6543bb-6978-5e99-a22c-4699421836dd', 'Сыроежка розовая', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 30, 'Ровная', 'Белый, розоватый, желтоватый', 'Выпуклая', 'Красноватый, розоватый, бархатный', 'Пластинчатая', 'Гриб повсеместно распространен в лесах Евразии, Северной Америки. Излюбленные его леса – широколиственные, но часто он может быть встречаться в хвойных лесах. Кроме того, сыроежка красивая обитает и в горных регионах. Здесь его излюбленное место – склоны холмов. Некоторые знатоки грибов относят его к условно-съедобным и даже ядовитым. Гриб также подходит для употребления в соленом виде.', '/media/mushrooms/placeholder.webp', NULL),
('14ee5bc9-138c-5ade-a73f-291e8c97041b', 'Млечник ароматный', 'Груздь ароматный, Солодчак, Млечник пахучий, Млечник кокосовый, Млечник душистый', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Сероватый, желтоватый, бледно-кремовый', 'Вогнутая', 'Сиренево-серый, охристо-серый, розово-коричневый', 'Пластинчатая', 'Период плодоношения млечника ароматного приходится на период с августа по октябрь. Плодовые тела гриба произрастают под берёзами, в смешанных и лиственных лесах. Часто грибники встречают их посреди опавших листьев. Млечник ароматный принадлежит к числу условно-съедобных грибов. Его чаще употребляют в солёном виде, а также в качестве хорошего ароматизатора к различным видам блюд.', '/media/mushrooms/placeholder.webp', NULL),
('daba01ed-a681-5494-aca8-b79582b013e8', 'Строфария корончатая', 'Строфария рыжая, Кольцевик корончатый, Строфария украшенная', NULL, 'Гименогастровые', false, 'Неизвестно', true, 15, 20, 'С юбкой', 'Беловатый, желтоватый', 'Выпуклая', 'Серо-желтый, желтый, лимонный', 'Пластинчатая', 'Встречается Строфария корончатая на лугах и пастбищах. Предпочитает унавоженные и песчаные почвы. Может расти и на равнинах и на невысоких холмах. Растет небольшими группами, скорее рассеяно. Никогда не образует больших скоплений. Чаще произрастает поодиночке или по два-три гриба в сростке. Период плодоношения с лета и до конца осени. О съедобности строфарии корончатой имеются противоречивые сведения. Одни источники указывают, гриб, как условно-съедобный, другие, как гриб несъедобный. Так же есть информация, что гриб возможно ядовит. Поэтому, скорее всего, употреблять в пищу его не стоит.', '/media/mushrooms/placeholder.webp', NULL),
('84f13ad7-ec1d-5190-b37a-6e9d92ca6cd6', 'Лепиота каштановая', 'Зонтик каштановый, Каштановый рыжик', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 2, 10, 'Ровная', 'Красноватый, бело-кремовый, коричневатый', 'Выпуклая', 'Красноватый, коричневый', 'Пластинчатая', 'Встречается в хвойных и лиственных лесах, преимущественно поодиночке или небольшими группами, на почве, подстилке. Предпочитает сосны, каменистые, известковые и песчаные почвы. Реже встречается у плосколистных растений, таких как каменный дуб и пробковый дуб. Растёт не только в лесах под деревьями, может заселять обочины дорог, лужайки, открытые тенистые места. Ядовитый гриб. Ряд источников осторожно пишет, что Лепиота каштановая «не рекомендуется к сбору», так как большинство лепиот ядовиты, и чтобы избежать потенциальной угрозы, не надо их собирать.', '/media/mushrooms/placeholder.webp', NULL),
('0512801b-c567-53a9-9851-9683c3c6c8ee', 'Мухомор шишковидный', NULL, NULL, 'Аманитовые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Белый', 'Ровная', 'Белый, сероватый, кремовый', 'Пластинчатая', 'Места обитания -лиственные дубовые леса, парки, известковая почва. В России мухомор шишковидный встречается только в Белгородской области, где известно несколько местонахождений в Новооскольском и Валуйском районах. Кроме того, встречается в Эстонии, Латвии, на Украине, в Восточной Грузии, а также в Центральном и Восточном Казахстане, в Западной Европе, за исключением ее северной части. Условно-съедобен, однако можно спутать с ядовитыми представителями рода. По этому употреблять категорически не рекомендуем, если не уверены на 100%.', '/media/mushrooms/placeholder.webp', NULL),
('7c6db54f-11b1-5d66-9735-a0d025f6a69a', 'Ежовик шероховатый', 'Саркодон шероховатый', NULL, 'Банкеровые', false, 'Неизвестно', true, 10, 25, 'Утолщенная вверху', 'Бледно-коричневый', 'Вогнутая', 'Красновато-коричневый, пурпурно-коричневый', 'Пластинчатая', 'Ежовик шероховатый относится к группе видов, микоризных с хвойными и твердолиственными породами деревьев; растет в одиночку или или группами. Плодоносит с конца лета и всю очень. Этот гриб считается несъедобным из-за горького вкуса.', '/media/mushrooms/placeholder.webp', NULL),
('f769fbb9-2976-59ad-b341-960a54604e37', 'Рядовка сросшаяся', 'Лиофиллум сросшийся', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 10, 'Утолщенная вверху', 'Белый, сероватый', 'Ровная', 'Белый, сероватый', 'Пластинчатая', 'Встречается с начала осени до конца октября в лесах различного типа, предпочитая разреженные участки, нередко растет вдоль лесных дорог и на самих дорогах. Как правило, плодоносит сростками (пучками), объединяющими 5-15 экземпляров разного размера. Гриб съедобен, но, по единодушным утверждениям видных авторов, совершенно невкусен. Согласно недавним исследованиям, Рядовка сросшаяся может содержать производные ядовитого вещества гиромитрин.', '/media/mushrooms/placeholder.webp', NULL),
('f65691ff-876f-5522-aaeb-d673fbfc08c0', 'Энтолома весенняя', 'Розовопластинник весенний', NULL, 'Энтоломовые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Серо-коричневый, черно-коричневый, оливковый', 'Вогнутая', 'Серо-коричневый, черно-коричневый, оливковый', 'Пластинчатая', 'Энтолома весенняя растет с середины мая до середины или конца июня на лесных опушках, реже в хвойных лесах, предпочитая песчанные почвы. И наши, и зарубежные источники относят Энтолому весеннюю к ядовитым грибам.', '/media/mushrooms/placeholder.webp', NULL),
('38226b2c-fcce-5049-ac5d-2f270df5a694', 'Псатирелла Кандолля', 'Ложноопёнок Кандолля, Хруплянка Кандолля, Гифолома Кандолля', NULL, 'Псатирелловые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Беловато-кремовый', 'Выпуклая', 'Серовато-белый, желто-коричневый', 'Пластинчатая', 'Время плодоношения – с мая и до начала осени. Псатирелла Кандолля встречается в лиственных и смешанных лесах, в огородах и парках, преимущественно на корнях и пнях лиственных деревьев. Произрастает большими группами. Старые источники причисляют гриб Псатирелла Кандолля к несъедобным и даже ядовитым грибам, но современная литература называет его вполне пригодным для употребления грибом, требующим предварительного отваривания.', '/media/mushrooms/placeholder.webp', NULL),
('d39971e1-3bab-5e6b-b57b-ccb8df6cb5dc', 'Катателазма вздутая', 'Шампиньон сахалинский', NULL, 'Катателазмовые', false, 'Неизвестно', true, 25, 35, 'С юбкой', 'Беловатый, светло-коричневатый, сероватый', 'Ровная', 'Белый, кремовый', 'Пластинчатая', 'Шампиньон сахалинский растет летом и осенью в хвойных лесах. На территории России встречается в хвойных и смешанных лесах Дальнего Востока. У этого гриба на беловатой шляпке часто образуются характерные серые пятна.Предположительно микоризная. Растет летом и осенью в одиночку или небольшими группами на земле под хвойными деревьями. Катателазма вздутая считается съедобным грибом высокого качества. В некоторых странах имеет промысловое значение. Употребляется в любом виде, можно варить, жарить, тушить, мариновать.', '/media/mushrooms/placeholder.webp', NULL),
('d7e1efe2-ff56-5174-a310-a21b53c4f85e', 'Шишкогриб хлопьеножковый', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 10, 30, 'Ровная', 'Серо-белый, серый, серовато-оливково-коричневый, черноватый', 'Выпуклая', 'Серо-коричневый, черно-коричневый', 'Трубчатая', 'Шишкогриб хлопьеножковый распространен во всем умеренном поясе северного полушария, был видимо занесен и в южное. Растет летом и осенью в хвойных и лиственных лесах, предпочитая холмы и кислые почвы. В низинах он образует микоризу с буками, а в местах расположенных выше растет под елями и пихтами. Плодоношение одиночно или малыми группами. Шишкогриб хлопьеножковый не ядовит, но старые жесткие ножки плохо перевариваются. В Германии признан несъедобным, в Америке отнесен к числу хороших грибов, в большинстве стран Европы его собирают, но считают низкокачественным.', '/media/mushrooms/placeholder.webp', NULL),
('f5a52ad2-6855-5e56-985d-1e70a313721f', 'Паутинник красивейший', 'Паутинник красноватый', NULL, 'Паутинниковые', false, 'Неизвестно', true, 25, 50, 'Ровная', 'Оранжево-бурый, охристый, лимонно-желтый', 'Выпуклая', 'Рыжевато-оранжевый, красновато-оранжевый, коричневый', 'Пластинчатая', 'Растёт во влажных хвойных лесах. Встречается преимущественно среди мхов с мая по сентябрь. Гриб смертельно ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('6f51ecc8-129c-5e3b-a3d4-65600fdfbb0e', 'Рядовка перевязанная', 'Рядовка опёнковидная', NULL, 'Рядовковые', false, 'Неизвестно', true, 20, 30, 'С юбкой', 'Грязно-белый, рыже-коричневый', 'Ровная', 'Рыжевато-бурый', 'Пластинчатая', 'Рядовка перевязанная встречается в сосновых лесах. Плодоносит в августе-октябре поодиночке или небольшими группами. Предпочитает зеленые мхи или песчаные почвы. Гриб можно употреблять в пищу, после предварительного отваривания в течение 20 минут. Отвар необходимо сливать.', '/media/mushrooms/placeholder.webp', NULL),
('ee7f7525-fc9a-5224-a1b3-c28972053306', 'Боровик розовокожий', 'Болет розовокожий', NULL, 'Болетовые', false, 'Неизвестно', true, 40, 60, 'Утолщенная в центре', 'Ярко-красный, жёлтый', 'Выпуклая', 'Коричнево-серый, грязно-желтый, красноватый', 'Трубчатая', 'Несмотря на то, что боровик розовокожий можно найти нечасто, известны случаи отравления именно этим грибом. Он ядовит как в сыром виде, так и после проведения тщательной обработки.', '/media/mushrooms/placeholder.webp', NULL),
('a1bfd72a-02b5-5ff0-ab2e-3ae99f111e62', 'Подберезовик болотный', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, сероватый', 'Выпуклая', 'Желтоватый, кремовый', 'Трубчатая', 'Встречается с начала мая до начала ноября (т.е до устойчивых морозов) в сырых березовых и смешанных (с березой) лесах, на березовых болотах, одиночно, не часто. Съедобный гриб, третьей категории.', '/media/mushrooms/placeholder.webp', NULL),
('493c200f-9652-5406-ac07-e8aeb5237a42', 'Моховик древесный', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 15, 60, 'Ровная', 'Желтый, рыжеватый', 'Выпуклая', 'Красно-коричневый, желтоватый', 'Трубчатая', 'Моховик древесный растет на древесине – пнях, у основания стволов и на опилках горных пород, в июле-сентябре. В Европе и Северной Америке. в России не отмечен. Несъедобен.', '/media/mushrooms/placeholder.webp', NULL),
('76e82fff-aab6-558d-9482-1bc3bdf36c40', 'Псатирелла каштановая', 'Гомофрон каштановый', NULL, 'Псатирелловые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Белый', 'Ровная', 'Коричневый, розовато-коричневый, красновато-коричневый', 'Пластинчатая', 'Обитает с начала лета и до середины осени на древесине лиственных пород (в первую очередь береза, осина), на сухостое, а также у основания стволов живых и мертвых деревьев, пней. Хороший съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('84747ff5-3e7e-5640-91b2-15ec8746a7ee', 'Гебелома горчичная', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 5, 15, 'Утолщенная внизу', 'Белый, буроватый', 'Выпуклая', 'Кремовый, красновато-бурый', 'Пластинчатая', 'Гебелома горчичная встречается в природе очень часто. Растет летом и осенью в хвойных и лиственных лесах, чаще на опушках леса. Плодоносит и растет большими группами. Гебелома горчичная является токсичным и ядовитым.', '/media/mushrooms/placeholder.webp', NULL),
('7721ed4c-0c3b-5324-a9ba-0410fa705351', 'Паутинник браслетчатый', 'Паутинник красный', NULL, 'Паутинниковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Беловатый, красно-буроватый', 'Выпуклая', 'Оранжевый, красно-коричневый', 'Пластинчатая', 'Паутинник браслетчатый встречается с начала августа и до конца «теплой осени» в лесах различного типа (очевидно — на бедных кислах почвах, но не факт), образуя микоризу как с березой, так и, возможно, с сосной. Селится во влажных местах, по краям болот, на кочках, во мхах. С одной стороны, паутинник браслетчатый вроде бы съедобен. С другой — как и все прочие паутинники, съедобен весьма и весьма условно.', '/media/mushrooms/placeholder.webp', NULL),
('1f330002-180b-5eea-a527-a86619c915f2', 'Весёлка Хадриана', NULL, NULL, 'Весёлковые', false, 'Неизвестно', true, 30, 45, 'Утолщенная в центре', 'Белый, мучной', 'Выпуклая', 'Грязно-коричневатый, черный, коричневый', 'Гладкая', 'Встречается довольно редко. Произрастает в лиственных лесах или в садах, в основном растёт на песчаной почве. Редко встречаются группы грибов. Споры разбрасывает с июля до октября. Пока мякоть гриба не потемнела, его можно употреблять в пищу. Используется в основном в лекарственных целях.', '/media/mushrooms/placeholder.webp', NULL),
('5b804e73-31f0-51cd-a42e-87fe99fa4533', 'Рядовка обособленная', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Белый, зеленоватый, оливковый', 'Выпуклая', 'Бледно-зеленоватый, коричневатый', 'Пластинчатая', 'Встречается в хвойных и лиственных лесах. Предпочитает сырые и кислые почвы с некоторыми лиственными деревьями может образовывать микоризу. Время плодоношения – август — сентябрь.', '/media/mushrooms/placeholder.webp', NULL),
('09c66b10-4c25-5642-9eb2-a6b68d2dec30', 'Боровик Фехтнера', 'Болет Фехтнера, Болетус Фехтнера', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 60, 'Утолщенная внизу', 'Желтоватый, красно-бурый', 'Выпуклая', 'Серебристо-белый, бледно-буроватый', 'Трубчатая', 'Боровик Фехтнера встречается на известковой почве в широколиственных лесах. Растет на Кавказе и Дальнем Востоке, а также России. Сезон на это гриб, то есть период его плодоношения, длится с июня по сентябрь. Гриб съедобный. Можно употреблять в свежем, соленом виде, а также консервировать. Его относят к третьей категории вкусовых качеств.', '/media/mushrooms/placeholder.webp', NULL),
('a7305281-1fb6-591d-b745-f34d8c5ea26d', 'Обабок окрашенноногий', 'Гаррия окрашенноножковая, Подосиновик окрашенноногий, Березовик окрашенноножковый', NULL, 'Болетовые', false, 'Неизвестно', true, 15, 30, 'Утолщенная в центре', 'Белый, пурпурный, розовый', 'Выпуклая', 'Розовый, желтоватый', 'Трубчатая', 'Этот вид гриба североамериканско-азиатский. В России известен лишь в Восточной Сибири (Восточный Саян) и на Дальнем Востоке. Обабок окрашенноногий растет на почве под березой в сухих дубовых и дубово-сосновых лесах в июле-сентябре, нередко. Съедобный гриб (2 категории). Возможно использование в первых и вторых блюдах (отваривание около 10–15 минут). При обработке мякоть чернеет.', '/media/mushrooms/placeholder.webp', NULL),
('73a3218b-b3fc-5cb7-8686-c201e0b35fcd', 'Чешуйчатка огненная', NULL, NULL, 'Строфариевые', false, 'Неизвестно', true, 15, 30, 'Ровная', 'Огненно-желтый, оранжеватый', 'Выпуклая', 'Огненно-желтый, оранжеватый', 'Пластинчатая', 'Чешуйчатку Огненную можно найти летом и осенью, пик плодоношения приходится на вторую половину лета — начало осени. Встречается в хвойных лесах любого типа и в смешанных с хвойными: елью, сосной, пихтой, лиственницей. Растёт на мёртвой древесине хвойный пород, редко встречается на лиственных, по литературным данным, из лиственных предпочитает берёзу. Как правило, плодовые тела вырастают одиночно, небольшими скоплениями. Считается несъедобной из-за неприятного запаха и горького, неприятного вкуса. Данных о ядовитости нет.', '/media/mushrooms/placeholder.webp', NULL),
('7a78a938-628f-510b-893f-b38fd0edcb20', 'Сыроежка миндальная', 'Сыроежка лавровишневая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, коричневатый', 'Выпуклая', 'Бело-коричневатый, светло-оранжевый', 'Пластинчатая', 'Сыроежку лавровишневую можно встретить рассеянными ареалами, преимущественно летом и в осеннее время. Обитает чаще всего в лиственных и смешанных лесах, очено редко – в хвойных. Любит расти под дубами, буками. Обычно произрастает одиночно. Относится к съедобным грибам.', '/media/mushrooms/placeholder.webp', NULL),
('8c3be207-73fd-5da5-b205-a9dc42907f06', 'Млечник буроватый', 'Млечник тёмно-бурый, Млечник сажистый', NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 30, 'Ровная', 'Светло-бурый, грязно-беловатый', 'Выпуклая', 'Бурый, желтоватый, розоватый', 'Пластинчатая', 'Млечник буроватый появляется в июле, предпочитая широколиственные и березовые леса, и растет приблизительно до середины сентября. Млечник буроватый съедобен.', '/media/mushrooms/placeholder.webp', NULL),
('06ded3ce-cedf-5d0c-b530-29b0aa71ba14', 'Шампиньон Бернарда', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 15, 25, 'Утолщенная вверху', 'Белый, грязно-белый, розововатый, коричневатый', 'Выпуклая', 'Белый, грязно-белый, розововатый, коричневатый', 'Пластинчатая', 'Встречается в местах, где происходит засоление почвы: в прибрежных морских районах или вдоль дорог, посыпаемых зимой солью, плодоносит обычно большими группами. Также на газонах и травянистых участках, может образовывать «ведьмины круги».Сезон лето — осень. Гриб съедобен, но невысокого качества, нежелательно употреблять грибы, растущие в загрязнённых местах вдоль автодорог.', '/media/mushrooms/placeholder.webp', NULL),
('fa2842b9-8a55-5ecf-8c3c-11a1080a2d60', 'Мухомор королевский', NULL, NULL, 'Аманитовые', false, 'Неизвестно', true, 15, 35, 'Ровная', 'Беловатый, кремовый', 'Выпуклая', 'Охряно-коричневый, белый, желто-охряный', 'Пластинчатая', 'Мухомор королевский распространен с середины июля до поздней осени, до ноября, в хвойных еловых лесах и смешанных (с елью), на почве, одиночно и небольшими группами, редко, чаще встречается в более северных и западных регионах Мухомор королевский считается ядовитым грибом', '/media/mushrooms/placeholder.webp', NULL),
('3fc9e07a-4cf5-552e-807c-a3d4b89cb0bf', 'Рядовка серно-жёлтая', 'Рядовка серная', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Беловато-серно-желтый', 'Выпуклая', 'Ярко-серно-желтый', 'Пластинчатая', 'Рядовка серно-жёлтая растёт в лиственных и хвойных лесах на земле и на пнях в августе — сентябре. Гриб несъедобен из-за неприятного вкуса и запаха.', '/media/mushrooms/placeholder.webp', NULL),
('310d7884-7226-52c3-b494-395836660ff3', 'Опенок луковичноногий', 'Опёнок осенний', NULL, 'Физалакриевые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Серовато-бурый, желтоватый', 'Выпуклая', 'Коричневато-серый, беловато-желтый, желтовато-коричневый', 'Пластинчатая', 'Сапротроф на старом валеже, на погружённой в землю мёртвой и живой древесине, редко растёт как паразит на ослабленных деревьях. Произрастает на лиственных деревьях. Опенок луковичноногий растёт и на почве — либо на корнях, либо на перепревших остатках травы и листового опада. Встречается как в лесах под деревьями, так и на открытой местности: на полянах, опушках, лугах, парковых зонах. Плодоносит с конца лета и до поздней осени. Опенок луковичноногий — съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('ab983b2d-32e0-52f7-b296-08ac93fc7e8c', 'Шампиньон пёстрый', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 15, 'С юбкой', 'Белый, розоватый, коричневатый', 'Выпуклая', 'Дымчато-сероватый, коричневатый', 'Пластинчатая', 'Этот гриб встречается в степной и лесостепной Украине. Встречается в лесистых местностях, парках, на плодородной, чаще щелочной почве, плодоносит группами или кольцами на плодородной почве. Распространён в северной умеренной зоне, встречается относительно редко, местами. Ядовитый гриб. Интересно, что восприимчивость к нему людей различна. Некоторые могут употреблять в пищу небольшие количества его без вреда. В некоторых руководствах его ядовитость не отмечена.', '/media/mushrooms/placeholder.webp', NULL),
('06e28131-95e1-53eb-9669-c7139ab3a43e', 'Подольшаник', 'Гиродон сизоватый', NULL, 'Свинушковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Желтовато-коричневатый, грязно-розовый', 'Выпуклая', 'Желтовато-коричневатый, грязно-розовый', 'Трубчатая', 'Произрастает подольшаник в ольшаниках и образует микоризу с ольхой. Распространен он только в Европе. Встречается редко. Съедобен, но невысокой ценности.', '/media/mushrooms/placeholder.webp', NULL),
('172630f1-5cc4-59b5-adc3-4024e629c2de', 'Маслёнок кедровый плачущий', NULL, NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'Охряно-коричневый, желтоватый', 'Выпуклая', 'Коричневый, желто-коричневатый', 'Трубчатая', 'Произрастает в хвойных и кедровых рощах. Больше всего кедровых маслят в сухом бору и лишайниковом сосняке. Маслята охотнее плодятся среди мелких хвойных порослей и в новых посадках. Эти грибы довольно часто встречаются в Сибири и на Дальнем Востоке — с сибирским и корейским кедрами и с кедровым стлаником. Это наиболее часто встречающийся в Сибири вид масленка вообще. Растет в дубово-кедровых, кедрово-широколиственных, кедрово-еловых и пихтово-кедровых лесах под кедром корейским, в августе — сентябре. Наиболее обилен в лесах на южных склонах. Маслята собирают с лета до осени. Цветение сосны — верная примета — пора за масленком кедровым. Съедобен.', '/media/mushrooms/placeholder.webp', NULL),
('a17a1319-d9f2-5ccb-8cbd-ce3bfcc3191c', 'Сыроежка кроваво-красная', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Розовато-красный, белый, сероватый, желтоватый', 'Выпуклая', 'Кроваво-красный, тёмно-красный, красный, розово-красный, ярко-красный, карминно-красный, желтовато-красный, беловато-красноватый', 'Пластинчатая', 'Сыроежка кроваво-красная образует микоризу с соснами, особенно охотно — с 2-х игольчатыми соснами и, возможно, с другими хвойными. Растёт на почве или хвойной подстилке в лесах разного типа, где есть сосны. Растет как одиночно, так и довольно большими скоплениями, «полянами». Плодоносит с середины лета до поздней осени, в теплых регионах и зимой, пик плодоношения август — октябрь. В относительно старых справочниках Сыроежка кроваво-красная относилась к условно-съедобным грибам 4-й категории (съедобен после обязательного отваривания). Современные справочники довольно единодушно ставят метку «Несъедобен».', '/media/mushrooms/placeholder.webp', NULL),
('ec3d818c-e7dd-58f5-b52e-5623047df0b9', 'Лисичка желтеющая', NULL, NULL, 'Лисичковые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Желтый, оранжевый, рыжеватый', 'Выпуклая', 'Желто-коричневый, темно-коричневый', 'Пластинчатая', 'Распространен в августе и сентябре в хвойных, чаще еловых, лесах, группами, не часто. Считается съедобным грибом (4 категории), используется свежим (отваривание около 15-20 минут) и сушеным.', '/media/mushrooms/placeholder.webp', NULL),
('142af40a-73bf-593d-8ae3-5c7f18d94c7c', 'Подберезовик разноцветный', 'Обабок разноцветный', NULL, 'Болетовые', false, 'Неизвестно', true, 20, 30, 'Утолщенная внизу', 'Белый, сероватый, светло-коричневатый', 'Выпуклая', 'Белый, серый', 'Трубчатая', 'Подберезовик разноцветный плодоносит как и его обыкновенный собрат, с начала лета и до конца октября, образуя микоризу преимущественно с березой; встречается в основном в болотистой местности, во мхах. В наших краях относительно редок, увидишь его нечастно, а в южной России, судя по рассказам очевидцев, вполне обыкновенный гриб. Хороший съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('7fa15350-d753-5ddf-8cfe-66ef36585195', 'Белопаутинник луковичный', 'Белопаутинник клубненосный', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, сероватый', 'Выпуклая', 'Кремовый, грязно-оранжевый', 'Пластинчатая', 'Встречается с августа по октябрь в хвойных и смешанных лесах, образуя микоризу с сосной и елью. Считается съедобным грибом среднего качества.', '/media/mushrooms/placeholder.webp', NULL),
('be41d262-0c50-5667-be21-37364e2aac78', 'Хлорофиллум тёмно-бурый', 'Хлорофиллум коричневый, Зонтик тёмно-бурый, Зонтик коричневый', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 15, 25, 'С юбкой', 'Беловатый, тускло-коричневатый', 'Выпуклая', 'Тускло-серовато-коричневый, белый, коричневый, серо-коричневый', 'Пластинчатая', 'Сапрофит, растет одиночно, рассеянно или большими скоплениями на плодородной, хорошо унавоженной почве в садах, на пустырях, лужайках или в теплицах и оранжереях; иногда образует ведьмины кольца. Зонтик коричневый плодоносит летом и осенью, до холодов. Распространён в США в прибрежной Калифорнии, на западном побережье и в районе Денвера; редко встречается на северо-востоке Северной Америки. Данные о съедобности крайне противоречивы. Разные источники указывают Хлорофиллум тёмно-бурый съедобным, условно-съедобным и «предположительно ядовитым». Может вызывать аллергические реакции. Есть упоминания о том, что в каких-то ранних источниках описывались даже некоторые галлюциногенные свойства.', '/media/mushrooms/placeholder.webp', NULL),
('83ae5679-f56f-5222-b9ed-12eb12e97467', 'Паутинник багряный', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 15, 25, 'Утолщенная внизу', 'Бурый, оливково-бурый, красновато-коричневый, голубоватый', 'Выпуклая', 'Бурый, оливково-бурый, красновато-коричневый, голубоватый', 'Пластинчатая', 'Активное плодоношение паутинника багряного приходится на осенний период. Гриб этого вида можно встретить в смешанных, лиственных или хвойных лесах, в основном, в конце августа и на протяжении сентября. Информация о том, съедобен ли паутинник багряный, является противоречивой. В одних источниках говорится, что данный вид грибов разрешено употреблять в пищу, в других же обозначено, что плодовые тела данного гриба не годятся для еды, поскольку обладают низкими вкусовыми качествами. Условно паутинник багряный можно назвать съедобным, в основном его употребляют в пищу солёным либо замаринованным. Пищевые свойства вида изучены мало.', '/media/mushrooms/placeholder.webp', NULL),
('a800fa4a-316d-5960-aa95-2338cc28030a', 'Ксерула корневая', 'Удемансиелла корневая, Коллибия хвостатая, Денежка корневая, Collybia radicata, Одимансиелла лучистая', NULL, 'Физалакриевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Коричневый, беловатый', 'Выпуклая', 'Оливковый, серовато-коричневый, грязно-желтый', 'Пластинчатая', 'Ксерула корневая встречается с середины до конца июля. Иногда попадается до конца сентября в различных лесах. Предпочитает корни деревьев и сильно перегнившие древесные останки. За счет длинной ножки, гриб формируется глубоко под землей и на поверхность вылезает лишь частично. В принципе, гриб Ксерула корневая считается съедобным. Некоторые источники утверждают, что в грибе содержаться некоторые целебные вещества. Этот гриб можно смело употреблять в пищу.', '/media/mushrooms/placeholder.webp', NULL),
('eede5e41-127b-5227-b0f0-e639bdca1534', 'Маслёнок серый', 'Масленок лиственничный серый, Масленок синеющий, Лиственник серый трубчатый', NULL, 'Маслёнковые', false, 'Неизвестно', true, 15, 30, 'С юбкой', 'Грязно-жетлый, коричневатый', 'Выпуклая', 'Коричневатый, светло-серый, зеленоватый, фиолетовый', 'Трубчатая', 'Маслёнок серый растёт в молодых сосновых и лиственничных лесах, часто большими группами. Съедобный гриб, третьей категории. Собирают в июле — сентябре. Употребляют свежим и маринованным.', '/media/mushrooms/placeholder.webp', NULL),
('80bc51cf-bc78-5dd2-9e42-07e70d1a6da8', 'Паутинник обыкновенный', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 20, 'С юбкой', 'Беловатый, светло-фиолетовый, буроватый, желто-коричневый, бурый', 'Выпуклая', 'Бледно-желтый, бледно-охряный, оливковый, медово-коричневатый, желтовато-коричневатый, красновато-коричневый', 'Пластинчатая', 'Растет с середины июля до середины сентября в лиственных, смешанных (с березой, осиной, ольхой), реже в хвойных лесах, в достаточно влажных местах, одиночно или небольшими группами, не часто. Считается несъедобным грибом, пищевые свойства не изучены', '/media/mushrooms/placeholder.webp', NULL),
('3fbc3486-1ca4-5944-a49a-cafd6dc4221c', 'Гиропорус песчаный', 'Песочник', NULL, 'Гиропоровые', false, 'Неизвестно', true, 15, 45, 'Утолщенная внизу', 'Белый, кремовый, оранжеватый, коричневато-рыжий, розоватый', 'Выпуклая', 'Желтовато-коричневый, розовый', 'Трубчатая', 'Растёт в хвойных лесах, в песчаных прибрежных районах или дюнах. Предпочитает известняковые почвы. Осенний гриб, который появляется в изолированных или разбросанных группах. Токсичный гриб, вызывает симптомы острых и продолжительных желудочно-кишечных беспорядков.', '/media/mushrooms/placeholder.webp', NULL),
('39d26323-d2f4-5ea8-b653-cb69e29f4939', 'Ежовик красновато-желтый', 'Ежовик рыжеющий', NULL, 'Ежовиковые', false, 'Неизвестно', true, 20, 40, 'Ровная', 'Рыжеватый, белый', 'Выпуклая', 'Красновато-рыжий', 'Шипастая', 'Произрастает преимущественно небольшими группами в лесах смешанного типа. Иногда встречается во мху или в невысокой траве. Гриб является съедобным и применяется в употреблении преимущественно в молодом возрасте.', '/media/mushrooms/placeholder.webp', NULL),
('5d57d19d-9015-5d04-a559-f687a025c80c', 'Рядовка лиственная', 'Зеленушка осиновая, Рядовка осиновая', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'Палево-желтый, зеленовато-желтый, серно-желтый', 'Выпуклая', 'Зеленовато-желтый, оливково-желтый, серно-желтый, желто-бурый, красновато-бурый, зеленовато-коричневый', 'Пластинчатая', 'Рядовка лиственная растет с августа по сентябрь, редко в октябре, образует микоризу с осиной. По неподтвержденным данным может расти и с березами. Рядовка лиственная считается условно-съедобным грибом. Однако, по некоторым исследованиям, в сходной ей зеленушке обнаружены ядовитые вещества, разрушающие мышечную ткань, соответственно, и этот вид, как близкий ей, может содержать их же, что, на данный момент не доказано.', '/media/mushrooms/placeholder.webp', NULL),
('884c9de8-cf6d-5a85-9425-0db485c801e5', 'Вольвариелла слизистоголовая', 'Вольвариелла слизистая, Вольвариелла прекрасная, Вольвариелла вязкошляпковая, Вольвариелла красивая', NULL, 'Плютеевые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'Белый, серо-желтый', 'Выпуклая', 'Беловатый, серовато-беловатый, серовато-бурый, серо-коричневый', 'Пластинчатая', 'Встречается с начала июля до конца сентября, в основном — на нарушенных перегнойных почвах, например, на жнивье, мусорных, навозных и компостных кучах, а также на огородных грядках, свалках, в основаниях стогов сена. Редко этот гриб встречается в лесу. Сами грибы появляются одиночно или встречаются небольшими группами Вольвариелла слизистоголовая является малоценным съедобным или условно-съедобным грибом среднего качества.', '/media/mushrooms/placeholder.webp', NULL),
('2faaf807-0a66-5002-908c-50facc1a41e4', 'Сыроежка дикая', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, желтеющий', 'Выпуклая', 'Розово-красный, розовый, желтоватый, желто-охристый, беловатый', 'Пластинчатая', 'Обильно растет в любых хвойных и лиственных лесах, на опушках и под отдельными деревьями на открытом ландшафте, особенно под дубами, каштанами и — реже — под соснами, часто во мхах, предпочитает кремнистые и более кислые почвы. Встречается под дубами и в очень сухих местах степного характера. Плодоносит с сентября по ноябрь. Сыроежка дикая относится к ядовитым грибам. Употребление в пищу даже небольшого количества может вызвать сильное расстройство желудочно-кишечного тракта. Ядовиты и шляпка, и ножка. Нет данных, разлагается ли яд при отваривании.', '/media/mushrooms/placeholder.webp', NULL),
('bd05cce1-6792-5b31-92f2-94cf96f96b70', 'Моховик полузолотистый', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 20, 35, 'Утолщенная внизу', 'Желтоватый, рыжеватый, серно-желтый, оранжевый', 'Выпуклая', 'Желтоватый, рыжеватый, серно-желтый', 'Трубчатая', 'Известен в Европе и Северной Америке, в Украине (Полтавская область), в России — на Кавказе и Дальнем Востоке. Всюду очень редок. Гриб является условно-съедобным.', '/media/mushrooms/placeholder.webp', NULL),
('904f5d95-38c5-500f-b883-f8540914c977', 'Паутинник сизо-голубой', 'Паутинник голубеющий, Паутинник голубой, Паутинник водянисто-голубой, Паутинник синеватый', NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 25, 'Утолщенная внизу', 'Охристо-жёлтый, голубовато-фиолетовый', 'Выпуклая', 'Сероватый, голубой, светловато-охристый', 'Пластинчатая', 'Гриб произрастает большими группами и колониями, встречается в смешанных и широколиственных лесах, является микоризообразователем со многими лиственными деревьями, в том числе – с буком. На территории России встречается только в Приморском крае. Образует микоризу с различными лиственными деревьями (в том числе – с дубами и буками). Несмотря на то, что гриб принадлежит к категории редких, и увидеть его можно нечасто, его причисляют к категории съедобных.', '/media/mushrooms/placeholder.webp', NULL),
('33e9a84e-cc2b-5cad-9f10-b5d71778fdea', 'Гигроцибе алая', 'Гигроцибе красная, Гигроцибе багряная', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Ярко-красный, желтовытый', 'Выпуклая', 'Насыщенно-алый, блекло-оранжевый, оранжево-желтый', 'Пластинчатая', 'Гигроцибе алая встречается на всякого рода лугах с конца лета и до поздней осени, предпочитая, очевидно, неплодородные почвы, где гигрофоровые традиционно не встречают серьезной конкуренции. Гигроцибе алая гриб не ядовитый, но в качестве съедобного гриба не употребляется даже опытными грибниками, так как встречается он не часто и отличается маленькими размерами.', '/media/mushrooms/placeholder.webp', NULL),
('29756438-0abf-598f-a116-81c34838a44d', 'Млечник блёклый', 'Болотная волнушка', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Светло-коричневый, кремовый', 'Ровная', 'Винно-бурый, коричневатый', 'Пластинчатая', 'Растет в лиственных и смешанных лесах, формируют микоризу с берёзовой древесиной. Массовое плодоношение гриба продолжается на протяжении всего сентября, а первый урожай млечника блеклого можно собрать уже в середине августа. Растёт в смешанных и лиственных лесах, где есть берёзы и сосны. Предпочитает болотистые местности, с высоким уровнем влажности и мшистыми участками. Млечник блеклый принадлежит к категории условно-съедобных грибов, употребляется в пищу, в основном, солёным.', '/media/mushrooms/placeholder.webp', NULL),
('daa0943d-1992-5010-9a48-0fd67287f5a0', 'Сыроежка охристая', 'Сыроежка бледно-охристая, Сыроежка бледно-желтая, Сыроежка лимонная, Сыроежка охристо-желтая, Сыроежка охристо-белая, Сыроежка охряно-желтая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Белый, желтый', 'Ровная', 'Желтовато-охряный', 'Пластинчатая', 'Сыроежка охристая обитает в наших лесах с конца августа до октября. Излюбленные леса – хвойные, особенно еловые и широколиственные с достаточным уровнем увлажнения. Растет на мхах, на лесных постилках. В южных районах страны встречается довольно редко. Гриб относится к съедобным, категория – третья. Некоторые исследователи относят такой гриб у условно-съедобным и даже несъедобным. Перед употреблением в пищу его необходимо отварить.', '/media/mushrooms/placeholder.webp', NULL),
('2700553d-0c5b-5e64-9738-693200ddb10e', 'Шампиньон кривой', 'Шампиньон отчетливоклубеньковый', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 20, 'С юбкой', 'Белый, кремоватый, сероватый', 'Выпуклая', 'Белый, кремовый, светло-охряный', 'Пластинчатая', 'Произрастает в хвойных лесах с середины лета до октября. Он любит расти на лесной подстилке, часто встречается группами, но иногда можно найти и одиночные экземпляры. Это съедобный вкусный гриб, по вкусу он ничем не уступает шампиньону полевому и используется точно так же (в первых и вторых блюдах, вареным, маринованным или соленым).', '/media/mushrooms/placeholder.webp', NULL),
('0e2d692c-731a-5cf8-bbf7-2f63bbe6a4e0', 'Мухомор толстый', 'Мухомор коренастый', NULL, 'Аманитовые', false, 'Неизвестно', true, 15, 25, 'С юбкой', 'Беловатый, серо-коричневатый', 'Выпуклая', 'Серо-коричневый, серебристо-серый', 'Пластинчатая', 'Летом и осенью встречается в лиственных и хвойных лесах. Гриб очень распространен. Несъедобен.', '/media/mushrooms/placeholder.webp', NULL),
('9b46b9ff-2c6d-595b-88d6-84030ea2f8ab', 'Подосиновик сосновый', NULL, NULL, 'Болетовые', false, 'Неизвестно', true, 20, 45, 'Утолщенная внизу', 'Грязно-белый, коричневатый', 'Выпуклая', 'Красно-бурый, оранжево-кирпичный', 'Трубчатая', 'Подосиновик сосновый встречается с июня до начала октября в хвойных и смешанных лесах, образуя микоризу строго с сосной. Особенно обильно плодоносит во мхах. Хороший съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('fa08bb31-d2b5-5d78-8fff-38f1f3e27d0d', 'Паутинник многообразный', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'Белый, оранжеватый, желтоватый', 'Выпуклая', 'Рыжий, красноватый, желтоватый', 'Пластинчатая', 'Гриб достаточно широко распространен в российских лесах европейской части страны, в лесах Белоруссии. Излюбленным местом распространения считаются именно хвойные леса, хотя гриб попадается и в густых лиственных лесах. Паутинник многообразный относится к условно-съедобным грибам. Может быть использован в пищу после получаса отваривания в кипящей воде.', '/media/mushrooms/placeholder.webp', NULL),
('66b03e89-f0a6-598d-bd41-9c5ec85000ce', 'Меланолеука прямоногая', 'Меланолейка прямоногая', NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Грязно-белый, мучной', 'Ровная', 'Беловатый, кремовый', 'Пластинчатая', 'Плодоношение у гриба описываемого вида достаточно обильное, продолжается с июня по октябрь. Меланолейки прямоногие произрастают преимущественно на лугах, в садах и на пастбищах. Лишь изредка этот вид грибов можно увидеть в лесу. Чаще всего меланолейки вырастают в горных областях и предгорьях. Меланолейка прямоногая является съедобным грибом.', '/media/mushrooms/placeholder.webp', NULL),
('7f24d3c3-ce32-5d5e-9904-eaf61e447f72', 'Рядовка бородатая', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Беловатый, коричневатый', 'Выпуклая', 'Красно-коричневый, светло-коричневый', 'Пластинчатая', 'Рядовка бородатая достаточно широко распространена в Северном полушарии. Образует микоризу с хвойными, чаще всего с елью, реже с сосной. Встречается с августа по ноябрь. Гриб не ядовит, но и высокими гастрономическими качествами не обладает. По некоторым источникам, он годится в засолку вместе с другими грибами после предварительного отваривания.', '/media/mushrooms/placeholder.webp', NULL),
('f100cca8-e0ec-5bc7-8ff0-d26df11db4b2', 'Лисичка аметистовая', NULL, NULL, 'Лисичковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная вверху', 'Светло-жёлтый, рыжеватый', 'Вогнутая', 'Светло-жёлтый, рыжеватый, коричневатый', 'Пластинчатая', 'Лисичка аметистовая начинает плодоносить в начале лета (июнь) а завершение периода плодоношения приходится на октябрь. Гриб распространён в лесистых местностях России, в основном лисичку аметистовую можно увидеть в хвойных, лиственных, травянистых, смешанных лесах. Аметистовая лисичка принадлежит к категории съедобных грибов, с прекрасными вкусовыми качествами. Гриб не предъявляет особых требований к транспортировке, хорошо сохраняется.', '/media/mushrooms/placeholder.webp', NULL),
('78deffc6-c996-5a45-be8c-86001bd8b477', 'Паутинник слизистый', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, мучной', 'Выпуклая', 'Глинисто-желтый, темно-коричневый', 'Пластинчатая', 'Паутинник слизистый встречается с середины августа до конца октября в хвойных и смешанных лесах, образует микоризу, видимо, с сосной. Попадается нечасто, больших групп не образует. В зарубежной литературе гриб описывается как несъедобный.', '/media/mushrooms/placeholder.webp', NULL),
('5a462721-d9ce-50ea-a3eb-884b2b320de4', 'Масленок желтоватый', NULL, NULL, 'Маслёнковые', false, 'Неизвестно', true, 15, 30, 'С юбкой', 'Беловатый, желтоватый', 'Ровная', 'Желтоватый, желтовато-коричневый, серо-желтый, охристо-желтоватый', 'Трубчатая', 'Масленок желтоватый любит тепло, поэтому встречается преимущественно на почвах песчаного типа. Легче всего найти этот гриб в сосновом лесу или в посадке этих деревьев, если им свойственен хороший уровень прогревания.Расти грибы этого вида могут как одиночными экземплярами, так и большими группами. Период их плодоношения начинается в конце мая и длится до конца ноября. Масленой желтоватый – условно съедобный, так как для употребления его в пищу необходимо снять с его поверхности кожицу, которая способствует возникновению диареи.', '/media/mushrooms/placeholder.webp', NULL),
('0a0d61d9-626d-5429-a065-dd9d636943da', 'Лаковица аметистовая', 'Лаковица лиловая', NULL, 'Гиднангиевые', false, 'Неизвестно', true, 2, 5, 'Ровная', 'Лиловый, фиолетовый, беловатый', 'Ровная', 'Лиловый, фиолетовый, беловатый', 'Пластинчатая', 'Лаковица аметистовая произрастает на влажный почвах в лесном поясе, время роста – летний и осенний период. Гриб относится к условно-съедобным, вполне пригоден для употребления в пищу, при этом его обычно добавляют в различные блюда в сочетании с другими грибами.', '/media/mushrooms/placeholder.webp', NULL),
('d0d8a45b-b1d1-54bf-9756-db1bed420bdd', 'Подосиновик желто-бурый', 'Обабок разнокожий, Подосиновик красно-бурый', NULL, 'Болетовые', false, 'Неизвестно', true, 25, 50, 'Утолщенная внизу', 'Зеленоватый, серо-черный, грязно-беловатый', 'Выпуклая', 'Рыжеватый, желтовато-серый, красноватый', 'Трубчатая', 'Подосиновик желто-бурый растет с июня по октябрь в лиственных и смешанных лесах, образуя микоризу преимущественно с березой. В молодых лесах может встречаться в баснословных количествах, особенно в начале сентября. Отличный съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('57ca7977-d0a8-5559-aa28-90c22f344db0', 'Пилолистник тигровый', NULL, NULL, 'Полипоровые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Коричневатый, мучной', 'Выпуклая', 'Желтоватый, кремовый, коричневатый', 'Пластинчатая', 'Растёт довольно большими сростками и группами на валеже, пнях и стволах преимущественно лиственных пород: дуба, тополя, ивы, на фруктовых деревьях. Сезон - лето-осень, с конца июля по сентябрь (для средней полосы России). В южных регионах — с апреля. В разных источниках гриб указывается как съедобный, но с разной степенью съедобности. О вкусовых качествах сведения тоже весьма противоречивы.', '/media/mushrooms/placeholder.webp', NULL),
('c32bf6e8-eb1a-54be-ab56-f375bebe6d92', 'Сетконоска сдвоенная', 'Диктиофора сдвоенная', NULL, 'Весёлковые', true, 'Неизвестно', true, 5, 15, 'Ровная', 'Белый', 'Выпуклая', 'Оливково-зеленый, коричневатый', 'Гладкая', 'Обитает сетконоска сдвоенная в лиственных лесах на почве, богатой гумусом, или на сильно разложившихся остатках древесины. Встречается исключительно редко, одиночно или группами, в июле — сентябре. Молодые грибы съедобны; кроме того, диктиофора сдвоенная используется в народной медицине против подагры и ревматизма.', '/media/mushrooms/placeholder.webp', NULL),
('a3267038-e48d-5b5b-b2c8-e45c3aad94dd', 'Трутовик клубненосный', NULL, NULL, 'Полипоровые', false, 'Неизвестно', true, 10, 20, 'Утолщенная вверху', 'Грязно-белый, рыжевато-бурый', 'Ровная', 'Рыжевато-желтый, коричневый', 'Трубчатая', 'Встречается Клубненосный Трутовик с конца весны в течение всего летнего периода и примерно до середины сентября. Произрастает на останках деревьев лиственных пород. Предпочитает липу и прочие схожие породы. Трутовик клубненосный считается условно-съедобным грибом', '/media/mushrooms/placeholder.webp', NULL),
('85bea805-4d02-5444-9211-5657fad65e5e', 'Пилолистник бокаловидный', 'Лентинус бокаловидный', NULL, 'Полипоровые', false, 'Неизвестно', true, 10, 25, 'Утолщенная вверху', 'Беловатый, коричневатый', 'Вогнутая', 'Рыжевато-бежевый, коричневатый', 'Пластинчатая', 'Пилолистник бокаловидный встречается на гниющих останках лиственных деревьев (по всей видимости, может паразитировать и на живых, вызывая белую гниль). Пилолистник бокаловидный — гриб преимущественно южный. Наиболее распространена информация, что пилолистник бокаловидный несъедобен из-за слишком плотной мякоти.', '/media/mushrooms/placeholder.webp', NULL),
('44e68e14-4624-57c3-bd1e-0f78931d626b', 'Маслёнок рубиновый', 'Перечный гриб рубиновый, Рубиноболет рубиновый', NULL, 'Болетовые', false, 'Неизвестно', true, 25, 45, 'Утолщенная внизу', 'Розоватый, красноватый', 'Выпуклая', 'Кирпично-красный, жёлто-бурый', 'Трубчатая', 'Произрастает в дубовых лесах, встречается очень редко. Известен в Европе. Съедобный гриб второй категории.', '/media/mushrooms/placeholder.webp', NULL),
('45369583-a39f-569e-aacb-14e55df3c437', 'Маслёнок белый', NULL, NULL, 'Маслёнковые', false, 'Неизвестно', true, 7, 20, 'Ровная', 'Беловатый, бурый', 'Выпуклая', 'Беловатый, бледно-жёлтый, серовато-белый, желтовато-белый, тускло-оливковый', 'Трубчатая', 'Съедобный, но незначительный гриб. Пригоден в пищу в свежем, маринованном и солёном виде.', '/media/mushrooms/placeholder.webp', NULL),
('fe72014c-f308-5044-a7f3-186c2c78b1c3', 'Паутинник пасынковидный', 'Паутинник клубненогий', NULL, 'Паутинниковые', false, 'Неизвестно', true, 5, 15, 'Утолщенная внизу', 'Беловатый, коричневатый', 'Ровная', 'Медно-оранжевый, оранжево-коричневый', 'Пластинчатая', 'Паутинник пасынковидный (он же клубненогий) (Cortinarius Privignoides) образует микоризу с деревьями хвойных пород. Произрастает на опавшей хвое и перегнивших ветках деревьев, а также – на земле. Иногда может расти и в лиственных лесах, под берёзами. Гриб считается ядовитым. Запах плодового тела не различим.', '/media/mushrooms/placeholder.webp', NULL),
('7533090b-3a2b-5d08-923d-db7595eaf56e', 'Опёнок чеканный', NULL, NULL, 'Физалакриевые', true, 'Неизвестно', true, 5, 10, 'Ровная', 'Коричневый, розоватый', 'Ровная', 'Коричневый, розоватый', 'Пластинчатая', 'Растет или одиночно, или небольшими группами. При этом предпочитает не пни или обычную лесную подстилку, а болотистые почвы или влажные сфагновые мхи. Сезон – август – конец сентября. Не съедобен.', '/media/mushrooms/placeholder.webp', NULL),
('d29a9c6a-c3a7-58c2-bce6-5137729a588a', 'Плютей благородный', 'Плютей широкошляпковый', NULL, 'Плютеевые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'Белый, сероватый, кремоватый', 'Ровная', 'Грязно-белый, коричневатый, розоватый', 'Пластинчатая', 'Данный гриб чаще всего произрастает на пнях и под различными лиственными деревьями. Излюбленным местом для роста считается влажная тенистая почва. Плютей может расти как поодиночке, так и небольшими скученными группами. Встречается как в равнинных, так и в горных лесах. Гриб является съедобным и используется в приготовлении первых и вторых блюд. Он обладает достаточно интересным своеобразным ароматом и приятным вкусом.', '/media/mushrooms/placeholder.webp', NULL),
('086bdc21-8ca5-5e4e-979d-e1a6a0f22c8a', 'Рядовка опаленная', 'Рядовка обожжённая, Рядовка загорелая', NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Беловатый, мучной, буроватый', 'Выпуклая', 'Каштаново-бурый', 'Пластинчатая', 'Опалённые рядовки широко распространены. Встретить их можно в лесах смешанного типа, преимущественно осенью. Гриб этого вида встречается на территории стран Европы, Азии, Северной Америки. Точных сведений о съедобности рядовки загорелой нет. Многие опытные грибники считают, что данный гриб является ядовитым и непригоден для употребления в пищу.', '/media/mushrooms/placeholder.webp', NULL),
('99a16eb6-2fb4-54e4-a53d-7aa26eb6edaa', 'Строфария небесно-синяя', NULL, NULL, 'Строфариевые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Матово-голубой, зеленоватый', 'Выпуклая', 'Матово-голубой, зеленоватый', 'Пластинчатая', 'Строфария данного типа растет или поодиночке, или небольшими группами. Любит расти в парках, вдоль дорог, на пастбищах, предпочитая гниющие травяные подстилки, влажные почвы, богатые гумусом. Строфарию небесно-синюю можно увидеть с июня по начало ноября (зависит от погоды). Относится к категории съедобных грибов, но знатоками не ценится, в пищу не употребляется.', '/media/mushrooms/placeholder.webp', NULL),
('97265718-8fb6-5e23-b73e-77ddf94f72b6', 'Шампиньон таблитчатый', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 30, 'С юбкой', 'Белый, беловатый', 'Выпуклая', 'Беловатый, беловато-серый', 'Пластинчатая', 'Шампиньон таблитчатый (Agaricus tabularis) очень редко встречается в пустынях и полупустынях Казахстана, Средней Азии, в целинных степях Украины, а также в Северной Америке. Относится к съедобным грибам.', '/media/mushrooms/placeholder.webp', NULL),
('5fd38f82-f333-57e0-b578-8f52ae10782d', 'Краснушка', 'Млечник сладковатый, Груздь сладкий', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Кремовый, беловатый, коричневатый', 'Ровная', 'Бледно-рыжеватый, светло-коричневый', 'Пластинчатая', 'Данный гриб легко можно найти в разных лесах, если обратить внимание на залежи мха. Собирать их лучше всего с середины лета, до середины осени. Гриб считается съедобным, однако для употребления в пищу его нужно варить или же солить, чтобы он не навредил здоровью. Ни в коем случае нельзя употреблять в пищу сырым.', '/media/mushrooms/placeholder.webp', NULL),
('2bd00f20-352a-5ca8-9c21-3066e729d700', 'Шампиньон крупноспоровый', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 10, 25, 'С юбкой', 'Беловатый', 'Выпуклая', 'Белый, мучной', 'Пластинчатая', 'В мире распространен довольно широко. Съедобен, обладает хорошими вкусовыми качествами.', '/media/mushrooms/placeholder.webp', NULL),
('3f74dbd4-dd51-5994-ad79-6b46b56f970a', 'Сыроежка ломкая', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый', 'Вогнутая', 'Розово-фиолетовый, бледно-розовый', 'Пластинчатая', 'Встречается часто на кислых почвах в лиственных, смешанных и хвойных лесах под березами, соснами, дубами, грабами и др. Встречается сыроежка ломкая в хвойных и лиственных лесах с августа по октябрь, реже с июня. Гриб условно-съедобен, четвертой категории. Употребляется только соленым.', '/media/mushrooms/placeholder.webp', NULL),
('32f49432-74fd-50ac-9935-d529fbddb896', 'Псевдоежовик студенистый', 'Псевдохидиум желатиновый, Ледяной гриб, Ложноежовик, Псевдоежовик, Псевдогиднум', NULL, 'Эксидиевые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Ровная', 'Беловато-серый, коричневатый', 'Гладкая', 'Встречается Псевдоежовик студенистый не часто. Плодоносит с конца лета и до первых холодов. Произрастает в лесах различного типа, предпочитает остатки лиственных, но чаще хвойных деревьев. Все доступные источники описывают Псевдоежовик студенистый как гриб, пригодный в употребление, правда, при этом его называют совершенно бесполезным с кулинарной точки зрения.', '/media/mushrooms/placeholder.webp', NULL),
('0200d2b7-f834-5102-a718-453d62d3bcdc', 'Поплавок желто-коричневый', 'Мухомор оранжевый, Мухомор желто-коричневый, Поплавок бурый, Поплавок оранжевый', NULL, 'Аманитовые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Бело-коричневый', 'Выпуклая', 'Золотистый, оранжевый, коричневый', 'Пластинчатая', 'Растет небольшими группами, также часто встречаются одиночные экземпляры. Любит заболоченные местности, кислые почвы. Предпочитает хвойники, в лиственных лесах встречается редко. Растет с июля по конец октября. Относится к съедобной категории (условно-съедобен), но употребляется только в отваренном виде.', '/media/mushrooms/placeholder.webp', NULL),
('615379ee-5e96-5e56-9075-9cd6a4eac799', 'Гигрофор сыроежковый', 'Гигрофор сыроежковидный, Вишняк', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 15, 35, 'Утолщенная внизу', 'Белый, красноватый', 'Выпуклая', 'Розоватый, темно-розовый, фиолетовый, беловатый', 'Пластинчатая', 'Встречается в лиственных лесах, в особенности под дубами, порой малыми группами. В гористых и холмистых местностях. Сезон - лето-осень. Съедобен.', '/media/mushrooms/placeholder.webp', NULL),
('1e229410-2793-5f91-bed7-6a80cfbe668e', 'Коллибия веретеноногая', 'Денежка веретеноногая', NULL, 'Омфалотовые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Красно-коричневый', 'Выпуклая', 'Красно-коричневый', 'Пластинчатая', 'Растёт на пнях, стволах и корнях старых лиственных деревьев, часто на дубах, буках, каштанах. Распространён в лиственных лесах. Плодоносит большими сростками.', '/media/mushrooms/placeholder.webp', NULL),
('dc0f6366-d495-5b3c-aac9-424900498c89', 'Чешуйчатка съедобная', 'Фолиота намеко, опёнок намеко', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Оранжево-коричневый, светло-оранжевый', 'Выпуклая', 'Оранжево-коричневый', 'Гладкая', 'Выращивается в искусственных условиях в больших объёмах. Предпочитает расти в условиях, где влажность воздуха – высокая (90-95%). Широко применяется в японской кухне.', '/media/mushrooms/placeholder.webp', NULL),
('16836205-93ed-517e-b0af-9a834d4040d1', 'Меланогастер Брума', 'Ложный трюфель', NULL, 'Свинушковые', true, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Жёлто-коричневый, коричневый, тёмно-коричневый', 'Гладкая', 'Растет в лиственных лесах, неглубоко в почве под слоем опавших листьев.', '/media/mushrooms/placeholder.webp', NULL),
('06ac5a3f-4fee-5f13-a5a2-a2243950a8a4', 'Ежовик усиковый', 'Креолофус усиковый, гериций кудрявый, ежовик разнозубчиковый', NULL, 'Герициевые', false, 'Неизвестно', false, NULL, NULL, NULL, NULL, 'Выпуклая', 'Бело-кремовый', 'Шипастая', 'Представляет собой мясистые, слоистые плодовые тела, , которые растут ярусами. Верхняя часть войлочная, нижнюю поверхность покрывают многочисленные длинные висячие шипы. Широко используется в медицине для лечения различных желудочных заболеваний и для профилактики рака желудочно–кишечного тракта. Встречается в смешанных лесах на стволах деревьев и пнях.', '/media/mushrooms/placeholder.webp', NULL),
('54d8a206-cf83-5d40-887a-fbf80402c264', 'Рогатик язычковый', 'Клавариадельфус язычковый', NULL, 'Клавариадельфовые', false, 'Неизвестно', true, 10, 30, 'Утолщенная вверху', 'Нежно-кремовый', 'Выпуклая', 'Нежно-кремовый', 'Гладкая', 'Вертикальное, языковидной формы плодовое тело, часто слегка сплющенное. Рогатик язычковый встречается с середины июля по конец сентября в хвойных или смешанных лесах, во мхах, возможно, образуя с ними микоризу. Попадается нечасто, но большими группами.', '/media/mushrooms/placeholder.webp', NULL),
('6105cef8-5679-545d-b6ef-5ec5f311e815', 'Хлорофиллум Оливье', 'Зонтик Оливье', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 12, 16, 'Утолщенная внизу', 'Беловатый', 'Выпуклая', 'Темно-красно-коричневый, бледно-коричневый', 'Пластинчатая', 'На ножке присутствует кольцо. У кольца два бахромчатых края, одна бахрома смотрит вверх, вторая — вниз. Гриб широко распространён в европейский странах. Плодовые тела встречаются как одиночно, разбросанно, так и образуют довольно большие скопления. Растёт как в хвойных, так и в лиственных лесах разного типа и кустарниках всех видов.', '/media/mushrooms/placeholder.webp', NULL),
('b174ec33-a2c2-559a-aa2a-2215ff477591', 'Моховик тупоспоровый', 'Моховик розовоногий, боровик тупоспоровый', NULL, 'Болетовые', false, 'Неизвестно', true, 10, 30, 'Утолщенная внизу', 'Красновато-жёлтый', 'Выпуклая', 'Коричневый', 'Трубчатая', 'Отмечен в Европе и Северной Америке; в пределах бывшего СССР отмечается в европейской части (ряд областей Украины, Саратовская область) и на Северном Кавказе.', '/media/mushrooms/placeholder.webp', NULL),
('954706e1-0167-583e-84a7-2c011a9f92a2', 'Навозник рассеянный', 'Навозник распространённый', NULL, 'Псатирелловые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Бело-сероватый', 'Выпуклая', 'Светло-кремовый, серый', 'Пластинчатая', 'Навозник рассеянный встречается с конца весны до середины осени на гниющей древесине, обычно большими колониями, равномерно покрывая удивительную площадь. По отдельности либо вообще не растет, либо никем не замечен.', '/media/mushrooms/placeholder.webp', NULL),
('afdeb95c-99af-56e6-95f0-4690266a6d8a', 'Моховик лиственничный', 'Болетин лиственничный', NULL, 'Маслёнковые', false, 'Неизвестно', true, 20, 40, 'Утолщенная внизу', 'Коричневатый, буроватый, темно-бурый', 'Выпуклая', 'Буроватый, охристо-бурый, грязно-бурый.', 'Трубчатая', 'Растёт только в присутствии лиственницы: в лиственничниках и смешанных лесах с присутствием берёзы, осины, под лиственницей.', '/media/mushrooms/placeholder.webp', NULL),
('724e763b-9b21-520d-8b5b-635ebaaa814e', 'Псатирелла водолюбивая', 'Псатирелла шаровидная, ложноопёнок водянистый, псатирелла гидрофильная', NULL, 'Псатирелловые', false, 'Неизвестно', true, 5, 8, 'Ровная', 'Беловатый, светло-коричневый', 'Выпуклая', 'Шоколадный, кремовый', 'Пластинчатая', 'Произрастает на пнях в лиственных или хвойных лесах, а так же вокруг пней и на сырых почвах. Растет большими колониями, соединяясь в пучки.', '/media/mushrooms/placeholder.webp', NULL),
('f78415a5-fdce-5729-b5bf-7320b1f6bfd0', 'Поплавок белый', NULL, NULL, 'Аманитовые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый', 'Выпуклая', 'Белый, грязно-белый', 'Пластинчатая', 'Растет в лиственных и смешанных лесах, на плодородных почвах. Образует микоризу с березой. Встречается не часто, отмечен во всей территории Европы, больше — в северных регионах.', '/media/mushrooms/placeholder.webp', NULL),
('05b171c1-a3bf-574e-9c0a-be992aaee24a', 'Мицена синеногая', NULL, NULL, 'Миценовые', true, 'Неизвестно', true, 1, 2, 'Ровная', 'Сероватый', 'Выпуклая', 'Светло-серый, серовато-коричневый', 'Пластинчатая', 'Растет в хвойных и смешанных влажных старовозрастных лесах, небольшими скоплениями, на коре, валеже и замшелой гнилой древесине хвойных. В России встречается в европейской части, на Среднем Урале, в Западной Сибири. Ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('5cdef5a9-9fc0-576d-b0a5-344f315cb4b1', 'Рядовка частопластинковая', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 8, 25, 'Утолщенная внизу', 'Белый, палево-желтоватый', 'Выпуклая', 'Белый, палевый, кремоватый', 'Пластинчатая', 'Ассоциирована с березой, предпочитает песчаные и торфяные почвы, однако встречается и на других видах почв, распространена повсеместно и очень широко, часто образует немаленькие скопления.', '/media/mushrooms/placeholder.webp', NULL),
('ad45738a-d04f-5bfa-8c45-57f3754547c5', 'Маслёнок полоножковый', 'Болетин полоножковый, решетник полоножковый', NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Оранжево-коричневый', 'Выпуклая', 'Ржаво-красный, желтый', 'Трубчатая', 'Встречается преимущественно в кедровых и лиственных лесах. Предпочитает почвы в горной или низинной местности.', '/media/mushrooms/placeholder.webp', NULL),
('951b81ea-e6e3-5f85-bf65-48357737da61', 'Гигрофор благоуханный', 'Гигрофор душистый', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Сероватый, серовато-бурый', 'Выпуклая', 'Сероватый, оливково-серый, желто-серый', 'Пластинчатая', 'Встречается в мшистых, сырых местах, в еловых лесах. Предпочитает горные местности. Отличается от других видов сильным миндальным запахом.', '/media/mushrooms/placeholder.webp', NULL),
('a21fc73f-e46e-5e66-9297-481da6e83da6', 'Гипомицес млечниковый', NULL, NULL, 'Гипокрейные', false, 'Неизвестно', true, 10, 30, 'Утолщенная вверху', 'Красно-оранжевый', 'Вогнутая', 'Красно-оранжевый', 'Пластинчатая', 'Является плесневым грибом, который растет на плодовых телах других грибов. Паразитирует на различных видах грибов, в частности, на сыроежках и млечниках. Распространен в основном в Северной Америке. Произрастает он после дождевой погоды.', '/media/mushrooms/placeholder.webp', NULL),
('cb197b45-00a7-5489-b1dd-93bc4f1e8be1', 'Порфировик порфироспоровый', 'Болет пурпуроспоровый, ежовик порфировый', NULL, 'Болетовые', false, 'Неизвестно', true, 10, 30, 'Утолщенная внизу', 'Сероватый, темно-коричневый', 'Выпуклая', 'Сероватый, темно-коричневый', 'Трубчатая', 'Встречается в южной части Альп, так же этот вид достаточно распространен в Центральной части Европы. Произрастает в хвойных и лиственных лесах, как правило, предпочитает горную местность.', '/media/mushrooms/placeholder.webp', NULL),
('6d03a29c-1202-5673-bdac-51142445ea3a', 'Гимнопил проникающий', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Коричнево-рыжеватый', 'Выпуклая', 'Коричнево-рыжеватый', 'Пластинчатая', 'Растет на останках хвойных деревьев, отдавая предпочтение сосне.', '/media/mushrooms/placeholder.webp', NULL),
('75ada04e-5ed8-5e53-86bf-686c0a9ff8e7', 'Галерина Болотная', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 2, 5, 'Ровная', 'Светло-желтый', 'Выпуклая', 'Медово-желтый, желтовато-бурый', 'Пластинчатая', 'Встречается в лесах различного типа, преимущественно на заболоченных участках, среди сфагнума.', '/media/mushrooms/placeholder.webp', NULL),
('6ab0e200-4ff3-5fa0-ad19-14efd1f8db77', 'Подгруздок бело-черный', 'Сыроежка бело-черная', NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Грязно-белый', 'Вогнутая', 'Грязно-бело-коричневый', 'Пластинчатая', 'Растет во многих лесах – хвойных, широколиственных.', '/media/mushrooms/placeholder.webp', NULL),
('16210bf2-35cf-5e7c-8f4a-7b6002c34338', 'Сыроежка сине-желтая', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 30, 'Ровная', 'Белый, нежно-фиолетовый', 'Вогнутая', 'Фиолетовый, серо-зеленый, сине-серый, охристо-желтый', 'Пластинчатая', 'Распространена в лиственных и хвойных лесах, может расти как в горах, так и в низинах.', '/media/mushrooms/placeholder.webp', NULL),
('739c7f40-d330-5e58-9e56-fdcaddd58ff1', 'Лимацелла обмазанная', 'Лимацелла масляная, лимацелла намазанная', NULL, 'Аманитовые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Беловатый, коричневатый', 'Выпуклая', 'Беловатый, коричневатый', 'Пластинчатая', 'Растет в лесах всех типов, встречается в полях, на газонах или на обочинах дорог, болотах, на лугах и песчаных дюнах. Растёт на земле или подстилке, рассеянно или группами, не редко.', '/media/mushrooms/placeholder.webp', NULL),
('f4cb7cc9-d114-5830-b54e-f697ad5f2637', 'Моховик паразитирующий', 'Моховик паразитный', NULL, 'Болетовые', false, 'Неизвестно', true, 5, 15, 'Утолщенная вверху', 'Коричнево-желтый', 'Выпуклая', 'Коричнево-желтоватый', 'Трубчатая', 'Встречается на плодовых телах ложных дождевиков. Как правило, произрастает большими группами. Предпочитает сухие места и песчаные почвы.', '/media/mushrooms/placeholder.webp', NULL),
('29f908aa-e8e8-5aa7-a7e4-7df0aa0abd37', 'Полевик жёсткий', 'Полёвка твёрдая', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Беловато-серый', 'Выпуклая', 'Беловато-серый, грязно-желтый, бежевый', 'Пластинчатая', 'Растет на лугах, в садах, парках, на газонах, предпочитая очеловеченные ландшафты.', '/media/mushrooms/placeholder.webp', NULL),
('9696f6c5-8bed-54db-99f8-0e05b1d4ba81', 'Коллибия Азема', NULL, NULL, 'Омфалотовые', false, 'Неизвестно', true, 3, 10, 'Утолщенная внизу', 'Бело-бежевый', 'Ровная', 'Бело-бежевый', 'Пластинчатая', 'Предпочитает кислые почвы. Распространен во всех лиственных лесах.', '/media/mushrooms/placeholder.webp', NULL),
('6ef9e11d-f33c-5c5b-a65a-1f6e8edeeee6', 'Ложная лисичка рыжая', NULL, NULL, 'Гигрофоропсисовые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Оранжево-жёлтый, желтовато-оранжевый, коричневато-оранжевый, коричневый', 'Вогнутая', 'Оранжево-жёлтый, желтовато-оранжевый, коричневато-оранжевый, коричневый', 'Пластинчатая', 'Обитает в смешанных и хвойных лесах на всякого рода древесных остатках, от трухлявых пней до щепок и опилок. Возможно, широко распространён в Европе — но информации пока что недостаточно. Подобно ложной лиcичке считается условно-съедобным, с низкими пищевыми качествами.', '/media/mushrooms/placeholder.webp', NULL),
('b4088314-90dc-597c-8e4c-182271c4a2b9', 'Энтолома седая', 'Лептония седоватая', NULL, 'Энтоломовые', false, 'Неизвестно', true, 2, 7, 'Ровная', 'Желтовато-зеленый, беловатый', 'Выпуклая', 'Светло-оливковый, жёлто-зеленый, золотисто-коричневый, коричневый', 'Пластинчатая', 'Энтолома седая встречается в лиственных, смешанных, реже — в хвойных лесах. Растет под деревьями и на полянках в лесу или на травянистых участках, в мху, листовой подстилке или «нарушенной» почве (канавах, обочинах дорог, тропинках, грунтовом дорожном полотне и т.д.). Предпочитает не плодородные щелочные почвы. Встречается одиночно или же большими группами. Время плодоношения: конец августа начала сентября. Ядовитый гриб, вызывает многие опасные явления, как-то стандартные рвоту и диарею, что приводит к обезвоживанию и дисфункции кишечника, учащённое сердцебиение, нарушения со стороны печени. Летальных случаев официально не зафиксировано, но рисковать не нужно. При малейших симптомах отравления необходимо немедленно обращаться за медицинской помощью.', '/media/mushrooms/placeholder.webp', NULL),
('fe2dd49e-bf9c-5177-97d1-27dbe49b207c', 'Гигрофор чёрный', NULL, NULL, 'Гигрофоровые', false, 'Неизвестно', true, 15, 30, 'Утолщенная в центре', 'Сероватый, голубоватый, бледно-белый', 'Вогнутая', 'Коричневатый, сизо-серый, серовато-белый, голубоватый', 'Пластинчатая', 'Встречается в мшистых, сырых местах, в подлеске хвойных горных лесов. Обычный для Южной Финляндии вид. Сезон произвостания - осень. Съедобный. Деликатесный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('799d5ed8-07ad-51ca-874c-dd7bf2855635', 'Моховик моравский', 'Болет моравский', NULL, 'Болетовые', false, 'Неизвестно', true, 15, 25, 'Утолщенная внизу', 'Розоватый, оранжево-желтый', 'Выпуклая', 'Коричневатый, розоватый, оранжево-желтый, светло-кирпичный', 'Трубчатая', 'Период плодоношения моховика моравского приходится на лето и осень. Начинается он в августе и продолжается на протяжении всего сентября. Произрастает в лиственных и дубовых лесах, в лесных посадках, в прудовых дамбах. Встречается преимущественно в южных областях страны. Моховик моравский принадлежит к числу съедобных, но очень редких грибов. Принадлежит к категории заповедных грибов.', '/media/mushrooms/placeholder.webp', NULL),
('89fb3c0d-85c1-5437-946e-eee5cad8eb9f', 'Маслёнок раскрашенный', 'Маслёнок Спрэга, Болетин раскрашенный, Болетинус раскрашенный, Решетник раскрашенный', NULL, 'Маслёнковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Желтый, насыщенно-охристый', 'Выпуклая', 'Красный, кирпично-красный, бордово-коричневый, винно-красный', 'Трубчатая', 'Период плодоношения Маслёнка раскрашенного начинается в начале лета (июнь), а завершается в сентябре. Этот вид грибов предпочитает селиться на плодородных почвах, иногда – посреди мшистых участков. Зачастую их можно встретить в составе целых грибных колоний. Промысловый вид этих грибов распространён на территории Дальнего Востока в России и Сибири. Маслёнок раскрашенный, несомненно, принадлежит к числу съедобных грибов, его можно жарить, отваривать, приготавливать грибные супы. Пригоден для употребления даже без предварительного отваривания или жарения.', '/media/mushrooms/placeholder.webp', NULL),
('8302283f-25ef-59da-8222-a4e2b23bd11b', 'Млечник бурый', 'Млечник древесинный, Груздь мавроголовый', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 20, 'Ровная', 'Буро-коричневый', 'Вогнутая', 'Буро-коричневый', 'Пластинчатая', 'Млечник бурый растет с середины июля до конца сентября в хвойных и смешанных лесах, образуя микоризу, видимо, с елью, реже — с сосной. Встречается нечасто, больших скоплений не образует. Как и все негорькие младшие млечники, Lactarius lignyotus формально съедобен, но успехом не пользуется.', '/media/mushrooms/placeholder.webp', NULL),
('6904c7f9-40a0-545e-b857-2721084b7661', 'Шампиньон двукольцевой', 'Шампиньон четырехспоровый', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 15, 30, 'С юбкой', 'Белый, желтоватый, розоватый, мучной', 'Выпуклая', 'Белыый, коричневатый, мучной', 'Пластинчатая', 'С конца весны до осени растет в населенных пунктах, на дорогах, по обочинам улиц, в садах и т.п. Превосходный съедобный гриб. Его выращивают в огромных количествах.', '/media/mushrooms/placeholder.webp', NULL),
('11fe9e95-af76-5e3c-b42e-d06bb9cc4bd1', 'Лепиота щитковая', 'Лепиота щитковидная, Зонтик мелкощитовидный', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Коричневатый, белый', 'Выпуклая', 'Охряно-коричневатый, мучной, беловатый', 'Пластинчатая', 'Растет Лепиота в лиственных и хвойных лесах с лета по осень. Как правило, небольшими группами по несколько (4-6) экземпляров. Попадается не часто. В некоторые годы отмечается достаточно активное плодоношение. Лепиота щитковидная применяется в домашней кулинарии только в свежем виде.', '/media/mushrooms/placeholder.webp', NULL),
('69e97710-0687-5b28-998b-6972924b5b9b', 'Сыроежка выцветающая', 'Сыроежка выцветающая, Сыроежка красивенькая, Сыроежка красивая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 35, 'Ровная', 'Белый, желтоватый', 'Ровная', 'Кроваво-красный, бело-коричневатый, оранжеватый', 'Пластинчатая', 'Сыроежка выцветающая обычно встречается в лиственных лесах среди буковых корней. Намного реже ее можно увидеть в лесах из хвойных пород деревьев. Этот гриб предпочитает известковые почвы. Период роста сыроежки приходится на летне-осенний сезон. В пищу этот гриб можно употреблять без опаски, но особой ценности он не представляет, потому что обладает невысокими вкусовыми качествами.', '/media/mushrooms/placeholder.webp', NULL),
('b42e696d-e99d-54c5-a2f7-efba14d617d0', 'Белосвинуха трёхцветная', NULL, NULL, 'Рядовковые', true, 'Неизвестно', true, 30, 50, 'Утолщенная внизу', 'Белый', 'Выпуклая', 'Охристый, желтовато-коричневый', 'Пластинчатая', 'Редкий реликтовый вид с разорванным ареалом. В России есть находки на Алтае, в Пензенской области, в Удмуртии, Башкирии и некоторых других регионах. Также встречается в странах Прибалтики, некоторых западноевропейских странах, в Северной Америке. Везде редок. В более южных регионах водятся под дубами и буками, также есть упоминание о росте в сосняках. Условно-съедобный вид, данных не хватает ввиду редкости.', '/media/mushrooms/placeholder.webp', NULL),
('69db840c-1e2e-51a7-8f8e-2dbf859540de', 'Сухлянка двухлетняя', 'Сухлянка двулетняя, Сухлянка тёмная', NULL, 'Гименохетовые', false, 'Неизвестно', true, 5, 10, 'Утолщенная вверху', 'Коричневый, буроватый', 'Вогнутая', 'Желто-охряный, охряный, желто-коричневый, светло-коричневый, серо-бурый', 'Трубчатая', 'Растет с начала июля до поздней осени в хвойных и смешанных лесах, часто на песчаных почвах, на пожарищах, группами, не редко. Hесъедобный.', '/media/mushrooms/placeholder.webp', NULL),
('df169c95-3842-5dd7-86dc-73d1f28d23df', 'Сыроежка Морзе', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 25, 'Утолщенная внизу', 'Белый, буроватый', 'Выпуклая', 'Желтый, желто-бурый', 'Пластинчатая', 'Сыроежка Морзе растёт в лиственных, хвойных и смешанных лесах. Гриб встречается как одиночно, так и небольшими группами. Сезон плодоношения — с середины лета и до первых заморозков. Относится к категории съедобных грибов. Обычно такие грибы солят, но так как мякоть имеет небольшую горечь, в процессе приготовления требуется удаление кожицы со шляпки, а также обязательное вымачивание.', '/media/mushrooms/placeholder.webp', NULL),
('8c3ebe7a-572d-5a22-9710-6bcd897d0286', 'Чешуйчатка клейкая', 'Чешуйчатка глинисто-желтая', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Рыжевато-коричневый, желтоватый', 'Выпуклая', 'Беловатый, глинисто-желтый', 'Пластинчатая', 'Чешуйчатка клейкая считается поздним грибом. Период плодоношения начинается осенью и заканчивается при первых заморозках в ноябре. Встречается в смешанных и хвойных лесах, на останках елей и сосен. Так же встречается на почве около пней. Произрастает небольшими группами. Чешуйчатка клейкая — гриб съедобный, но из-за слизистого вида не ценится в грибной кулинарии.', '/media/mushrooms/placeholder.webp', NULL),
('774daf13-1144-5b56-8bf1-c461c3201c92', 'Катателазма императорская', 'Шампиньон императорский, Катателазма царская', NULL, 'Катателазмовые', false, 'Неизвестно', true, 45, 75, 'С юбкой', 'Беловатый, коричневатый', 'Выпуклая', 'Темно-коричневый, красновато-коричневый, желтовато-коричневоый', 'Пластинчатая', 'Найти этот удивительный гриб можно только лишь в восточной части, в горных местностях, чаще всего в Альпах. Местные встречают его с июля по середину осени. Встречается со второй половины лета и осенью в одиночку или небольшими группами на земле под хвойными деревьями. Предпочитает расти под елью Энгельмана и пихтой шершавоплодной (субальпийской). Этот гриб легко можно употреблять в пищу в любом виде. Он достаточно вкусный, без ярко выраженных оттенков, идеален как добавка к какому-то блюду.', '/media/mushrooms/placeholder.webp', NULL),
('b86fe896-9e38-5d95-b21e-55668e8a9a1c', 'Чешуйчатка слизистая', NULL, NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Желтоватый, беловатый, буроватый', 'Выпуклая', 'Коричневый, желтый, кирпичный, оранжеватый', 'Пластинчатая', 'Слизистая чешуйчатка встречается на сильно перегнившей древесине. Плодоносит с августа и по октябрь. Произрастает на почве близи прогнивших деревьев, вокруг пней и так далее. О съедобности гриба известно мало, однако гриб используетсы в медицинских исследованиях.', '/media/mushrooms/placeholder.webp', NULL),
('288b6a31-39f4-506f-bd0c-9623407fd17b', 'Паутинник ленивый', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 15, 'Ровная', 'Красный, оранжевый, ржаво-бурый', 'Ровная', 'Красный, оранжевый, ржаво-бурый', 'Пластинчатая', 'Паутинник ленивый стречается в сентябре-октябре в лесах различного типа, образуя микоризу, видимо, с деревьями разных пород, от березы до сосны. Предпочитает кислые почвы, плодоносит во влажных местах, во мхах, нередко группами разновозрастных грибов. Гриб несъедобен или слабо ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('907b57b2-8cdc-5ae7-a987-f3b2bb5412d8', 'Меланолеука полосатоножковая', NULL, NULL, 'Рядовковые', false, 'Неизвестно', true, 5, 20, 'Ровная', 'Белый, бероватый, сероватый', 'Ровная', 'Грязно-белый, охряный, коричневатый, сизый', 'Пластинчатая', 'Меланолеука полосатоножковая (Melanoleuca grammopodia) произрастает в лесах лиственного и смешанного типа, в парковых зонах, садах, борах, полянках, луговых участках местности, опушках, хорошо освещаемых травянистых местах. Иногда растёт и по обочинам дорог, группами или одиночно. Гриб съедобен, его можно употреблять в любом виде, даже в свежем, без предварительного отваривания. Меланолеука полосатоножковая хороша в отварном виде.', '/media/mushrooms/placeholder.webp', NULL),
('9c02ca2c-e702-5402-ab0d-ae0576209a33', 'Лимацелла липкая', NULL, NULL, 'Аманитовые', false, 'Неизвестно', true, 25, 50, 'Ровная', 'Красновато-коричневый, темно-кирпичный', 'Выпуклая', 'Бело-желтоватый, бледно-коричневатый, красновато-коричневый', 'Пластинчатая', 'Микоризная или сапробная, растёт в одиночку или небольшими группами в лесах разного типа, под деревьями лиственных или хвойных пород. Встречается очень редко.Сезон плодоношения - лето-осень. Точных данных о распространении нет. Известно, что подтверждённые находки Лимацеллы липкой были в Северной Америке. Данных о ядовитости нет.', '/media/mushrooms/placeholder.webp', NULL),
('eb124ef0-571d-53ec-b931-01fdbf12719b', 'Мухомор Баттарры', 'Поплавок Баттарры, Поплавок умброво-желтый', NULL, 'Аманитовые', false, 'Неизвестно', true, 8, 20, 'Утолщенная внизу', 'Беловатый, пыльно-серый', 'Выпуклая', 'Серо-коричневый, коричневатый, мучной, грязно-белый', 'Пластинчатая', 'Растет с июня по октябрь, обильно, в хвойных и смешанных лесах. Образует микоризу с елями, пихтами и ​​соснами. Предпочитает кислые почвы. Считается съедобным грибом с низкими вкусовыми качествами. Рекомендуется предварительное отваривание.', '/media/mushrooms/placeholder.webp', NULL),
('88df576a-99d7-5664-9c0e-8137c1b851df', 'Маслёнок примечательный', 'Болетин примечательный, Болетин нарядный, Фускоболетинус великолепный', NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 35, 'Ровная', 'Огненно-желтый, красноватый, розовато-оранжевый', 'Ровная', 'Огненно-желтый, красноватый, розовато-оранжевый', 'Трубчатая', 'Маслёнок примечательный распространен в Северной Америке и в России, где известен в Восточной Сибири и на Дальнем Востоке. Сезон: Июль – сентябрь. Съедобный гриб.', '/media/mushrooms/placeholder.webp', NULL),
('e9225688-209a-57b2-abde-69d0a245f520', 'Гебелома недоступная', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Грязно-белый, коричневатый', 'Выпуклая', 'Рыжеватый, коричневатый, беловатый', 'Пластинчатая', 'Широко распространен во всех флористических областях России, в Сибири и на Дальнем востоке. Гебелома недоступная растет на влажных почвах различных лесов (смешанных, лиственных, хвойных), парков, скверов, заброшенных садов. Появляется в августе — сентябре. Ядовитый гриб.', '/media/mushrooms/placeholder.webp', NULL),
('a599836f-5103-5a03-95fd-0515a58a36e3', 'Волоконница земляная', 'Волоконница землисто-пластинковая', NULL, 'Волоконницевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Белый, мучноватый', 'Ровная', 'Белый, желтоватый, розоватый, фиолетовый', 'Пластинчатая', 'Волоконница земляная растёт в лиственных и хвойных лесах, среди кустарников в июле — августе. Гриб смертельно ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('f9fa3ea6-356e-5cd1-8c58-53924dc6aa0c', 'Гигрофор краснеющий', 'Гигрофор красноватый', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 35, 55, 'Утолщенная внизу', 'Белый, розоватый', 'Выпуклая', 'Розовато-беловатый, желтоватый', 'Пластинчатая', 'Найти в обычных хвойных лесах или же в смешанных Гигрофор краснеющий можно достаточно легко в августе или же в сентябре. Чаще всего он располагается под елью или сосной, с которыми соседствует. Этот гриб многие употребляют в пищу, но без охоты, особого вкуса и запах он не имеет, хорош в качестве дополнения.', '/media/mushrooms/placeholder.webp', NULL),
('04351042-5301-5d52-8b9a-6ecbc3f9c080', 'Сыроежка цельная', 'Сыроежка замечательная, Сыроежка безупречная, Сыроежка буро-красная', NULL, 'Сыроежковые', false, 'Неизвестно', true, 30, 60, 'Утолщенная внизу', 'Белый', 'Выпуклая', 'Кровяно-красный, оливково-желтый, буроватый', 'Пластинчатая', 'Гриб растет группами в горных хвойных лесах, на известковых почвах. Сезон - лето-осень (июль — октябрь). Гриб съедобен и принадлежит к 3-й категории. Применяют его свежим и соленым.', '/media/mushrooms/placeholder.webp', NULL),
('18097755-ff00-52da-b923-0acd691f04d4', 'Рыжик японский', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 25, 'Утолщенная вверху', 'Грязно-белый, красноватый, розоватый', 'Вогнутая', 'Розоватый, оранжевый, красный', 'Пластинчатая', 'Гриб встречается в хвойных и смешанных лесах, а также под цельнолистной пихтой. Время его распространения – сентябрь или октябрь. Ареал распространения – Приморский край (южная часть), Япония. Этот вид полностью съедобен.', '/media/mushrooms/placeholder.webp', NULL),
('e0853578-883f-5c84-9a9f-b91f9de52f98', 'Мицена розовая', NULL, NULL, 'Миценовые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Белый, розовый, беловатый', 'Выпуклая', 'Розовый, красноватый, бледно-розовый', 'Пластинчатая', 'Обильное плодоношение мицены розовой приходится на лето и осень. Начинается оно в июле, а завершается – в ноябре. Грибы мицены розовые поселяются посреди опавшей старой листвы, в лесах смешанного и лиственного типа. Чаще всего гриб этого вида поселяется под дубами или буками. Встречается одиночно или небольшими группами. Данные о съедобности мицены розовой у разных специалистов-микологов противоречивы. Некоторые учёные говорят, что данный гриб вполне съедобен, другие говорят о его слабой ядовитости. Скорее всего, гриб мицена розовая всё же ядовит, поскольку в его составе содержится элемент мускарин.', '/media/mushrooms/placeholder.webp', NULL),
('83a2e323-ec9f-5aa3-b7ad-d365de519c24', 'Паутинник бело-фиолетовый', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 15, 35, 'Утолщенная внизу', 'Фиолетовый, беловатый, ржавый', 'Выпуклая', 'Лилово-серебристый, беловато-сиреневый, охряный, желто-бурый, грязно-беловатый', 'Пластинчатая', 'Паутинник бело-фиолетовый обитает с конца августа до конца сентября в хвойных, смешанных и лиственных лесах (с березой, дубом), на влажной почве, небольшими группами и одиночно, не часто. Паутинник бело-фиолетовый — съедобный гриб низкого качества (по некоторым оценкам условно-съедобный), используется свежим (отваривание около 15 минут) во вторых блюдах, соленым, маринованным.', '/media/mushrooms/placeholder.webp', NULL),
('1b8e0f7e-ea53-599b-8cf9-dd785cfbe32a', 'Сыроежка золотистая', 'Сыроежка золотисто-красная', NULL, 'Сыроежковые', true, 'Неизвестно', true, 15, 25, 'Утолщенная вверху', 'Белый, лимонно-жёлтый, светло-охряный', 'Вогнутая', 'Кирпично-красный, красно-оранжевый, медно-красный, ярко-жёлтый, оранжево-жёлтый, жёлтый', 'Пластинчатая', 'Растёт в хвойных и лиственных лесах обоих полушарий. Предположительно, образует микоризу с дубом и берёзой, а их хвойных — с елью, сосной и пихтой. Встречается как одиночно, так и небольшими группами. Плодоносит с середины лета (июль) до середины осени, ежегодно, часто. Сыроежка золотисто-красная относится к съедобным грибам с отличным вкусом, но в старых справочниках отнесена к грибам III категории.', '/media/mushrooms/placeholder.webp', NULL),
('f24ab9c6-6c93-5622-907b-5bba991647c4', 'Сыроежка берёзовая', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, желтоватый', 'Ровная', 'Сиренево-розовый, желтоватый, кремовый', 'Пластинчатая', 'Описываемый вид широко распространён на территории Северной Европы. Берёзовые сыроежки получили своё название за произрастание в берёзовых лесах. Кроме того, грибы этого вида можно встретить также в смешанных хвойно-лиственных лесах, где растёт много берёз. Сыроежки берёзовые любят расти во влажных местах, иногда встречаются в болотистых местностях, на сфагнуме. Сыроежка берёзовая принадлежит к числу условно-съедобных грибов, но некоторые микологи относят её к категории несъедобных. Употребление грибов этого вида в свежем виде может приводить к лёгким желудочно-кишечным отравлениям.', '/media/mushrooms/placeholder.webp', NULL),
('4e64412c-e296-5add-8f76-7cc2ffdd99be', 'Груздь сосочковый', 'Млечник сосочковый, Груздь крупный', NULL, 'Сыроежковые', false, 'Неизвестно', true, 8, 20, 'Ровная', 'Сероватый, мучной, грязно-белый', 'Ровная', 'Голубовато-серый, коричнево-серый, тёмно-серо-бурый, фиолетово-розоватый', 'Пластинчатая', 'Наиболее активное плодоношение млечника сосочкового приходится на период с августа по сентябрь. Гриб этого вида предпочитает расти в лесах хвойного и смешанного типов, а также в лиственных лесах. Любит песчаные грунты, произрастает только в группах и поодиночке не встречается. Его можно встретить в северных умеренных областях страны. Груздь сосочковый принадлежит к категории условно-съедобных грибов, употребляется преимущественно в солёном виде. Однако во многих зарубежных источниках указывается, что сосочковый млечник является несъедобным грибом', '/media/mushrooms/placeholder.webp', NULL),
('923035f1-12ad-5763-848c-fde3effea713', 'Волоконница разорванная', NULL, NULL, 'Волоконницевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Бурый, рыжеватый, красновато-бурый', 'Выпуклая', 'Желто-бурый, светло-коричневый', 'Пластинчатая', 'Растёт в сыроватых лесах по краям дорог и канав в июле — сентябре. Гриб смертельно ядовит. Симптомы отравления, как при употреблении волоконницы Патуйяра.', '/media/mushrooms/placeholder.webp', NULL),
('8c547a84-caf1-52e2-8480-32daa9760d35', 'Порфировик порфировоспоровый', 'Порфирелл, Боровик пурпуровоспоровый, Порфировик ложноберезовиковый', NULL, 'Болетовые', false, 'Неизвестно', true, 25, 55, 'Утолщенная внизу', 'Серо-коричневый, грязно-оранжевый', 'Выпуклая', 'Серо-коричневый, грязно-оранжевый', 'Трубчатая', 'Произрастает в широколиственных, реже хвойных лесах в Европе, Азии и Северной Америке. В бывшем СССР отмечен там же, где шишкогриб хлопьеножковый (в горных районах, в хвойных лесах, летом и осенью), а также на юго-западе Украины и в горном лесу южной Киргизии. На юге Дальнего Востока встречается еще несколько видов этого рода. Съедобен, но неценный. Гриб низкого качества, в пищу употребляется редко.', '/media/mushrooms/placeholder.webp', NULL),
('ccada3ac-4288-501e-a080-56baef0cd645', 'Паутинник чешуйчатый', NULL, NULL, 'Паутинниковые', false, 'Неизвестно', true, 5, 15, 'Утолщенная внизу', 'Серо-коричневатый, бледно-фиолетовый, бледно-бурый', 'Выпуклая', 'Бледно-бурый, коричнево-бурый,, буроватый, лиловый', 'Пластинчатая', 'Паутинник чешуйчатый обитает с конца августа до конца сентября в хвойных, лиственных и смешанных (с березой) лесах, во влажных местах, во мху, около болот, группами и одиночно, не редко. Паутинник чешуйчатый — Съедобный гриб среднего качества, используется свежим (отваривание около 15 минут, запах вываривается) во вторых блюдах, соленым, маринованным (лучше одни шляпки).', '/media/mushrooms/placeholder.webp', NULL),
('cfa45500-9b4a-500e-8df2-6cf52c5b27c2', 'Гигрофор ранний', 'Гигрофор мартовский, Снежный гриб', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Серебряный, белый, пыльно-серый', 'Выпуклая', 'Светло-серый, свинцово-серый, черноватый', 'Пластинчатая', 'Редкий вид, встречается местами обильно. Растет в лиственных и хвойных лесах, в основном в горах, под буками. Ранний вид, иногда встречается под снегом во время весенней оттепели. Хороший съедобный гриб, который появляется один из первых.', '/media/mushrooms/placeholder.webp', NULL),
('7d6b139a-1f81-50af-90d8-ebea40de4b26', 'Галерина моховая', NULL, NULL, 'Гименогастровые', false, 'Неизвестно', true, 1, 2, 'Ровная', 'светло-желтый', 'Выпуклая', 'медово-желтый, светло-бурый', 'Пластинчатая', 'Растет небольшими группами во мху и на полусгнивших бревнах, остатках мертвой древесины. Встречается в хвойных и смешанных лесах в Европе и Северной Америке.', '/media/mushrooms/placeholder.webp', NULL),
('b16742be-8fb0-5fb0-beff-a1c3a97a7ff9', 'Шампиньон изящный', 'Шампиньон розовопластинковый', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 4, 5, 'Утолщенная внизу', 'желтовато-белый', 'Выпуклая', 'серо-желтый, розоватый', 'Пластинчатая', 'Растет поодиночке и группами с середины июля до конца сентября в лиственных и смешанных лесах, а также на плодородных почвах в садах и огородах. Растет всегда среди травы. Иногда его находят на газонах, лужайках больших парков.', '/media/mushrooms/placeholder.webp', NULL),
('1e378f98-2283-5d32-accc-5dd252e61556', 'Мицена колпаковидная', 'Мицена серо-розовая, Мицена колпачковидная', NULL, 'Миценовые', false, 'Неизвестно', true, 1, 6, 'Утолщенная внизу', 'беловатый, бледно-серый, кремоватый, кремово-желтоватый', 'Выпуклая', 'буро-серый, серо-коричневый, рыжевато-коричневый, бледно-коричневый', 'Пластинчатая', 'Растет на хорошо разложившихся бревнах и пнях, но нередко вырастает из «подземной», закопанной древесины и выглядит наземной. Может расти на стволах и корнях живых, ослабленных деревьев.', '/media/mushrooms/placeholder.webp', NULL),
('2680c58c-5680-5fd7-93db-cf4efcbcc469', 'Масленок рыже-красный', 'Масленок тридентский', NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 25, 'Утолщенная внизу', 'желтовато-оранжевый', 'Выпуклая', 'желтовато-оранжевый, оранжево-красноватый', 'Трубчатая', 'Известен в Европе, особенно в Альпах. В России — в Западной Сибири, в хвойных лесах Алтая. Любит богатую известью почву. Встречается очень редко.', '/media/mushrooms/placeholder.webp', NULL),
('418b4e53-c4eb-5400-947b-8853e4ea38e5', 'Рыжик полукрасный', 'Рыжик красный сосновый', NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 25, 'Утолщенная вверху', 'оранжевый, оранжево-розовый, зеленоватый, оранжево-красный, охряный', 'Выпуклая', 'оранжевый, оранжево-красный, охряный', 'Пластинчатая', 'Встретить можно в сосновых и смешанных (с сосной) лесах и парковых зонах. Предпочитает известковые почвы. Растёт одиночно или небольшими группами, с июля по октябрь, не обильно.', '/media/mushrooms/placeholder.webp', NULL),
('00c315eb-1380-5d8d-afb3-796f324835de', 'Сморчок съедобный', 'Сморчок настоящий, Сморчок съедобный', NULL, 'Сморчковые', false, 'Неизвестно', true, 15, 30, 'Утолщенная внизу', 'беловатый, желтоватый, кремовый, буроватый', 'Выпуклая', 'желто-бурый, бурый', 'Лабиринтовидная', 'Сморчок съедобный распространён по всей умеренной зоне Северного полушария — в Евразии вплоть до Японии и в Северной Америке, а также в Австралии и на Тасмании. Произрастает в хорошо освещенных местах на плодородной, богатой известью почве — от низменностей и пойм рек до склонов гор. Обычно встречается в лесах на более или менее плодородной почве под лиственными деревьями, чаще в травянистых, хорошо защищенных местах.', '/media/mushrooms/placeholder.webp', NULL),
('51445639-d802-574e-afc8-847c7945093d', 'Лепиота Бребиссона', NULL, NULL, 'Шампиньоновые', false, 'Неизвестно', true, 3, 5, 'Ровная', 'палевый, пурпурно-фиолетовый', 'Выпуклая', 'беловатый, беловато-коричневый', 'Пластинчатая', 'Можно встретить не только в лесистой местности, но и в степях, на полянках, в парковых и лесопосадочных полосах, и даже – пустынных местностях. Чаще всего плодовые тела вырастают посреди старой опавшей листвы, на отмершей древесине или перегное.', '/media/mushrooms/placeholder.webp', NULL),
('33e19895-bbcd-5114-9591-df3442f4bdc2', 'Млечник шиповатый', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 4, 8, 'Ровная', 'розовато-бежевый', 'Вогнутая', 'розово-красный', 'Пластинчатая', 'Млечник шиповатый встречается в августе-сентябре в лиственных и смешанных лесах, микоризуясь с березой.', '/media/mushrooms/placeholder.webp', NULL),
('a32ae4f5-cf16-5d1d-9404-737cd5d8e1f5', 'Паутинник изменчивый', 'Паутинник разноцветный, Паутинник кирпично-коричневый клейкий', NULL, 'Паутинниковые', false, 'Неизвестно', true, 10, 30, 'Утолщенная внизу', 'беловатый', 'Выпуклая', 'рыжий, оранжево-коричневатый, красно-коричневый', 'Пластинчатая', 'Растет с июля до конца сентября в хвойных и широколиственных лесах, встречается в более южных и восточных регионах.', '/media/mushrooms/placeholder.webp', NULL),
('b1c12657-a5c7-5659-b538-43a1490f5502', 'Говорушка желобчатая', 'Говорушка сероватая, Говорушка Ланге', NULL, 'Трихоломовые', false, 'Неизвестно', true, 2, 5, 'Ровная', 'сероватый, беловатый', 'Вогнутая', 'серовато-коричневый, серовато-белый', 'Пластинчатая', 'Обычно произрастает группами в сосновых лесах. Время произрастания ноябрь- январь. Предпочитает сухие хвойные разреженные леса вплоть до пустошей вереска.', '/media/mushrooms/placeholder.webp', NULL),
('54788b4e-fb3d-513a-9642-c1610cd555cc', 'Лисичка горбатая', 'Кантареллюля бугорковая', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 2, 7, 'Ровная', 'беловатый, сероватый, серовато-желтоватый, желтовато-коричневый', 'Вогнутая', 'бледно-серый, желтовато-коричневый, дымчато-серый, зеленовато-сизый', 'Пластинчатая', 'Обитает в хвойных, преимущественно сосновых и смешанных с сосной лесах. Часто растет на торфяных или песчаных почвах, обочинах лесных дорог.', '/media/mushrooms/placeholder.webp', NULL),
('b3be182f-eeea-56e3-af8c-4eab2a374b8e', 'Гигроцибе коническая', NULL, NULL, 'Гигрофоровые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'желтый, оранжевый', 'Выпуклая', 'оранжевый, желтоватый, красноватый', 'Пластинчатая', 'Встречается преимущественно в редких молодых посадках, вдоль дорог и на вересковых пустошах. Произрастает среди травянистых ландшафтов: на лугах, пастбищах, полянах и так далее. В лесах встречается реже.', '/media/mushrooms/placeholder.webp', NULL),
('c2e911c3-1932-5445-9b4d-f8a44310ae27', 'Стробилюрус съедобный', 'Стробилурус сочный', NULL, 'Физалакриевые', false, 'Неизвестно', true, 1, 3, 'Ровная', 'желто-коричневый, охряный', 'Выпуклая', 'светло-коричневый, темно-коричневый', 'Пластинчатая', 'Стробилюрус съедобный встречается исключительно в еловых, или смешанных с елью лесах. Произрастает на еловых шишках, проросших в почву и шишках, лежащих на земле в местах повышенной влажности.', '/media/mushrooms/placeholder.webp', NULL),
('90715f36-694a-5ef1-b76b-122221d9131f', 'Лопастник ямчатый', 'Лопастник ямчатый, Лопастник ямчатый', NULL, 'Гельвелловые', false, 'Неизвестно', true, 10, 15, 'Утолщенная внизу', 'серый, темно-серый', 'Выпуклая', 'темно-серый', 'Гладкая', 'Произрастает на почвах в лесу хвойного и лиственного типа, преимущественно группами.', '/media/mushrooms/placeholder.webp', NULL),
('0abb867a-c1fc-54b1-850a-e5926d67b5aa', 'Псевдоговорушка бокаловидная', 'Говорушка бокаловидная', NULL, 'Трихоломовые', false, 'Неизвестно', true, 3, 6, 'Ровная', 'темно-серый, серо-коричневый', 'Вогнутая', 'серовато-коричневатый', 'Пластинчатая', 'Распространен с начала августа до конца сентября в хвойных и смешанных лесах, на подстилке и гниющей древесине, одиночно и группами, не часто.', '/media/mushrooms/placeholder.webp', NULL),
('eb94c22a-4a75-5fc6-ad2a-13c389ac10fd', 'Маслёнок сибирский', NULL, NULL, 'Маслёнковые', false, 'Неизвестно', true, 10, 15, 'Утолщенная внизу', 'серно-желтый, рыже-бурый', 'Выпуклая', 'оливково-желтый, грязно-серножелтый, желто-оливковый', 'Трубчатая', 'Растет в хвойно-широколиственных и хвойных лесах под кедром, встречается часто, в больших количествах, в августе-сентябре.', '/media/mushrooms/placeholder.webp', NULL),
('2c03dd41-8e7e-59f9-aa6a-3f1f1676a523', 'Псатирелла бархатистая', 'Лакримария бархатистая, Лакримария войлочная', NULL, 'Псатирелловые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'грязно-белый, бело-желтый', 'Выпуклая', 'коричневато-рыжий, жёлто-бурый, охряно-коричневый', 'Пластинчатая', 'Можно встретить в смешанных, лиственных и открытых местах, на почвах (чаще – песчаных), в траве, около обочин, на сгнившей древесине, возле лесных тропинок и дорог, в парках и скверах. Встретить грибы такого вида в России можно не часто. Бархатистые псатиреллы произрастают группами или одиночно.', '/media/mushrooms/placeholder.webp', NULL),
('df52a7ef-9dba-5f46-acf7-ebe13e6d824b', 'Мицена нитконогая', 'Мицена нитевидноножковая', NULL, 'Миценовые', false, 'Неизвестно', true, 1, 2, 'Ровная', 'коричневатый, серый, светло-серый', 'Выпуклая', 'сероватый, тёмно-коричневый, серо-коричневый', 'Пластинчатая', 'Предпочитает произрастать в лесах смешанного, хвойного и лиственного типа, на плодородных почвах, опавших листьях и хвое. Иногда этот вид грибов можно встретить на стволах деревьев, укрытых мхом, а также – на подгнивающей древесине.', '/media/mushrooms/placeholder.webp', NULL),
('b711cace-c667-58e3-a915-63fcc68dfc88', 'Сыроежка синяя', 'Сыроежка лазуревая', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'белый, грязно-белый, синевато-белый, серо-синеватый', 'Вогнутая', 'сине-фиолетовый', 'Пластинчатая', 'Растет в лесах хвойных пород, главным образом в ельниках, целыми гнездами. Встречается в средней полосе европейской части России, Прибалтике.', '/media/mushrooms/placeholder.webp', NULL),
('0f86c6ee-f6c6-53eb-b67c-6539f58d9783', 'Строфария горнеманна', 'Строфария Хорнеманна', NULL, 'Строфариевые', false, 'Неизвестно', true, 10, 30, 'Утолщенная вверху', 'белый, желтоватый', 'Выпуклая', 'красно-коричневый, желто-серый,', 'Пластинчатая', 'Встречается в смешанных и хвойных лесах на мертвой гниющей древесине. Иногда у основания пней лиственных пород деревьев. Произрастает не часто, небольшими группами.', '/media/mushrooms/placeholder.webp', NULL),
('fa4e0d98-b37e-5195-9f2c-6a2b2eccfb73', 'Сыроежка турецкая', NULL, NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'белый, розоватый', 'Вогнутая', 'лиловый, фиолетовый, фиолетово-бурый', 'Пластинчатая', 'Распространена на хвойных лесах Европы. Способна образовывать микоризу с пихтой и елью. Встречается небольшими группами или одиночно, преимущественно в сосновых и еловых лесах.', '/media/mushrooms/placeholder.webp', NULL),
('a3575b60-6519-5a51-a338-5d69b0b811b7', 'Мухомор ярко-жёлтый', 'Мухомор соломенно-жёлтый', NULL, 'Аманитовые', false, 'Неизвестно', true, 5, 15, 'Утолщенная внизу', 'беловатый, желтоватый', 'Выпуклая', 'охристо-жёлтый', 'Пластинчатая', 'Сезон конец весны — осень.', '/media/mushrooms/placeholder.webp', NULL),
('becad3c9-2c32-5e5e-9593-5573205c8a49', 'Агроцибе эребия', 'Полёвка тёмная', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 10, 'С юбкой', 'серо-коричневатый', 'Выпуклая', 'темно-коричневый, буро-каштановый', 'Пластинчатая', 'Распространен со второй половины июня до осени, в смешанных и лиственных лесах (с березой), на краю леса, вне леса, у дорог, в парках, в траве и на голой почве, группой, редко.', '/media/mushrooms/placeholder.webp', NULL),
('f5c24b77-2455-514d-9fef-69d9cf7f272b', 'Чешуйчатка гаревая', 'Чешуйчатка углелюбивая, Фолиота гаревая', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'грязно-желтый', 'Выпуклая', 'оранжево-коричневый', 'Пластинчатая', 'Произрастает на старых кострищах и гарях, на обгоревшей древесине.', '/media/mushrooms/placeholder.webp', NULL),
('8422a435-ce55-5d6c-ac11-1c4463152e54', 'Сморчок полусвободный', NULL, NULL, 'Сморчковые', false, 'Неизвестно', true, 15, 20, 'Утолщенная внизу', 'желтоватый', 'Выпуклая', 'коричневый', 'Лабиринтовидная', 'Произрастает в лесистых местностях, садах, рощах, парках, на опавших листьях и прошлогодней растительности, или прямо на поверхности грунта. Встретить этот вид можно не часто.', '/media/mushrooms/placeholder.webp', NULL),
('1a64bc79-a580-59b9-b479-49e0bba22aa6', 'Мицена молочная', NULL, NULL, 'Миценовые', false, 'Неизвестно', true, 3, 5, 'Ровная', 'Серый, серо-коричневатый, голубоватый', 'Выпуклая', 'Серый, серо-коричневатый, голубоватый', 'Пластинчатая', 'Обитает с начала лета и до конца грибного сезона в лесах всех видов, растет в присутствии листового или хвойного опада. Эта мицена относится к съедобным грибам. Но гастрономического интереса не представляет никакого, так как мелкая, тонкая и малообильная. Более того, имеется много шансов ее попутать с другими миценами, часть из которых не только несъедобна, а и ядовита.', '/media/mushrooms/placeholder.webp', NULL),
('1920f453-a2f5-5b44-8e45-cd5124ad0ae0', 'Агроцибе стоповидный', 'Полёвка стоповидная, Полевик стоповидный', NULL, 'Строфариевые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Светло-коричневый, светло-желтый', 'Выпуклая', 'Охристый, светло-коричневый, светло-желтый, буро-коричневый', 'Пластинчатая', 'В основном встречается на пастбищах, лугах и вырубках, заросших травой, — в гористых и холмистых местностях. Сезон - лето-осень. Несъедобный.', '/media/mushrooms/placeholder.webp', NULL),
('016eb81d-e2a6-5da4-ac5c-ac7330bf5b15', 'Млечник чахлый', 'Груздь чахлый, Груздь нежный', NULL, 'Сыроежковые', false, 'Неизвестно', true, 5, 15, 'Ровная', 'Охристо-кирпичный, рыжий, светло-рыжий', 'Вогнутая', 'Охристо-кирпичный, рыжий, светло-рыжий', 'Пластинчатая', 'Млечник чахлый произрастает на мшистых поверхностях, во влажных и сырых местах. Эту разновидность гриба из семейства Сыроежковых можно встретить в лиственных и смешанных лесах. Период плодоношения вида начинается в июле, и продолжается до сентября. Является условно-съедобным грибом, его чаще употребляют в пищу в солёном виде.', '/media/mushrooms/placeholder.webp', NULL),
('f9f23e6c-ac45-537d-ae39-cfcc4b8d52ae', 'Млечник голубой', 'Синий рыжик, Синий груздь, Синий молочный гриб', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 25, 'Ровная', 'Джинсово-синий, серебристо-белый', 'Вогнутая', 'Серебристо-голубой, бледно-серый', 'Пластинчатая', 'Растёт группами, иногда одиночно, как в лиственных, так и в хвойных лесах, поскольку может образовывать микоризу и с теми, и с другими. Чаще встречается с дубами и соснами. Любит влажные места, например: поймы, которые недавно были затоплены. Хороший съедобный гриб. Можно есть сырым, например, нарезав в салат для улучшения цвета и придания особого пикантного островатого вкуса. Однако, в большинстве случаев, его готовят различными способами.', '/media/mushrooms/placeholder.webp', NULL),
('fe3b51d5-5f11-51d5-b63c-0c06b973c185', 'Лиофиллум симедзи', 'Хон-симедзи, Лиофиллюм симедзи', NULL, 'Лиофилловые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Белый, сероватый', 'Выпуклая', 'Серый, коричневатый, серовато-коричневый, грязновато-серый, желтовато-серый', 'Пластинчатая', 'Растёт на почве, подстилке, предпочитает сухие сосновые леса. Активное плодоношение приходится на август — сентябрь. Лиофиллум симедзи растёт небольшими сростками и группами, реже одиночно. Распространён по всей Евразии от Японского архипелага до Скандинавии. Гриб съедобен. В Японии Лиофиллум симедзи, называемый там Хон-симедзи, считается деликатесным грибом', '/media/mushrooms/placeholder.webp', NULL),
('0b91bbce-3316-51b8-abc3-0ed9f7111769', 'Млечник липкий', 'Млечник слизистый, Млечник серо-зелёный, Груздь серо-зелёный', NULL, 'Сыроежковые', false, 'Неизвестно', true, 15, 25, 'Ровная', 'Сероватый, грязно-беловатый', 'Вогнутая', 'Светло-коричневатый, грязно-белый, сероватый, грязно-зеленоватый', 'Пластинчатая', 'Образует микоризу с лиственными деревьями, особенно с буком и берёзой. Гриб встречается обычно небольшими группами в лиственных лесах, часто в гористой местности. Распространён в Европе и Азии. Иногда считается условно-съедобным и пригодным для соления, но возможные его токсические свойства не изучены, поэтому собирать не рекомендуется.', '/media/mushrooms/placeholder.webp', NULL),
('bbbd7842-9ae0-51e1-8236-364aed83fc53', 'Млечник беззоновый', 'Млечник безонный', NULL, 'Сыроежковые', false, 'Неизвестно', true, 10, 20, 'Ровная', 'Песочный, бледно-коричневый', 'Ровная', 'Песочный, бледно-коричневый, бурый, коричневатый', 'Пластинчатая', 'В России растет в европейской части, а также в южных районах и областях (Краснодарский край). Обитает обычно в лесах, где растут дубы, так как образует микоризу именно с этим деревом. Сезон: июль – сентябрь. В неурожайные годы грибов не бывает. Млечник беззоновый относится к съедобным грибам. В пищу употребляют в соленом и маринованном виде. Специалисты рекомендуют употреблять в пищу только молодые грибы.', '/media/mushrooms/placeholder.webp', NULL),
('06ee5a66-fd99-596e-90f7-42272eea8791', 'Гебелома корневая', 'Гебелома корневидная, Гифолома укорененная, Гифолома укореняющаяся', NULL, 'Гименогастровые', false, 'Неизвестно', true, 10, 20, 'Утолщенная внизу', 'Светло серый, коричневатый', 'Выпуклая', 'Серо-коричневый, буроватый', 'Пластинчатая', 'Встречается с середины августа до начала октября в лесах различного типа, образуя микоризу с лиственными деревьями; нередко гебелому корневую можно найти в местах с поврежденным верхним слоем почвы — в канавках и ямах, около нор грызунов. В удачные для себя годы может попадаться очень большими группами, в неудачные — вовсе отсутствовать. Несъедобен, хотя и не ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('3389e099-339b-5472-8e57-6c036ede96d4', 'Паутинник болотный', 'Паутинник прибрежный, Паутинник ивовый, Паутинник топяной', NULL, 'Паутинниковые', false, 'Неизвестно', true, 5, 10, 'Ровная', 'Желтовато-оранжевый, светло-красный', 'Выпуклая', 'Медно-оранжевый, кирпично-красный', 'Пластинчатая', 'Растет на влажной почве рядом с ивами или (гораздо реже) с ольхой, чаще всего по краям озёр или вдоль рек, а также на болотах. Предпочитает низменности, но встречается и в альпийских регионах в густых ивовых зарослях. Прямые данные о съедобности отсутствуют, однако, учитывая, что гриб близок к ядовитым родственникам подрода Dermocybe, скорее всего он также ядовит.', '/media/mushrooms/placeholder.webp', NULL),
('5bd2e85f-5d35-5c4d-8d01-888a3133e472', 'Гигрофор луговой', 'Куфофилл луговой, Гигроцибе луговое', NULL, 'Гигрофоровые', false, 'Неизвестно', true, 15, 30, 'Утолщенная вверху', 'Бледно-белый, желтоватый', 'Выпуклая', 'Бледно-оранжевый, ржавый', 'Пластинчатая', 'Зачастую встречается в травах на умеренно влажных или сухих лугах, пастбищах, редко в травянистых светлых лесах. Сезон - конец лета – осень. Съедобен.', '/media/mushrooms/placeholder.webp', NULL),
('68bd9ec6-f2b5-5dfc-a282-7f5e35080e95', 'Лепиота вздутоспоровая', 'Лепиота чешуйчатая желтоватая, Зонтик вздутоспоровый, Чешуйница вздутоспоровая', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 3, 8, 'С юбкой', 'Грязно-белый, рыже-коричневатый', 'Ровная', 'Бело-желтоватый, бежевый, рыжеватый', 'Пластинчатая', 'Лепиота вздутоспоровая встречается редко в августе-сентябре в лесах различного типа, появляясь обычно маленькими группами. По одним данным, гриб съедобен. По другим — несъедобен или даже смертельно ядовит. Во всех источниках сообщается, что пищевые качества представителей рода Lepiota изучены слабо.', '/media/mushrooms/placeholder.webp', NULL),
('73c126fb-3079-5c37-a040-e54ae5395bda', 'Цезарский гриб дальневосточный', 'Мухомор цезаревидный, Кесарев дальневосточный', NULL, 'Аманитовые', false, 'Неизвестно', true, 15, 35, 'С юбкой', 'Желтый, желтовато-оранжевый, охристо-желтый', 'Выпуклая', 'Красно-оранжевый, огненно-красный, оранжево-киноварный', 'Пластинчатая', 'Растёт одиночно и большими группами, в летне-осенний период. Образует микоризу с лиственными деревьями, предпочитает дуб, растёт под лещиной и берёзой сахалинской. Встречается в дубовых лесах Камчатки, характерен для всего Приморского края. Замечен в Амурской области, Хабаровском крае и на Сахалине, в Японии, Корее, Китае. Гриб съедобен и очень вкусен.', '/media/mushrooms/placeholder.webp', NULL),
('72014c0b-af86-5374-8895-686ac2d8f8a8', 'Шампиньон паровой', 'Шампиньнон тепличный', NULL, 'Шампиньоновые', false, 'Неизвестно', true, 20, 35, 'С юбкой', 'Розоватый, грязно-белый', 'Выпуклая', 'Коричневый, розоватый', 'Пластинчатая', 'Паровой шампиньон плодоносит преимущественно в первой половине осени, встречается в смешанных лесах, а также – в садах, где почва насыщена органическими питательными компонентами. Шампиньон паровой съедобен, принадлежит к третьей категории. Можно употреблять в пищу в любом виде.', '/media/mushrooms/placeholder.webp', NULL);

