VALUES
('3083eff4-4d77-5e76-bc09-2e945ad16383', '9db0ff16-7cc5-5a30-b7c3-38630c0d2085', 'Свинушка ольховая'),
('22b97249-503d-5c95-bad6-c2000dc59938', '9db0ff16-7cc5-5a30-b7c3-38630c0d2085', 'Войлочная свинушка'),
('d6cf3e9b-8861-5555-8860-9e6ae9110bae', 'edc491d5-d075-51d6-ab8d-000e0ac40e32', 'Белый гриб'),
